-- Tables
CREATE TABLE IF NOT EXISTS public."admin_contracts" (
  "id" uuid DEFAULT uuid_generate_v4() NOT NULL,
  "org_id" uuid NOT NULL,
  "location_id" uuid,
  "vendor_id" uuid,
  "service_scope" text NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date,
  "monthly_value" numeric(10,2),
  "notice_period_days" integer DEFAULT 30,
  "status" text DEFAULT 'active'::text,
  "created_at" timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."applications" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "name" text NOT NULL,
  "domain_url" text NOT NULL,
  "api_url" text,
  "is_free" boolean DEFAULT false,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."building_cooperation_links" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "location_master_id" uuid NOT NULL,
  "admin_org_id" uuid NOT NULL,
  "cleaning_org_id" uuid,
  "maintenance_org_id" uuid,
  "cleaning_issues_to_serwis" boolean DEFAULT true NOT NULL,
  "skip_admin_triage" boolean DEFAULT false NOT NULL,
  "status" cooperation_link_status DEFAULT 'active'::cooperation_link_status NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."building_inspections" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "location_id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "inspection_type" text NOT NULL,
  "source" text NOT NULL,
  "status" text NOT NULL,
  "planned_date" date NOT NULL,
  "execution_date" date,
  "ckob_document_ref" text,
  "internal_notes" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."ckob_credentials" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "api_key_encrypted" text NOT NULL,
  "is_active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."ckob_property_mappings" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "location_id" uuid NOT NULL,
  "ckob_building_id" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."ckob_sync_logs" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "status" text NOT NULL,
  "records_processed" integer DEFAULT 0 NOT NULL,
  "error_details" jsonb,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."cleaning_catalog" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "name" text NOT NULL,
  "unit" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."cleaning_clients" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "name" text NOT NULL,
  "email" text,
  "phone" text,
  "contract_details" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."cleaning_extra_job_photos" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "extra_job_id" uuid NOT NULL,
  "uploaded_by" uuid NOT NULL,
  "storage_path" text NOT NULL,
  "source" text NOT NULL,
  "sort_order" integer DEFAULT 0 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."cleaning_extra_jobs" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "task_id" uuid NOT NULL,
  "location_id" uuid NOT NULL,
  "assigned_staff_id" uuid,
