  "origin" text NOT NULL,
  "title" text NOT NULL,
  "instructions" text,
  "work_report" text,
  "requires_photo" boolean DEFAULT false NOT NULL,
  "gps_required" boolean DEFAULT true NOT NULL,
  "qr_required" boolean DEFAULT false NOT NULL,
  "biometric_required" boolean DEFAULT false NOT NULL,
  "pay_mode" text DEFAULT 'hourly'::text NOT NULL,
  "employee_hourly_rate" numeric,
  "client_hourly_rate" numeric,
  "employee_fixed_amount" numeric,
  "client_fixed_amount" numeric,
  "applied_employee_rate" numeric,
  "applied_client_rate" numeric,
  "employee_total" numeric,
  "client_total" numeric,
  "duration_minutes" integer,
  "approval_status" text DEFAULT 'pending_review'::text NOT NULL,
  "approved_by" uuid,
  "approved_at" timestamp with time zone,
  "rejection_reason" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."cleaning_inventory" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "location_id" uuid,
  "item_name" text NOT NULL,
  "current_quantity" numeric(10,2) DEFAULT 0,
  "unit" text DEFAULT 'liters'::text,
  "min_threshold" numeric(10,2) DEFAULT 1.0,
  "last_restock_at" timestamp with time zone,
  "catalog_item_id" uuid
);
CREATE TABLE IF NOT EXISTS public."cleaning_locations" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "client_id" uuid,
  "address" text NOT NULL,
  "geo_location" geography(Point,4326),
  "geofence_radius_meters" integer DEFAULT 50,
  "square_meters" numeric(10,2),
  "access_code" text,
  "instruction_notes" text,
  "validation_config" jsonb DEFAULT '{"qr_required": true, "gps_required": true, "biometric_required": false}'::jsonb,
  "visibility_config" jsonb DEFAULT '{"public_status": false, "manager_photos": true}'::jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "qr_code_token" text DEFAULT (gen_random_uuid())::text,
  "coordinator_notes" text,
  "monthly_fee" numeric DEFAULT 0,
  "hourly_rate_cleaning" numeric DEFAULT 0,
  "hourly_rate_snow" numeric DEFAULT 0,
  "coordinator_can_view_financials" boolean DEFAULT false,
  "monthly_salary" numeric DEFAULT 0,
  "cleaning_rate" numeric DEFAULT 0,
  "snow_removal_rate" numeric DEFAULT 0,
  "google_place_id" text,
  "latitude" double precision,
  "longitude" double precision,
  "auto_notify_issues" boolean DEFAULT false,
  "client_notification_email" text,
  "location_master_id" uuid,
  "status" text DEFAULT 'active'::text,
  "is_cleaning_active" boolean DEFAULT false NOT NULL,
  "is_maintenance_active" boolean DEFAULT false NOT NULL,
  "maintenance_notes" text,
  "ticket_routing_preference" text DEFAULT 'auto_exchange'::text,
  "preferred_contractor_id" uuid,
  "place_id" text,
  "serwis_notes" text,
  "require_gps_validation_serwis" boolean DEFAULT false,
  "issue_qr_token" uuid DEFAULT gen_random_uuid(),
  "is_active_in_serwis" boolean DEFAULT true,
  "serwis_contacts" jsonb DEFAULT '[]'::jsonb,
  "admin_contacts" jsonb DEFAULT '[]'::jsonb,
  "billing_details" text,
  "access_codes" text,
  "is_admin_active" boolean DEFAULT false NOT NULL,
  "admin_compliance_score" integer DEFAULT 100,
  "name" text,
  "board_portal_token" uuid DEFAULT gen_random_uuid() NOT NULL,
  "public_report_token" uuid DEFAULT gen_random_uuid() NOT NULL,
  "c_kob_building_id" text,
  "community_id" uuid,
  "allow_anonymous_qr_reports" boolean DEFAULT true NOT NULL,
  "skip_cleaning_issue_approval" boolean DEFAULT false NOT NULL,
  "cleaning_scope_contract_id" uuid,
  "extra_work_rate" numeric DEFAULT 0 NOT NULL
);
CREATE TABLE IF NOT EXISTS public."cleaning_staff" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid,
  "full_name" text NOT NULL,
  "phone" text,
  "internal_id" text,
  "pin" text,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "notes" text,
  "emergency_contact" text,
  "emergency_phone" text,
  "status" text DEFAULT 'active'::text,
  "employment_type" text,
  "contact_email" text
);
CREATE TABLE IF NOT EXISTS public."cleaning_tasks" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "location_id" uuid,
  "assigned_staff_id" uuid,
  "status" task_status DEFAULT 'pending'::task_status,
  "priority" priority_level DEFAULT 'medium'::priority_level,
  "scheduled_at" timestamp with time zone NOT NULL,
  "started_at" timestamp with time zone,
  "completed_at" timestamp with time zone,
  "check_in_metadata" jsonb,
  "check_out_metadata" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "coordinator_notes" text,
  "staff_notes" text,
  "section_id" uuid,
  "actual_performer_id" uuid,
  "checklist" jsonb DEFAULT '{}'::jsonb,
  "task_type" task_type DEFAULT 'sop_standard'::task_type NOT NULL,
  "applied_hourly_rate" numeric(10,2),
  "total_cost" numeric(10,2),
  "is_paid" boolean DEFAULT false,
  "source_template_id" uuid,
  "scheduled_on" date GENERATED ALWAYS AS (((scheduled_at AT TIME ZONE 'UTC'::text))::date) STORED
);
CREATE TABLE IF NOT EXISTS public."cleaning_work_sessions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "org_id" uuid NOT NULL,
  "location_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "task_id" uuid,
  "started_at" timestamp with time zone NOT NULL,
  "ended_at" timestamp with time zone,
  "status" text DEFAULT 'open'::text NOT NULL,
  "close_reason" text,
  "needs_review" boolean DEFAULT false NOT NULL,
  "is_paid" boolean DEFAULT false NOT NULL,
  "check_in_lat" double precision,
  "check_in_lng" double precision,
  "check_out_lat" double precision,
  "check_out_lng" double precision,
  "check_out_distance_meters" integer,
  "remaining_tasks" integer,
  "edited_by" uuid,
  "edited_at" timestamp with time zone,
  "edit_reason" text,
  "original_started_at" timestamp with time zone,
  "original_ended_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
