  "vendor_id" uuid,
  "issue_id" uuid,
  "dispatch_id" uuid,
  "message_id" text NOT NULL,
  "from_address" text,
  "to_address" text,
  "subject" text,
  "body_text" text,
  "matched_event_type" text,
  "extracted" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "match_method" text DEFAULT 'unmatched'::text NOT NULL,
  "status" text DEFAULT 'received'::text NOT NULL,
  "error_detail" text,
  "raw_payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."vendor_email_inbound_templates" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "vendor_id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "event_type" text NOT NULL,
  "subject_pattern" text,
  "body_pattern" text NOT NULL,
  "sample_body" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE IF NOT EXISTS public."vendor_partners" (
  "id" uuid DEFAULT uuid_generate_v4() NOT NULL,
  "org_id" uuid NOT NULL,
  "name" text NOT NULL,
  "service_type" text NOT NULL,
  "contact_email" text,
  "contact_phone" text,
  "has_system_access" boolean DEFAULT false,
  "status" text DEFAULT 'active'::text,
  "created_at" timestamp with time zone DEFAULT now(),
  "dispatch_channel" text DEFAULT 'in_app'::text NOT NULL,
  "is_emergency_24h" boolean DEFAULT false NOT NULL,
  "trade_categories" text[] DEFAULT '{}'::text[] NOT NULL
);

