-- Indexes
CREATE UNIQUE INDEX IF NOT EXISTS admin_contracts_pkey ON public.admin_contracts USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS applications_domain_url_key ON public.applications USING btree (domain_url);
CREATE UNIQUE INDEX IF NOT EXISTS applications_pkey ON public.applications USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS building_cooperation_links_pkey ON public.building_cooperation_links USING btree (id);
CREATE INDEX IF NOT EXISTS building_inspections_location_id_idx ON public.building_inspections USING btree (location_id);
CREATE INDEX IF NOT EXISTS building_inspections_org_id_idx ON public.building_inspections USING btree (org_id);
CREATE INDEX IF NOT EXISTS building_inspections_org_status_planned_idx ON public.building_inspections USING btree (org_id, status, planned_date);
CREATE UNIQUE INDEX IF NOT EXISTS building_inspections_pkey ON public.building_inspections USING btree (id);
CREATE INDEX IF NOT EXISTS building_inspections_status_idx ON public.building_inspections USING btree (status);
CREATE INDEX IF NOT EXISTS ckob_credentials_org_id_idx ON public.ckob_credentials USING btree (org_id);
CREATE UNIQUE INDEX IF NOT EXISTS ckob_credentials_org_id_uq ON public.ckob_credentials USING btree (org_id);
CREATE UNIQUE INDEX IF NOT EXISTS ckob_credentials_pkey ON public.ckob_credentials USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS ckob_property_mappings_location_ckob_uq ON public.ckob_property_mappings USING btree (location_id, ckob_building_id);
CREATE INDEX IF NOT EXISTS ckob_property_mappings_location_id_idx ON public.ckob_property_mappings USING btree (location_id);
CREATE UNIQUE INDEX IF NOT EXISTS ckob_property_mappings_pkey ON public.ckob_property_mappings USING btree (id);
CREATE INDEX IF NOT EXISTS ckob_sync_logs_org_id_idx ON public.ckob_sync_logs USING btree (org_id);
CREATE UNIQUE INDEX IF NOT EXISTS ckob_sync_logs_pkey ON public.ckob_sync_logs USING btree (id);
CREATE INDEX IF NOT EXISTS ckob_sync_logs_status_created_at_idx ON public.ckob_sync_logs USING btree (status, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_catalog_pkey ON public.cleaning_catalog USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_clients_pkey ON public.cleaning_clients USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_extra_job_photos_pkey ON public.cleaning_extra_job_photos USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_extra_jobs_pkey ON public.cleaning_extra_jobs USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_extra_jobs_task_id_key ON public.cleaning_extra_jobs USING btree (task_id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_inventory_pkey ON public.cleaning_inventory USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_locations_c_kob_building_id_key ON public.cleaning_locations USING btree (c_kob_building_id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_locations_pkey ON public.cleaning_locations USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_locations_qr_code_token_key ON public.cleaning_locations USING btree (qr_code_token);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_staff_pkey ON public.cleaning_staff USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_tasks_pkey ON public.cleaning_tasks USING btree (id);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_tasks_sop_template_day_key ON public.cleaning_tasks USING btree (org_id, location_id, source_template_id, scheduled_on);
CREATE UNIQUE INDEX IF NOT EXISTS cleaning_work_sessions_one_open ON public.cleaning_work_sessions USING btree (user_id, location_id, session_kind) WHERE (status = 'open'::text);
CREATE INDEX IF NOT EXISTS cleaning_work_sessions_org_auto_idx ON public.cleaning_work_sessions USING btree (org_id, ended_at DESC) WHERE (status = 'auto_closed'::text);
