-- Functions
CREATE OR REPLACE FUNCTION private.assert_sha256_hex(p_value text, p_field text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF p_value IS NULL OR p_value !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION '% must be a lowercase 64-char SHA-256 hex digest', p_field
      USING ERRCODE = 'check_violation';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION private.begin_legal_consent(p_user_id uuid, p_source text, p_email text, p_ip_address text, p_user_agent text, p_document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_email text;
  v_ip text;
  v_ua text;
  v_ids uuid[];
  v_pending uuid[];
  v_missing uuid[];
  v_batch public.user_consent_batches%ROWTYPE;
  v_existing uuid;
  v_dispatch uuid;
  v_docs jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'LEGAL_AUTH_REQUIRED' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_source IS NULL OR p_source NOT IN ('signup_email', 'signup_oauth', 'reacceptance') THEN
    RAISE EXCEPTION 'LEGAL_SOURCE_INVALID' USING ERRCODE = 'check_violation';
  END IF;

  SELECT au.email INTO v_email
  FROM auth.users au
  WHERE au.id = p_user_id;

  v_email := NULLIF(btrim(COALESCE(v_email, p_email, '')), '');
  IF v_email IS NULL OR length(v_email) < 3 THEN
    RAISE EXCEPTION 'LEGAL_EMAIL_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;

  v_ip := NULLIF(left(btrim(COALESCE(p_ip_address, '')), 64), '');
  v_ua := NULLIF(left(btrim(COALESCE(p_user_agent, '')), 1024), '');

  SELECT ARRAY(
    SELECT DISTINCT x
    FROM unnest(COALESCE(p_document_ids, ARRAY[]::uuid[])) AS x
    WHERE x IS NOT NULL
  )
  INTO v_ids;

  IF v_ids IS NULL OR coalesce(array_length(v_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'LEGAL_DOCUMENTS_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_ids) AS i(id)
    LEFT JOIN public.legal_documents d ON d.id = i.id
    WHERE d.id IS NULL OR d.is_active IS NOT TRUE
  ) THEN
    RAISE EXCEPTION 'LEGAL_DOCUMENTS_STALE' USING ERRCODE = 'check_violation';
  END IF;

  SELECT ARRAY(
    SELECT d.id
    FROM public.legal_documents d
    WHERE d.is_active = true
      AND d.is_required = true
      AND NOT EXISTS (
        SELECT 1
        FROM public.user_consents c
        WHERE c.user_id = p_user_id
          AND c.document_id = d.id
      )
  )
  INTO v_pending;

  SELECT ARRAY(
    SELECT p
    FROM unnest(COALESCE(v_pending, ARRAY[]::uuid[])) AS p
    WHERE p <> ALL (v_ids)
  )
  INTO v_missing;

  IF coalesce(array_length(v_missing, 1), 0) > 0 THEN
    RAISE EXCEPTION 'LEGAL_REQUIRED_DOCS_MISSING' USING ERRCODE = 'check_violation';
  END IF;

  SELECT ARRAY(
    SELECT i
    FROM unnest(v_ids) AS i
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.user_consents c
      WHERE c.user_id = p_user_id
        AND c.document_id = i
    )
  )
  INTO v_ids;

  IF coalesce(array_length(v_ids, 1), 0) = 0 THEN
    SELECT c.batch_id INTO v_existing
    FROM public.user_consents c
    WHERE c.user_id = p_user_id
    ORDER BY c.accepted_at DESC
    LIMIT 1;

    SELECT d.id INTO v_dispatch
    FROM public.legal_welcome_dispatches d
    WHERE d.batch_id = v_existing
    LIMIT 1;

    RETURN jsonb_build_object(
      'already_recorded', true,
      'batch_id', v_existing,
      'dispatch_id', v_dispatch,
      'document_ids', ARRAY[]::uuid[]
    );
  END IF;

  INSERT INTO public.user_consent_batches (
    user_id, source, email, ip_address, user_agent
  )
  VALUES (
    p_user_id, p_source, v_email, v_ip, v_ua
  )
  RETURNING * INTO v_batch;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', d.id,
        'document_type', d.document_type,
        'version', d.version,
        'content', d.content,
        'content_hash', d.content_hash,
        'active_from', d.active_from
      )
      ORDER BY
        CASE d.document_type
          WHEN 'terms' THEN 1
          WHEN 'privacy' THEN 2
          ELSE 3
        END
    ),
    '[]'::jsonb
  )
  INTO v_docs
  FROM public.legal_documents d
  WHERE d.id = ANY (v_ids);

  RETURN jsonb_build_object(
    'already_recorded', false,
    'batch_id', v_batch.id,
    'accepted_at', v_batch.accepted_at,
    'email', v_batch.email,
    'ip_address', v_batch.ip_address,
    'user_agent', v_batch.user_agent,
    'source', v_batch.source,
    'document_ids', to_jsonb(v_ids),
    'documents', v_docs
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.clone_inspections_to_successor(p_from_org uuid, p_to_org uuid, p_master uuid, p_target_location_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ DECLARE n integer; BEGIN INSERT INTO public.property_inspections (location_id, location_master_id, org_id, origin_org_id, company_id, type, status, execution_date, valid_until, protocol_number, inspector_name, notes, document_url) SELECT p_target_location_id, pin.location_master_id, p_to_org, COALESCE(pin.origin_org_id, pin.org_id), COALESCE((SELECT c2.id FROM public.companies c_from INNER JOIN public.companies c2 ON c2.org_id = p_to_org AND c2.legal_entity_id IS NOT NULL AND c2.legal_entity_id = c_from.legal_entity_id WHERE c_from.id = pin.company_id LIMIT 1), pin.company_id), pin.type, pin.status, pin.execution_date, pin.valid_until, pin.protocol_number, pin.inspector_name, pin.notes, pin.document_url FROM public.property_inspections pin WHERE pin.org_id = p_from_org AND pin.location_master_id = p_master AND EXISTS (SELECT 1 FROM public.companies c WHERE c.id = pin.company_id); GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END; $function$;
CREATE OR REPLACE FUNCTION private.clone_issues_to_successor(p_from_org uuid, p_to_org uuid, p_master uuid, p_target_location_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ DECLARE n integer; BEGIN INSERT INTO public.property_issues (org_id, location_id, location_master_id, origin_org_id, description, photo_url, status, priority, category, source, reporter_name, reporter_phone, reporter_email, photos_before, photos_after, created_at) SELECT p_to_org, p_target_location_id, pi.location_master_id, COALESCE(pi.origin_org_id, pi.org_id), pi.description, pi.photo_url, pi.status, pi.priority, pi.category, pi.source, pi.reporter_name, pi.reporter_phone, pi.reporter_email, pi.photos_before, pi.photos_after, pi.created_at FROM public.property_issues pi WHERE pi.org_id = p_from_org AND pi.location_master_id = p_master; GET DIAGNOSTICS n = ROW_COUNT; RETURN n; END; $function$;
CREATE OR REPLACE FUNCTION private.community_board_apply_estate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_community_id uuid;
  v_address text;
  v_name text;
  v_estate uuid;
BEGIN
  SELECT cl.community_id, cl.address, cl.name
  INTO v_community_id, v_address, v_name
  FROM public.cleaning_locations cl
  WHERE cl.id = NEW.location_id;

  NEW.origin_label := COALESCE(
    NULLIF(btrim(COALESCE(v_address, '')), ''),
    NULLIF(btrim(COALESCE(v_name, '')), ''),
    'Budynek'
  );

  v_estate := NULL;
  IF v_community_id IS NOT NULL THEN
    SELECT em.estate_id
    INTO v_estate
    FROM public.estate_members em
    JOIN public.estates e ON e.id = em.estate_id
    WHERE em.community_id = v_community_id
      AND em.status = 'accepted'
      AND e.status = 'active'
    LIMIT 1;
  END IF;

  NEW.estate_id := v_estate;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.community_set_rpc_flag()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM set_config('app.community_rpc', '1', true);
END;
$function$;
CREATE OR REPLACE FUNCTION private.contract_belongs_to_admin_org(p_contract_org_id uuid, p_origin_org_id uuid, p_shared_with_org_ids uuid[], p_location_org_id uuid, p_admin_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    COALESCE(p_contract_org_id, p_location_org_id) IS NOT DISTINCT FROM p_admin_org_id
    OR COALESCE(p_origin_org_id, p_location_org_id) IS NOT DISTINCT FROM p_admin_org_id
    OR COALESCE(p_admin_org_id = ANY (COALESCE(p_shared_with_org_ids, '{}'::uuid[])), false);
$function$;
CREATE OR REPLACE FUNCTION private.contract_has_document(p_document_url text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT length(trim(both from COALESCE(p_document_url, ''))) > 0;
$function$;
CREATE OR REPLACE FUNCTION private.contract_in_community_scope(p_contract_community_id uuid, p_contract_location_id uuid, p_contract_location_community_id uuid, p_admin_location_id uuid, p_community_id uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    p_contract_location_id IS NOT DISTINCT FROM p_admin_location_id
    OR (
      p_community_id IS NOT NULL
      AND (
        p_contract_community_id IS NOT DISTINCT FROM p_community_id
        OR p_contract_location_community_id IS NOT DISTINCT FROM p_community_id
      )
    );
$function$;
CREATE OR REPLACE FUNCTION private.contract_eligible_for_cleaning_scope(p_contract_id uuid, p_admin_org_id uuid, p_admin_location_id uuid, p_community_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.property_contracts pc
    JOIN public.cleaning_locations loc ON loc.id = pc.location_id
    WHERE pc.id = p_contract_id
      AND private.contract_has_document(pc.document_url)
      AND private.contract_belongs_to_admin_org(
        pc.org_id,
        pc.origin_org_id,
        pc.shared_with_org_ids,
        loc.org_id,
        p_admin_org_id
      )
      AND private.contract_in_community_scope(
        pc.community_id,
        pc.location_id,
        loc.community_id,
        p_admin_location_id,
        p_community_id
      )
  );
$function$;
CREATE OR REPLACE FUNCTION private.contract_is_active(p_end_date date)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT p_end_date IS NULL OR p_end_date >= CURRENT_DATE;
$function$;
