CREATE OR REPLACE FUNCTION private.equipment_assert_active_member(p_org_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_org_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'EQUIPMENT_FORBIDDEN';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.memberships m
    WHERE m.org_id = p_org_id AND m.user_id = p_user_id AND COALESCE(m.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'EQUIPMENT_WORKER_NOT_IN_ORG';
  END IF;
END;
$function$;
