  END IF;
  RETURN v_actor;
END;
$function$;
CREATE OR REPLACE FUNCTION private.fleet_apply_placeholders(p_template text, p_vehicle text, p_date text, p_days text, p_model text, p_reg_no text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT replace(replace(replace(replace(replace(replace(replace(replace(replace(
    COALESCE(p_template, ''), '{{vehicle_model}}', COALESCE(p_model, '')),
    '{{reg_no}}', COALESCE(p_reg_no, '')), '{{expiry_date}}', COALESCE(p_date, '')),
    '{{inspection_date}}', COALESCE(p_date, '')), '{{tire_change_date}}', COALESCE(p_date, '')),
    '{vehicle}', COALESCE(p_vehicle, '')), '{date}', COALESCE(p_date, '')),
    '{days}', COALESCE(p_days, '')), '{reg_no}', COALESCE(p_reg_no, ''));
$function$;
CREATE OR REPLACE FUNCTION private.fleet_html_escape(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ SELECT replace(replace(replace(replace(replace(COALESCE(p_text, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;'); $function$;
CREATE OR REPLACE FUNCTION private.fleet_notification_html(p_body text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ SELECT '<p>' || replace(private.fleet_html_escape(p_body), E'\n', '<br/>') || '</p>'; $function$;
CREATE OR REPLACE FUNCTION private.fleet_notification_payload(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_row public.fleet_notification_dispatches%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.fleet_notification_dispatches WHERE id = p_dispatch_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'dispatch_id', v_row.id,
    'to_email', v_row.recipient_email,
    'subject', v_row.subject,
    'html', private.fleet_notification_html(v_row.body_text),
    'already_sent', v_row.status = 'sent'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.fleet_valid_email(p_email text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ SELECT p_email IS NOT NULL AND char_length(p_email) BETWEEN 3 AND 320 AND position('@' IN p_email) > 1 AND position(' ' IN p_email) = 0; $function$;
CREATE OR REPLACE FUNCTION private.enqueue_due_fleet_notifications()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  rec record; v_recipient record; v_vehicle text; v_date text; v_days text; v_subject text; v_body text;
  v_inserted integer := 0; v_skipped integer := 0; v_already integer := 0; v_had_recipient boolean;
BEGIN
  FOR rec IN SELECT * FROM public.v_active_notifications LOOP
    v_had_recipient := false;
    v_vehicle := btrim(COALESCE(rec.model, '') || ' (' || COALESCE(rec.reg_no, '') || ')');
    v_date := to_char(rec.deadline_date, 'DD.MM.YYYY');
    v_days := COALESCE(rec.days_left::text, '0');
    v_subject := NULLIF(btrim(private.fleet_apply_placeholders(rec.subject, v_vehicle, v_date, v_days, rec.model, rec.reg_no)), '');
    v_body := NULLIF(btrim(private.fleet_apply_placeholders(rec.body_template, v_vehicle, v_date, v_days, rec.model, rec.reg_no)), '');
    IF v_subject IS NULL THEN
      v_subject := CASE rec.alert_type
        WHEN 'inspection' THEN 'Przypomnienie: przegląd techniczny'
        WHEN 'insurance' THEN 'Przypomnienie: ubezpieczenie OC/AC'
        ELSE 'Przypomnienie: wymiana opon' END;
    END IF;
    IF v_body IS NULL THEN
      v_body := 'Pojazd ' || v_vehicle || ' ma termin ' || v_date || ' (za ' || v_days || ' dni).';
    END IF;
    v_subject := left(v_subject, 200);
    v_body := left(v_body, 10000);
    FOR v_recipient IN
      SELECT DISTINCT ON (lower(btrim(src.email))) src.user_id, src.role, lower(btrim(src.email)) AS email
      FROM (
        SELECT rec.assigned_driver_id AS user_id, 'driver'::text AS role, rec.driver_email AS email
        WHERE rec.send_to IN ('driver', 'both')
        UNION ALL
        SELECT p.id, 'admin'::text, p.email
        FROM public.profiles p
        JOIN public.memberships m ON m.user_id = p.id AND m.org_id = rec.org_id AND COALESCE(m.is_active, true) = true
        WHERE rec.send_to IN ('admin', 'both')
          AND (p.fleet_role = 'admin'::public.fleet_role OR m.role ILIKE ANY (ARRAY['owner','admin','administrator','manager','coordinator','koordynator','wlasciciel']))
        UNION ALL
        SELECT p.id, 'admin'::text, p.email
        FROM public.organizations o
        JOIN public.profiles p ON p.id = o.owner_id
        WHERE rec.send_to IN ('admin', 'both') AND o.id = rec.org_id
      ) src
      WHERE private.fleet_valid_email(lower(btrim(COALESCE(src.email, ''))))
      ORDER BY lower(btrim(src.email)), src.role DESC, src.user_id
    LOOP
      v_had_recipient := true;
      BEGIN
        INSERT INTO public.fleet_notification_dispatches (
          org_id, vehicle_id, alert_type, deadline_date, recipient_role, recipient_user_id, recipient_email, subject, body_text, status
        ) VALUES (
          rec.org_id, rec.vehicle_id, rec.alert_type, rec.deadline_date, v_recipient.role, v_recipient.user_id, v_recipient.email, v_subject, v_body, 'pending'
        );
        v_inserted := v_inserted + 1;
      EXCEPTION WHEN unique_violation THEN
        v_already := v_already + 1;
      END;
    END LOOP;
    IF NOT v_had_recipient THEN v_skipped := v_skipped + 1; END IF;
  END LOOP;
  RETURN jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped, 'already', v_already);
END;
$function$;
CREATE OR REPLACE FUNCTION private.has_active_admin_mandate(p_org_id uuid, p_community_id uuid, p_location_master_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ SELECT EXISTS (SELECT 1 FROM public.service_mandates sm WHERE sm.org_id = p_org_id AND sm.community_legal_entity_id = p_community_id AND sm.module = 'admin' AND sm.status = 'active' AND sm.role IN ('primary_operator', 'co_operator') AND (sm.location_master_id IS NULL OR sm.location_master_id IS NOT DISTINCT FROM p_location_master_id)); $function$;
CREATE OR REPLACE FUNCTION private.inbound_ai_monthly_limit(p_org_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (
      SELECT MAX(pp.ai_monthly_parse_limit)
      FROM public.org_subscriptions os
      JOIN public.pricing_plans pp ON pp.id = os.plan_id
      WHERE os.org_id = p_org_id
        AND os.status = 'active'
        AND (os.expires_at IS NULL OR os.expires_at > now())
        AND pp.ai_monthly_parse_limit IS NOT NULL
    ),
    20
  );
$function$;
CREATE OR REPLACE FUNCTION private.inbound_has_ai_auto(p_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.org_subscriptions os
    JOIN public.pricing_plans pp ON pp.id = os.plan_id
    WHERE os.org_id = p_org_id
      AND os.status = 'active'
      AND (os.expires_at IS NULL OR os.expires_at > now())
      AND COALESCE(pp.has_ai_features, false) = true
  );
$function$;
CREATE OR REPLACE FUNCTION private.inbound_is_noreply(p_from text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text := lower(btrim(COALESCE(p_from, '')));
  v_email text;
BEGIN
  v_email := substring(v from '<([^>]+)>');
  IF v_email IS NOT NULL THEN
    v := lower(btrim(v_email));
  END IF;
  v := regexp_replace(v, '[<>"]', '', 'g');
  IF v = '' THEN
    RETURN true;
  END IF;
  IF v IN (
    'usterki@domio.com.pl',
    'firmy@domio.com.pl',
    'biuro@domio.com.pl'
  ) THEN
    RETURN true;
  END IF;
  RETURN v ~ '(^|@)(no[-_]?reply|mailer-daemon|postmaster|bounce|noreply)([.@]|$)';
END;
$function$;
CREATE OR REPLACE FUNCTION private.inbound_looks_like_org_alias(p_alias text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(p_alias, '') ~ '^usterki\+(serwis|cleaning|administracja)-[a-z0-9]';
$function$;
CREATE OR REPLACE FUNCTION private.inbound_match_location(p_org_id uuid, p_location_id uuid, p_address_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_count integer;
  v_addr text := lower(btrim(COALESCE(p_address_text, '')));
BEGIN
  IF p_location_id IS NOT NULL THEN
    SELECT cl.id INTO v_id
    FROM public.cleaning_locations cl
    WHERE cl.id = p_location_id
      AND cl.org_id = p_org_id
      AND (cl.status IS NULL OR cl.status IN ('active', 'archived'))
    LIMIT 1;
    IF v_id IS NOT NULL THEN
      RETURN v_id;
    END IF;
  END IF;
  IF v_addr = '' THEN
    RETURN NULL;
  END IF;
  SELECT COUNT(*)::integer, MIN(cl.id)
    INTO v_count, v_id
  FROM public.cleaning_locations cl
  WHERE cl.org_id = p_org_id
    AND (cl.status IS NULL OR cl.status = 'active')
    AND lower(btrim(cl.address)) = v_addr;
  IF v_count = 1 THEN
    RETURN v_id;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION private.inbound_month_start()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT date_trunc('month', timezone('utc', now()))::date;
$function$;
CREATE OR REPLACE FUNCTION private.inbound_normalize_alias(p_to text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text := lower(btrim(COALESCE(p_to, '')));
  v_email text;
  v_at integer;
BEGIN
  IF v = '' THEN
    RETURN NULL;
  END IF;
  v_email := substring(v from '<([^>]+)>');
  IF v_email IS NOT NULL AND v_email <> '' THEN
    v := lower(btrim(v_email));
  END IF;
  v := regexp_replace(v, '[<>"]', '', 'g');
  v := btrim(v);
  v_at := position('@' IN v);
  IF v_at > 1 THEN
    v := left(v, v_at - 1);
  END IF;
  v := btrim(v);
  IF v = '' THEN
    RETURN NULL;
  END IF;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION private.inbound_try_consume_ai_parse(p_org_id uuid, p_prompt_tokens bigint, p_output_tokens bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_month date := private.inbound_month_start();
  v_limit integer := private.inbound_ai_monthly_limit(p_org_id);
  v_used integer;
  v_in bigint := GREATEST(COALESCE(p_prompt_tokens, 0), 0);
  v_out bigint := GREATEST(COALESCE(p_output_tokens, 0), 0);
BEGIN
  IF v_limit <= 0 THEN
    RETURN false;
  END IF;
  INSERT INTO public.org_ai_usage_monthly (org_id, year_month)
  VALUES (p_org_id, v_month)
  ON CONFLICT (org_id, year_month) DO NOTHING;
  SELECT u.parse_count INTO v_used
  FROM public.org_ai_usage_monthly u
  WHERE u.org_id = p_org_id AND u.year_month = v_month
  FOR UPDATE;
  IF COALESCE(v_used, 0) >= v_limit THEN
    RETURN false;
  END IF;
  UPDATE public.org_ai_usage_monthly
  SET parse_count = parse_count + 1,
      prompt_tokens = prompt_tokens + v_in,
      output_tokens = output_tokens + v_out
  WHERE org_id = p_org_id AND year_month = v_month;
  RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION private.lease_fleet_notification_dispatch(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_row public.fleet_notification_dispatches%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.fleet_notification_dispatches WHERE id = p_dispatch_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_row.status = 'sent' THEN RETURN private.fleet_notification_payload(v_row.id); END IF;
  IF v_row.status = 'skipped' THEN RETURN NULL; END IF;
  UPDATE public.fleet_notification_dispatches
  SET status = 'processing', attempt_count = attempt_count + 1, next_attempt_at = now() + interval '10 minutes'
  WHERE id = p_dispatch_id AND attempt_count < 12;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN private.fleet_notification_payload(p_dispatch_id);
END;
$function$;
CREATE OR REPLACE FUNCTION private.legal_acceptance_salt()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'vault', 'pg_catalog'
AS $function$
DECLARE
  v_salt text;
BEGIN
  SELECT ds.decrypted_secret
  INTO v_salt
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'legal_acceptance_salt';

  IF v_salt IS NULL OR length(v_salt) < 32 THEN
    RAISE EXCEPTION 'LEGAL_ACCEPTANCE_SALT_MISSING'
      USING ERRCODE = 'configuration_limit_exceeded';
  END IF;

  RETURN v_salt;
END;
$function$;
CREATE OR REPLACE FUNCTION private.legal_acceptance_hmac(p_user_id uuid, p_accepted_at timestamp with time zone, p_document_id uuid, p_document_version text, p_pdf_sha256 text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'extensions', 'pg_catalog'
AS $function$
DECLARE
  v_payload text;
BEGIN
  IF p_user_id IS NULL
     OR p_accepted_at IS NULL
     OR p_document_id IS NULL
     OR p_document_version IS NULL
     OR p_pdf_sha256 IS NULL
     OR p_pdf_sha256 !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'LEGAL_ACCEPTANCE_HMAC_INPUT'
      USING ERRCODE = 'check_violation';
  END IF;

  v_payload :=
    p_user_id::text || '|' ||
    to_char(p_accepted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') || '|' ||
    p_document_id::text || '|' ||
    p_document_version || '|' ||
    p_pdf_sha256;

  RETURN encode(
    extensions.hmac(v_payload, private.legal_acceptance_salt(), 'sha256'),
    'hex'
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.finalize_legal_consent(p_batch_id uuid, p_pdf_sha256 text, p_pdf_storage_path text, p_document_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_batch public.user_consent_batches%ROWTYPE;
  v_doc public.legal_documents%ROWTYPE;
  v_id uuid;
  v_hash text;
  v_dispatch_id uuid;
  v_terms text;
  v_privacy text;
  v_marketing text;
  v_marketing_consent boolean := false;
BEGIN
  PERFORM private.assert_sha256_hex(p_pdf_sha256, 'pdf_sha256');

  IF p_pdf_storage_path IS NULL OR btrim(p_pdf_storage_path) = '' THEN
    RAISE EXCEPTION 'LEGAL_PDF_PATH_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;

  IF p_document_ids IS NULL OR coalesce(array_length(p_document_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'LEGAL_DOCUMENTS_REQUIRED' USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_batch
  FROM public.user_consent_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'LEGAL_BATCH_NOT_FOUND' USING ERRCODE = 'no_data_found';
  END IF;

  SELECT d.id INTO v_dispatch_id
  FROM public.legal_welcome_dispatches d
  WHERE d.batch_id = p_batch_id;

  IF v_dispatch_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'already_recorded', true,
      'batch_id', p_batch_id,
      'dispatch_id', v_dispatch_id
    );
  END IF;

  UPDATE public.user_consent_batches
  SET
    pdf_sha256 = p_pdf_sha256,
    pdf_storage_path = btrim(p_pdf_storage_path)
  WHERE id = p_batch_id
  RETURNING * INTO v_batch;

  FOREACH v_id IN ARRAY p_document_ids
  LOOP
    SELECT * INTO v_doc
    FROM public.legal_documents
    WHERE id = v_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'LEGAL_DOCUMENTS_STALE' USING ERRCODE = 'check_violation';
    END IF;

    v_hash := private.legal_acceptance_hmac(
      v_batch.user_id,
      v_batch.accepted_at,
      v_doc.id,
      v_doc.version,
      v_batch.pdf_sha256
    );

    INSERT INTO public.user_consents (
      batch_id,
      user_id,
      document_id,
      document_type,
      document_version,
      accepted_at,
      ip_address,
      user_agent,
      acceptance_hash
    )
    VALUES (
      v_batch.id,
      v_batch.user_id,
      v_doc.id,
      v_doc.document_type,
      v_doc.version,
      v_batch.accepted_at,
      v_batch.ip_address,
      v_batch.user_agent,
      v_hash
    );

    IF v_doc.document_type = 'terms' THEN
      v_terms := v_doc.version;
    ELSIF v_doc.document_type = 'privacy' THEN
      v_privacy := v_doc.version;
    ELSIF v_doc.document_type = 'marketing' THEN
      v_marketing := v_doc.version;
      v_marketing_consent := true;
    END IF;
  END LOOP;

  INSERT INTO public.legal_welcome_dispatches (batch_id, status, next_attempt_at)
  VALUES (v_batch.id, 'pending', now())
  RETURNING id INTO v_dispatch_id;

  INSERT INTO public.profiles (
    id,
    email,
    account_type,
    is_first_login,
    accepted_terms_at,
    terms_version,
    privacy_version,
    marketing_consent,
    marketing_version,
    ip_address
  )
  VALUES (
    v_batch.user_id,
    v_batch.email,
    'hub',
    false,
    v_batch.accepted_at,
    COALESCE(v_terms, '1.0'),
    v_privacy,
    v_marketing_consent,
    v_marketing,
    v_batch.ip_address
  )
  ON CONFLICT (id) DO UPDATE
  SET
    email = COALESCE(EXCLUDED.email, public.profiles.email),
    accepted_terms_at = EXCLUDED.accepted_terms_at,
    terms_version = COALESCE(EXCLUDED.terms_version, public.profiles.terms_version),
    privacy_version = COALESCE(EXCLUDED.privacy_version, public.profiles.privacy_version),
    marketing_consent = public.profiles.marketing_consent OR EXCLUDED.marketing_consent,
    marketing_version = COALESCE(EXCLUDED.marketing_version, public.profiles.marketing_version),
    ip_address = COALESCE(EXCLUDED.ip_address, public.profiles.ip_address),
    updated_at = now();

  RETURN jsonb_build_object(
    'already_recorded', false,
    'batch_id', v_batch.id,
    'dispatch_id', v_dispatch_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.legal_content_sha256(p_content text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'extensions', 'pg_catalog'
AS $function$
  SELECT encode(extensions.digest(convert_to(p_content, 'UTF8'), 'sha256'), 'hex');
$function$;
CREATE OR REPLACE FUNCTION private.legal_welcome_email_html(p_accepted_at timestamp with time zone, p_versions text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  RETURN
    '<p>Dzień dobry,</p>'
    || '<p>dziękujemy za konto w DOMIO. W załączniku przesyłamy plik PDF z treścią '
    || '<strong>Regulaminu</strong> i <strong>Polityki prywatności</strong>'
    || CASE WHEN p_versions IS NOT NULL AND p_versions <> '' THEN ' (' || p_versions || ')' ELSE '' END
    || ', obowiązującą w chwili akceptacji'
    || CASE
         WHEN p_accepted_at IS NULL THEN '.'
         ELSE ' (' || to_char(p_accepted_at AT TIME ZONE 'Europe/Warsaw', 'YYYY-MM-DD HH24:MI')
           || ' czas polski).'
       END
    || '</p>'
    || '<p>Zachowaj tę wiadomość. Stanowi ona trwały nośnik dokumentów — późniejsza zmiana treści na stronie nie zmienia załącznika.</p>'
    || '<p>Pozdrawiamy,<br>Zespół DOMIO</p>';
END;
$function$;
CREATE OR REPLACE FUNCTION private.legal_welcome_email_subject()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT 'DOMIO — Regulamin i Polityka prywatności'::text;
$function$;
CREATE OR REPLACE FUNCTION private.legal_welcome_filename(p_accepted_at timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT 'DOMIO_Regulamin_i_Polityka_Prywatnosci_'
    || to_char(COALESCE(p_accepted_at, clock_timestamp()) AT TIME ZONE 'Europe/Warsaw', 'YYYY-MM-DD')
    || '.pdf';
$function$;
CREATE OR REPLACE FUNCTION private.legal_welcome_payload(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_dispatch public.legal_welcome_dispatches%ROWTYPE;
  v_batch public.user_consent_batches%ROWTYPE;
  v_versions text;
BEGIN
  SELECT * INTO v_dispatch
  FROM public.legal_welcome_dispatches
  WHERE id = p_dispatch_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_batch
  FROM public.user_consent_batches
  WHERE id = v_dispatch.batch_id;

  SELECT string_agg(c.document_type || ' v' || c.document_version, ', ' ORDER BY c.document_type)
  INTO v_versions
  FROM public.user_consents c
  WHERE c.batch_id = v_batch.id;

  RETURN jsonb_build_object(
    'dispatch_id', v_dispatch.id,
    'batch_id', v_batch.id,
    'status', v_dispatch.status,
    'already_sent', v_dispatch.status = 'sent',
    'to_email', v_batch.email,
    'subject', private.legal_welcome_email_subject(),
    'html', private.legal_welcome_email_html(v_batch.accepted_at, v_versions),
    'storage_path', v_batch.pdf_storage_path,
    'filename', private.legal_welcome_filename(v_batch.accepted_at)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.lease_legal_welcome_dispatch(p_dispatch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_row public.legal_welcome_dispatches%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.legal_welcome_dispatches
  WHERE id = p_dispatch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_row.status = 'sent' THEN
    RETURN private.legal_welcome_payload(v_row.id);
  END IF;

  UPDATE public.legal_welcome_dispatches
  SET
    status = 'processing',
    attempt_count = attempt_count + 1,
    next_attempt_at = now() + interval '10 minutes'
  WHERE id = p_dispatch_id;

  RETURN private.legal_welcome_payload(p_dispatch_id);
END;
$function$;
CREATE OR REPLACE FUNCTION private.mandate_require_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$ DECLARE v_actor uuid := (SELECT auth.uid()); BEGIN IF v_actor IS NULL THEN RAISE EXCEPTION 'MANDATE_AUTH_REQUIRED'; END IF; RETURN v_actor; END; $function$;
CREATE OR REPLACE FUNCTION private.cleaning_scope_require_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'private'
AS $function$
BEGIN
  RETURN private.mandate_require_actor();
EXCEPTION
  WHEN others THEN
    IF SQLERRM LIKE '%MANDATE_AUTH_REQUIRED%' THEN
      RAISE EXCEPTION 'CLEANING_SCOPE_AUTH_REQUIRED';
    END IF;
    RAISE;
END;
$function$;
CREATE OR REPLACE FUNCTION private.mandate_set_rpc_flag()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN PERFORM set_config('app.mandate_rpc', '1', true); END; $function$;
CREATE OR REPLACE FUNCTION private.mandate_transition_ok(p_old mandate_status, p_new mandate_status)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ SELECT p_old IS NOT DISTINCT FROM p_new OR (p_old = 'invited' AND p_new IN ('active', 'declined')) OR (p_old = 'active' AND p_new IN ('paused', 'superseded')) OR (p_old = 'paused' AND p_new IN ('active', 'superseded')); $function$;
CREATE OR REPLACE FUNCTION private.org_inbound_disable_cleaning_module()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
BEGIN
  IF NEW.module = 'cleaning' THEN
    NEW.is_enabled := false;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.pending_required_legal_documents(p_user_id uuid)
 RETURNS TABLE(id uuid, document_type text, version text, active_from timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'LEGAL_AUTH_REQUIRED'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Workers / simplified staff are not consumers of platform ToS in this flow.
  IF EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = p_user_id
      AND p.account_type = 'simplified'
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    d.id,
    d.document_type,
    d.version,
    d.active_from
  FROM public.legal_documents d
  WHERE d.is_active = true
    AND d.is_required = true
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_consents c
      WHERE c.user_id = p_user_id
        AND c.document_id = d.id
    )
  ORDER BY
    CASE d.document_type
      WHEN 'terms' THEN 1
      WHEN 'privacy' THEN 2
      ELSE 3
    END,
    d.active_from;
END;
$function$;
CREATE OR REPLACE FUNCTION private.pick_scope_contract_row(p_admin_org_id uuid, p_admin_location_id uuid, p_community_id uuid, p_prefer_type property_contract_type)
 RETURNS property_contracts
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.property_contracts;
BEGIN
  SELECT pc.*
  INTO v_row
  FROM public.property_contracts pc
  JOIN public.cleaning_locations loc ON loc.id = pc.location_id
  WHERE private.contract_has_document(pc.document_url)
    AND private.contract_is_active(pc.end_date)
    AND private.contract_belongs_to_admin_org(
      pc.org_id, pc.origin_org_id, pc.shared_with_org_ids, loc.org_id, p_admin_org_id
    )
    AND private.contract_in_community_scope(
      pc.community_id, pc.location_id, loc.community_id, p_admin_location_id, p_community_id
    )
    AND (p_prefer_type IS NULL OR pc.type = p_prefer_type)
  ORDER BY
    CASE WHEN pc.location_id = p_admin_location_id THEN 0 ELSE 1 END,
    CASE WHEN pc.community_id IS NOT DISTINCT FROM p_community_id THEN 0 ELSE 1 END,
    pc.start_date DESC
  LIMIT 1;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION private.resident_order_append_event(p_order_id uuid, p_actor_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb)
