CREATE OR REPLACE FUNCTION private.resolve_partner_cleaning_location(p_location_master_id uuid, p_admin_org_id uuid, p_community_id uuid)
 RETURNS TABLE(cleaning_org_id uuid, cleaning_location_id uuid, has_active_mandate boolean, has_active_cooperation boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_coop_org uuid;
  v_mandate_org uuid;
  v_le uuid;
  v_partner_org uuid;
  v_partner_loc uuid;
  v_has_coop boolean := false;
  v_has_mandate boolean := false;
BEGIN
  SELECT bcl.cleaning_org_id
  INTO v_coop_org
  FROM public.building_cooperation_links bcl
  WHERE bcl.location_master_id = p_location_master_id
    AND bcl.admin_org_id = p_admin_org_id
    AND bcl.status = 'active'
    AND bcl.cleaning_org_id IS NOT NULL
  LIMIT 1;

  v_has_coop := v_coop_org IS NOT NULL;

  IF p_community_id IS NOT NULL THEN
    SELECT c.legal_entity_id INTO v_le
    FROM public.communities c
    WHERE c.id = p_community_id;
  END IF;

  IF v_le IS NOT NULL THEN
    SELECT sm.org_id
    INTO v_mandate_org
    FROM public.service_mandates sm
    WHERE sm.community_legal_entity_id = v_le
      AND sm.module = 'cleaning'
      AND sm.status = 'active'
      AND sm.org_id IS NOT NULL
      AND (
        sm.location_master_id IS NULL
        OR sm.location_master_id IS NOT DISTINCT FROM p_location_master_id
      )
    ORDER BY sm.location_master_id NULLS LAST, sm.accepted_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  v_has_mandate := v_mandate_org IS NOT NULL;
  v_partner_org := COALESCE(v_coop_org, v_mandate_org);

  IF v_partner_org IS NOT NULL THEN
    SELECT cl.id
    INTO v_partner_loc
    FROM public.cleaning_locations cl
    WHERE cl.location_master_id = p_location_master_id
      AND cl.org_id = v_partner_org
      AND COALESCE(cl.is_cleaning_active, false) = true
      AND COALESCE(cl.status, 'active') = 'active'
    ORDER BY cl.created_at
    LIMIT 1;
  END IF;

  IF v_partner_org IS NULL OR v_partner_loc IS NULL THEN
    RETURN;
  END IF;

  cleaning_org_id := v_partner_org;
  cleaning_location_id := v_partner_loc;
  has_active_mandate := v_has_mandate;
  has_active_cooperation := v_has_coop;
  RETURN NEXT;
END;
$function$;
CREATE OR REPLACE FUNCTION private.resolve_scope_document(p_admin_location cleaning_locations)
 RETURNS TABLE(contract_id uuid, contract_number text, contract_type text, company_name text, document_url text, source text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_pc public.property_contracts;
  v_source text := 'none';
BEGIN
  IF p_admin_location.cleaning_scope_contract_id IS NOT NULL
     AND private.contract_eligible_for_cleaning_scope(
       p_admin_location.cleaning_scope_contract_id,
       p_admin_location.org_id,
       p_admin_location.id,
       p_admin_location.community_id
     )
  THEN
    SELECT * INTO v_pc
    FROM public.property_contracts
    WHERE id = p_admin_location.cleaning_scope_contract_id;
    v_source := 'explicit';
  END IF;

  IF v_pc.id IS NULL THEN
    v_pc := private.pick_scope_contract_row(
      p_admin_location.org_id,
      p_admin_location.id,
      p_admin_location.community_id,
      'cleaning'
    );
    IF v_pc.id IS NOT NULL THEN
      v_source := CASE
        WHEN v_pc.location_id = p_admin_location.id THEN 'location'
        ELSE 'community'
      END;
    END IF;
  END IF;

  IF v_pc.id IS NULL THEN
    v_pc := private.pick_scope_contract_row(
      p_admin_location.org_id,
      p_admin_location.id,
      p_admin_location.community_id,
      NULL
    );
    IF v_pc.id IS NOT NULL THEN
      v_source := CASE
        WHEN v_pc.location_id = p_admin_location.id THEN 'location'
        ELSE 'community'
      END;
    END IF;
  END IF;

  IF v_pc.id IS NULL THEN
    contract_id := NULL;
    contract_number := NULL;
    contract_type := NULL;
    company_name := NULL;
    document_url := NULL;
    source := 'none';
    RETURN NEXT;
    RETURN;
  END IF;

  contract_id := v_pc.id;
  contract_number := v_pc.contract_number;
  contract_type := v_pc.type::text;
  document_url := v_pc.document_url;
  source := v_source;

  SELECT c.name INTO company_name
  FROM public.companies c
  WHERE c.id = v_pc.company_id;

  RETURN NEXT;
END;
$function$;
CREATE OR REPLACE FUNCTION private.resolve_serwis_org_for_issue(p_issue_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_location uuid;
  v_claimed uuid;
  v_master uuid;
  v_legal uuid;
BEGIN
  SELECT i.claimed_by_org_id, i.location_id
  INTO v_claimed, v_location
  FROM public.property_issues i
  WHERE i.id = p_issue_id;

  IF v_claimed IS NOT NULL THEN
    RETURN v_claimed;
  END IF;

  IF v_location IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT cl.location_master_id, c.legal_entity_id
  INTO v_master, v_legal
  FROM public.cleaning_locations cl
  LEFT JOIN public.communities c ON c.id = cl.community_id
  WHERE cl.id = v_location;

  IF v_master IS NOT NULL THEN
    SELECT bcl.maintenance_org_id
    INTO v_org
    FROM public.building_cooperation_links bcl
    WHERE bcl.location_master_id = v_master
      AND bcl.status = 'active'
      AND bcl.maintenance_org_id IS NOT NULL
    LIMIT 1;
    IF v_org IS NOT NULL THEN
      RETURN v_org;
    END IF;
  END IF;

  IF v_legal IS NOT NULL THEN
    SELECT sm.org_id
    INTO v_org
    FROM public.service_mandates sm
    WHERE sm.community_legal_entity_id = v_legal
      AND sm.module = 'maintenance'
      AND sm.status = 'active'
      AND sm.org_id IS NOT NULL
      AND (sm.valid_until IS NULL OR sm.valid_until > now())
      AND (
        sm.location_master_id IS NULL
        OR sm.location_master_id = v_master
      )
    ORDER BY sm.location_master_id NULLS LAST
    LIMIT 1;
    IF v_org IS NOT NULL THEN
      RETURN v_org;
    END IF;
  END IF;

  SELECT i.org_id
  INTO v_org
  FROM public.property_issues i
  JOIN public.org_duty_state d ON d.org_id = i.org_id AND d.is_duty_enabled
  WHERE i.id = p_issue_id;

  RETURN v_org;
END;
$function$;
CREATE OR REPLACE FUNCTION private.succession_location_masters(p_community_id uuid, p_location_master_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ SELECT DISTINCT master_id FROM (SELECT p_location_master_id AS master_id WHERE p_location_master_id IS NOT NULL UNION SELECT loc.id FROM public.locations loc WHERE p_location_master_id IS NULL AND loc.legal_entity_id = p_community_id UNION SELECT cl.location_master_id FROM public.cleaning_locations cl INNER JOIN public.communities c ON c.id = cl.community_id WHERE p_location_master_id IS NULL AND c.legal_entity_id = p_community_id AND cl.location_master_id IS NOT NULL) s WHERE master_id IS NOT NULL; $function$;
CREATE OR REPLACE FUNCTION private.succession_transition_ok(p_old succession_status, p_new succession_status)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ SELECT p_old IS NOT DISTINCT FROM p_new OR (p_old = 'proposed' AND p_new IN ('accepted', 'rejected', 'cancelled')) OR (p_old = 'accepted' AND p_new IN ('completed', 'cancelled')); $function$;
CREATE OR REPLACE FUNCTION private.sync_profile_last_login_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.last_sign_in_at IS DISTINCT FROM OLD.last_sign_in_at THEN
    UPDATE public.profiles
    SET last_login_at = NEW.last_sign_in_at
    WHERE id = NEW.id
      AND last_login_at IS DISTINCT FROM NEW.last_sign_in_at;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_cleaning_locations_active_community()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
BEGIN
  IF NEW.community_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.community_id IS NOT DISTINCT FROM OLD.community_id
     AND NEW.is_admin_active IS NOT TRUE
  THEN
    RETURN NEW;
  END IF;

  SELECT c.status INTO v_status
  FROM public.communities c
  WHERE c.id = NEW.community_id;

  IF v_status = 'inactive'
     AND (
       TG_OP = 'INSERT'
       OR NEW.community_id IS DISTINCT FROM OLD.community_id
       OR (NEW.is_admin_active IS TRUE AND OLD.is_admin_active IS DISTINCT FROM TRUE)
     )
  THEN
    RAISE EXCEPTION 'COMMUNITY_INACTIVE';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_communities_status_via_rpc()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND (
       NEW.status IS DISTINCT FROM OLD.status
       OR NEW.deactivated_at IS DISTINCT FROM OLD.deactivated_at
       OR NEW.deactivated_by IS DISTINCT FROM OLD.deactivated_by
     )
     AND current_setting('app.community_rpc', true) IS DISTINCT FROM '1'
  THEN
    RAISE EXCEPTION 'COMMUNITY_STATUS_VIA_RPC';
  END IF;
  RETURN NEW;
END;
$function$;
