CREATE OR REPLACE FUNCTION private.tg_equipment_lifecycle_via_rpc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.equipment_rpc', true) = '1' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_TABLE_NAME = 'equipment_assets' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.status IS DISTINCT FROM 'available' OR NEW.current_holder_id IS NOT NULL THEN
        RAISE EXCEPTION 'EQUIPMENT_STATUS_VIA_RPC';
      END IF;
    ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.status IS DISTINCT FROM OLD.status OR NEW.current_holder_id IS DISTINCT FROM OLD.current_holder_id THEN
        RAISE EXCEPTION 'EQUIPMENT_STATUS_VIA_RPC';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'staff_equipment' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.status IS DISTINCT FROM 'assigned' THEN
        RAISE EXCEPTION 'EQUIPMENT_STATUS_VIA_RPC';
      END IF;
    ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.status IS DISTINCT FROM OLD.status OR NEW.returned_at IS DISTINCT FROM OLD.returned_at THEN
        RAISE EXCEPTION 'EQUIPMENT_STATUS_VIA_RPC';
      END IF;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_equipment_protocols_via_rpc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.equipment_rpc', true) = '1' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  RAISE EXCEPTION 'EQUIPMENT_PROTOCOL_VIA_RPC';
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_fill_shared_orgs_from_live_grants()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_resource public.succession_resource; v_orgs uuid[];
BEGIN
  IF NEW.location_master_id IS NULL THEN RETURN NEW; END IF;
  v_resource := CASE TG_TABLE_NAME WHEN 'property_issues' THEN 'issues'::public.succession_resource WHEN 'property_inspections' THEN 'inspections'::public.succession_resource WHEN 'inspection_campaigns' THEN 'unit_inspections'::public.succession_resource WHEN 'property_contracts' THEN 'contracts'::public.succession_resource WHEN 'location_access' THEN 'residents'::public.succession_resource ELSE NULL END;
  SELECT COALESCE(array_agg(DISTINCT g.grantee_org_id), '{}'::uuid[]) INTO v_orgs FROM public.succession_share_grants g WHERE g.location_master_id = NEW.location_master_id AND g.revoked_at IS NULL AND g.expires_at > now() AND (g.resource_type = v_resource OR g.resource_type = 'all');
  SELECT ARRAY(SELECT DISTINCT x FROM unnest(COALESCE(NEW.shared_with_org_ids, '{}'::uuid[]) || v_orgs) AS x) INTO NEW.shared_with_org_ids;
  RETURN NEW;
END; $function$;
CREATE OR REPLACE FUNCTION private.tg_legal_documents_after_insert_close_previous()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.is_active THEN
    UPDATE public.legal_documents
    SET is_active = false
    WHERE document_type = NEW.document_type
      AND is_active = true
      AND id IS DISTINCT FROM NEW.id;
  END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_legal_documents_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE
  v_expected text;
BEGIN
  IF NEW.content IS NULL OR btrim(NEW.content) = '' THEN
    RAISE EXCEPTION 'legal document content must not be empty'
      USING ERRCODE = 'check_violation';
  END IF;

  v_expected := private.legal_content_sha256(NEW.content);
  IF NEW.content_hash IS NULL OR NEW.content_hash = '' THEN
    NEW.content_hash := v_expected;
  ELSIF NEW.content_hash IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'content_hash does not match document content'
      USING ERRCODE = 'check_violation';
  END IF;

  NEW.active_from := COALESCE(NEW.active_from, NEW.published_at, clock_timestamp());
  IF NEW.is_active THEN
    NEW.active_until := NULL;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_legal_documents_before_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.document_type IS DISTINCT FROM OLD.document_type
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.content IS DISTINCT FROM OLD.content
     OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
     OR NEW.active_from IS DISTINCT FROM OLD.active_from
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.is_required IS DISTINCT FROM OLD.is_required
  THEN
    RAISE EXCEPTION 'Published legal documents are immutable (id=%)', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF OLD.is_active AND NOT NEW.is_active AND NEW.active_until IS NULL THEN
    NEW.active_until := clock_timestamp();
  END IF;

  IF (NOT OLD.is_active) AND NEW.is_active THEN
    NEW.active_until := NULL;
  END IF;

  RETURN NEW;
END;
$function$;
