$function$;
CREATE OR REPLACE FUNCTION private.tg_mandate_tables_via_rpc()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN IF current_setting('app.mandate_rpc', true) IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'MANDATE_VIA_RPC'; END IF; RETURN COALESCE(NEW, OLD); END; $function$;
CREATE OR REPLACE FUNCTION private.tg_service_mandates_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN IF current_setting('app.mandate_rpc', true) IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'MANDATE_VIA_RPC'; END IF; IF TG_OP = 'UPDATE' THEN IF NOT private.mandate_transition_ok(OLD.status, NEW.status) THEN RAISE EXCEPTION 'ILLEGAL_STATUS_TRANSITION'; END IF; IF OLD.status = 'invited' AND NEW.status = 'active' THEN IF NEW.accepted_at IS NULL OR NEW.accepted_by_org_id IS NULL THEN RAISE EXCEPTION 'MANDATE_ACCEPTANCE_REQUIRED'; END IF; END IF; IF NEW.status = 'superseded' THEN IF NEW.revoked_at IS NULL OR NEW.revoked_by_org_id IS NULL THEN RAISE EXCEPTION 'MANDATE_REVOKE_AUDIT_REQUIRED'; END IF; END IF; END IF; IF TG_OP = 'INSERT' AND NEW.status = 'active' AND NEW.accepted_at IS NULL THEN RAISE EXCEPTION 'MANDATE_ACCEPTANCE_REQUIRED'; END IF; RETURN COALESCE(NEW, OLD); END; $function$;
CREATE OR REPLACE FUNCTION private.tg_succession_events_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN IF current_setting('app.mandate_rpc', true) IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'SUCCESSION_VIA_RPC'; END IF; IF TG_OP = 'UPDATE' AND NOT private.succession_transition_ok(OLD.status, NEW.status) THEN RAISE EXCEPTION 'ILLEGAL_STATUS_TRANSITION'; END IF; IF TG_OP = 'INSERT' AND NEW.status <> 'proposed' THEN RAISE EXCEPTION 'ILLEGAL_STATUS_TRANSITION'; END IF; RETURN COALESCE(NEW, OLD); END; $function$;
CREATE OR REPLACE FUNCTION private.tg_user_consent_batches_before_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.accepted_at IS DISTINCT FROM OLD.accepted_at
     OR NEW.source IS DISTINCT FROM OLD.source
     OR NEW.email IS DISTINCT FROM OLD.email
     OR NEW.ip_address IS DISTINCT FROM OLD.ip_address
     OR NEW.user_agent IS DISTINCT FROM OLD.user_agent
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'user_consent_batches identity columns are immutable (id=%)', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF OLD.pdf_sha256 IS NOT NULL AND NEW.pdf_sha256 IS DISTINCT FROM OLD.pdf_sha256 THEN
    RAISE EXCEPTION 'pdf_sha256 can only be set once (id=%)', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF OLD.pdf_storage_path IS NOT NULL AND NEW.pdf_storage_path IS DISTINCT FROM OLD.pdf_storage_path THEN
    RAISE EXCEPTION 'pdf_storage_path can only be set once (id=%)', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_user_consent_batches_forbid_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  RAISE EXCEPTION 'user_consent_batches rows cannot be deleted (id=%)', OLD.id
    USING ERRCODE = 'integrity_constraint_violation';
END;
$function$;
CREATE OR REPLACE FUNCTION private.tg_user_consents_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_batch public.user_consent_batches%ROWTYPE;
  v_doc public.legal_documents%ROWTYPE;
BEGIN
  PERFORM private.assert_sha256_hex(NEW.acceptance_hash, 'acceptance_hash');

  SELECT * INTO v_batch
  FROM public.user_consent_batches
  WHERE id = NEW.batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown consent batch %', NEW.batch_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  SELECT * INTO v_doc
  FROM public.legal_documents
  WHERE id = NEW.document_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown legal document %', NEW.document_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  NEW.user_id := v_batch.user_id;
  NEW.accepted_at := v_batch.accepted_at;
  NEW.ip_address := COALESCE(NEW.ip_address, v_batch.ip_address);
  NEW.user_agent := COALESCE(NEW.user_agent, v_batch.user_agent);
  NEW.document_type := v_doc.document_type;
  NEW.document_version := v_doc.version;

  RETURN NEW;
END;
$function$;
