Prosimy o potwierdzenie przyjęcia zgłoszenia.$t$::text;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_default_subject()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT '[DOMIO {{issue.token}}] Zgłoszenie: {{building.address}}'::text;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_build_payload(p_issue_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_issue public.property_issues%ROWTYPE;
  v_dispatch public.issue_email_dispatches%ROWTYPE;
  v_channel public.vendor_email_channels%ROWTYPE;
  v_vendor public.vendor_partners%ROWTYPE;
  v_org public.organizations%ROWTYPE;
  v_loc public.cleaning_locations%ROWTYPE;
  v_to text;
  v_reply text;
BEGIN
  SELECT * INTO v_issue FROM public.property_issues WHERE id = p_issue_id;
  IF v_issue.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zgłoszenia.';
  END IF;

  SELECT * INTO v_dispatch
  FROM public.issue_email_dispatches
  WHERE issue_id = p_issue_id;

  IF v_dispatch.id IS NULL THEN
    RAISE EXCEPTION 'Brak wątku wysyłki e-mail dla zgłoszenia.';
  END IF;

  SELECT * INTO v_channel
  FROM public.vendor_email_channels
  WHERE vendor_id = v_dispatch.vendor_id;

  SELECT * INTO v_vendor FROM public.vendor_partners WHERE id = v_dispatch.vendor_id;
  SELECT * INTO v_org FROM public.organizations WHERE id = v_issue.org_id;
  SELECT * INTO v_loc FROM public.cleaning_locations WHERE id = v_issue.location_id;

  v_to := COALESCE(
    NULLIF(btrim(COALESCE(v_channel.outbound_to_email, '')), ''),
    NULLIF(btrim(COALESCE(v_vendor.contact_email, '')), '')
  );

  v_reply := 'biuro+t_' || v_dispatch.correlation_token || '@domio.com.pl';

  RETURN jsonb_build_object(
    'dispatchId', v_dispatch.id,
    'issueId', v_issue.id,
    'toEmail', COALESCE(v_to, ''),
    'toName', COALESCE(v_vendor.name, ''),
    'cc', to_jsonb(COALESCE(v_channel.outbound_cc, '{}'::text[])),
    'replyTo', v_reply,
    'subjectTemplate', COALESCE(
      v_channel.outbound_subject_template,
      private.vendor_email_default_subject()
    ),
    'bodyTemplate', COALESCE(
      v_channel.outbound_body_template,
      private.vendor_email_default_body()
    ),
    'variables', jsonb_build_object(
      'issue.id', v_issue.id::text,
      'issue.token', v_dispatch.correlation_token,
      'issue.description', COALESCE(v_issue.description, ''),
      'issue.category', COALESCE(v_issue.category, ''),
      'issue.priority', COALESCE(v_issue.priority::text, ''),
      'building.name', COALESCE(v_loc.name, ''),
      'building.address', COALESCE(v_loc.address, ''),
      'org.name', COALESCE(v_org.name, ''),
      'reporter.name', COALESCE(v_issue.reporter_name, ''),
      'reporter.phone', COALESCE(v_issue.reporter_phone, '')
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_escape_regex(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text := COALESCE(p_text, '');
  ch text;
  i integer;
  out_text text := '';
BEGIN
  FOR i IN 1..char_length(v) LOOP
    ch := substr(v, i, 1);
    IF ch IN ('[', ']', '(', ')', '{', '}', '.', '^', '$', '|', '*', '+', '?') THEN
      out_text := out_text || chr(92) || ch;
    ELSE
      out_text := out_text || ch;
    END IF;
  END LOOP;
  RETURN out_text;
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_extract_token(p_to text, p_subject text, p_body text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_local text; v_token text; v_blob text;
BEGIN
  v_local := private.inbound_normalize_alias(p_to);
  IF v_local IS NOT NULL THEN
    v_token := substring(v_local from '\+t_([a-z0-9]{12})');
    IF v_token IS NOT NULL THEN RETURN v_token; END IF;
  END IF;
  v_blob := lower(COALESCE(p_subject, '') || E'\n' || COALESCE(p_body, ''));
  v_token := substring(v_blob from '\[domio[[:space:]]+([a-z0-9]{12})\]');
  IF v_token IS NOT NULL THEN RETURN v_token; END IF;
  v_token := substring(v_blob from 'domio[[:space:]]+([a-z0-9]{12})');
  IF v_token IS NOT NULL THEN RETURN v_token; END IF;
  v_token := substring(v_blob from 'ref:[[:space:]]*([a-z0-9]{12})');
  RETURN v_token;
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_guess_event(p_subject text, p_body text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := lower(COALESCE(p_subject, '') || E'\n' || COALESCE(p_body, ''));
BEGIN
  IF v ~ 'zako[nń]cz|wykonan|completed|resolved|gotowe' THEN RETURN 'completed'; END IF;
  IF v ~ 'odrzu|rezygn|nie przyjmu|cancel' THEN RETURN 'rejected'; END IF;
  IF v ~ 'technik|przypisan|assigned' THEN RETURN 'assigned_technician'; END IF;
  IF v ~ 'przyj[eę]|akcept|przyjel' THEN RETURN 'accepted'; END IF;
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_is_service_role()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT (SELECT auth.role()) IS NOT DISTINCT FROM 'service_role';
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_match_template(p_pattern text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pat text := regexp_replace(btrim(COALESCE(p_pattern, '')), E'\\s+', ' ', 'g');
  v_txt text := regexp_replace(btrim(COALESCE(p_text, '')), E'\\s+', ' ', 'g');
  v_names text[] := '{}';
  v_regex text := '';
  v_rest text;
  v_m text[];
  v_open integer;
  v_close integer;
  v_token text;
  v_i integer;
  v_obj jsonb := '{}'::jsonb;
BEGIN
  IF v_pat = '' OR v_txt = '' THEN
    RETURN jsonb_build_object('matched', false);
  END IF;

  v_rest := v_pat;
  LOOP
    v_open := position('{{' IN v_rest);
    IF v_open = 0 THEN
      v_regex := v_regex || private.vendor_email_escape_regex(v_rest);
      EXIT;
    END IF;
    v_regex := v_regex || private.vendor_email_escape_regex(left(v_rest, v_open - 1));
    v_rest := substr(v_rest, v_open + 2);
    v_close := position('}}' IN v_rest);
    IF v_close = 0 THEN
      RETURN jsonb_build_object('matched', false);
    END IF;
    v_token := btrim(left(v_rest, v_close - 1));
    v_rest := substr(v_rest, v_close + 2);
    IF v_token = '' OR v_token !~ '^[a-z][a-z0-9_]*$' THEN
      RETURN jsonb_build_object('matched', false);
    END IF;
    v_names := array_append(v_names, v_token);
    v_regex := v_regex || '(.+?)';
  END LOOP;

  v_m := regexp_match(v_txt, '^' || v_regex || '$');
  IF v_m IS NULL THEN
    RETURN jsonb_build_object('matched', false);
  END IF;

  FOR v_i IN 1..COALESCE(array_length(v_names, 1), 0) LOOP
    v_obj := v_obj || jsonb_build_object(v_names[v_i], COALESCE(v_m[v_i], ''));
  END LOOP;

  RETURN jsonb_build_object('matched', true, 'extracted', v_obj);
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_new_token()
 RETURNS text
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  SELECT encode(extensions.gen_random_bytes(6), 'hex');
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_normalize_address(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text := lower(btrim(COALESCE(p_raw, '')));
  v_email text;
BEGIN
  IF v = '' THEN
    RETURN NULL;
  END IF;
  v_email := substring(v from '<([^>]+)>');
  IF v_email IS NOT NULL AND v_email <> '' THEN
    v := lower(btrim(v_email));
  END IF;
  v := regexp_replace(v, '[<>"]', '', 'g');
  v := btrim(v);
  IF v = '' OR position('@' IN v) < 2 THEN
    RETURN NULL;
  END IF;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_from_allowed(p_from text, p_allowlist text[])
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from text := private.vendor_email_normalize_address(p_from);
  v_item text;
  v_domain text;
BEGIN
  IF v_from IS NULL THEN
    RETURN false;
  END IF;
  IF p_allowlist IS NULL OR cardinality(p_allowlist) = 0 THEN
    RETURN true;
  END IF;

  FOREACH v_item IN ARRAY p_allowlist LOOP
    v_item := lower(btrim(COALESCE(v_item, '')));
    IF v_item = '' THEN
      CONTINUE;
    END IF;
    IF v_item = v_from THEN
      RETURN true;
    END IF;
    IF left(v_item, 1) = '@' THEN
      v_domain := substr(v_item, 2);
    ELSIF position('@' IN v_item) = 0 THEN
      v_domain := v_item;
    ELSE
      v_domain := NULL;
    END IF;
    IF v_domain IS NOT NULL AND v_domain <> ''
       AND v_from LIKE '%@' || v_domain THEN
      RETURN true;
    END IF;
  END LOOP;

  RETURN false;
END;
$function$;
CREATE OR REPLACE FUNCTION private.vendor_email_thread_blob(p_raw jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := ''; v_headers jsonb;
BEGIN
  v := v || ' ' || lower(COALESCE(p_raw->>'inReplyTo', ''));
  v := v || ' ' || lower(COALESCE(p_raw->>'in_reply_to', ''));
  v := v || ' ' || lower(COALESCE(p_raw->>'references', ''));
  IF jsonb_typeof(p_raw->'headers') = 'object' THEN
    v_headers := p_raw->'headers';
    v := v || ' ' || lower(COALESCE(v_headers->>'in-reply-to', ''));
    v := v || ' ' || lower(COALESCE(v_headers->>'In-Reply-To', ''));
    v := v || ' ' || lower(COALESCE(v_headers->>'references', ''));
    v := v || ' ' || lower(COALESCE(v_headers->>'References', ''));
  END IF;
  IF jsonb_typeof(p_raw->'metadata') = 'object' THEN
    v := v || ' ' || lower(COALESCE(p_raw->'metadata'->>'inReplyTo', ''));
    v := v || ' ' || lower(COALESCE(p_raw->'metadata'->>'references', ''));
  END IF;
  RETURN btrim(v);
END;
$function$;
CREATE OR REPLACE FUNCTION private.verify_user_consent(p_consent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_consent public.user_consents%ROWTYPE;
  v_batch public.user_consent_batches%ROWTYPE;
  v_expected text;
  v_matches boolean := false;
BEGIN
  IF p_consent_id IS NULL THEN
    RAISE EXCEPTION 'LEGAL_CONSENT_ID_REQUIRED'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_consent
  FROM public.user_consents
  WHERE id = p_consent_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'consent_not_found'
    );
  END IF;

  SELECT * INTO v_batch
  FROM public.user_consent_batches
  WHERE id = v_consent.batch_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'consent_id', v_consent.id,
      'reason', 'batch_not_found'
    );
  END IF;

  IF v_batch.pdf_sha256 IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'consent_id', v_consent.id,
      'user_id', v_consent.user_id,
      'document_id', v_consent.document_id,
      'document_version', v_consent.document_version,
      'accepted_at', v_consent.accepted_at,
      'hash_matches', false,
      'pdf_sha256_present', false,
      'reason', 'pdf_sha256_missing'
    );
  END IF;

  v_expected := private.legal_acceptance_hmac(
    v_consent.user_id,
    v_consent.accepted_at,
    v_consent.document_id,
    v_consent.document_version,
    v_batch.pdf_sha256
  );
  v_matches := (v_expected = v_consent.acceptance_hash);

  RETURN jsonb_build_object(
    'ok', true,
    'consent_id', v_consent.id,
    'user_id', v_consent.user_id,
    'document_id', v_consent.document_id,
    'document_version', v_consent.document_version,
    'accepted_at', v_consent.accepted_at,
    'hash_matches', v_matches,
    'pdf_sha256_present', true,
    'reason', CASE WHEN v_matches THEN NULL ELSE 'hash_mismatch' END
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.accept_duty_alert(p_issue_id uuid)
 RETURNS duty_alerts
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.duty_alerts;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;

  UPDATE public.duty_alerts
  SET status = 'accepted'
  WHERE issue_id = p_issue_id
    AND target_user_id = (SELECT auth.uid())
    AND status = 'pending'
  RETURNING * INTO v_row;

  IF NOT FOUND THEN RAISE EXCEPTION 'DUTY_ALERT_ACCEPT_FAILED'; END IF;
  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.application_matches_module_slug(p_name text, p_domain_url text, p_api_url text, p_slug text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE lower(btrim(COALESCE(p_slug, '')))
    WHEN 'cleaning' THEN
      v.blob LIKE '%clean%'
    WHEN 'serwis' THEN
      v.blob LIKE '%serwis%' OR v.blob LIKE '%service%'
    WHEN 'flota' THEN
      v.blob LIKE '%flot%' OR v.blob LIKE '%fleet%'
    WHEN 'administracja' THEN
      v.blob LIKE '%administr%'
    WHEN 'home' THEN
      v.blob LIKE '%home%' OR v.blob LIKE '%mieszkan%'
    ELSE
      false
  END
  FROM (
    SELECT lower(
      concat_ws(
        ' ',
        COALESCE(p_name, ''),
        COALESCE(p_domain_url, ''),
        COALESCE(p_api_url, '')
      )
    ) AS blob
  ) v;
$function$;
CREATE OR REPLACE FUNCTION public.apply_vendor_email_event(p_to_address text, p_message_id text, p_from_address text, p_subject text, p_body_text text, p_parsed jsonb DEFAULT '{}'::jsonb, p_raw_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_message_id text := btrim(COALESCE(p_message_id, ''));
  v_parsed jsonb := COALESCE(p_parsed, '{}'::jsonb);
  v_ingest_id uuid; v_existing public.vendor_email_inbound_events%ROWTYPE;
  v_token text; v_thread text; v_dispatch public.issue_email_dispatches%ROWTYPE;
  v_channel public.vendor_email_channels%ROWTYPE; v_method text; v_event text;
  v_extracted jsonb := '{}'::jsonb; v_match jsonb;
  v_tpl public.vendor_email_inbound_templates%ROWTYPE; v_cand uuid;
  v_from_ok boolean; v_notify boolean := false; v_guess text;
BEGIN
  IF NOT private.vendor_email_is_service_role() THEN RAISE EXCEPTION 'Brak uprawnień.'; END IF;
  IF v_message_id = '' OR length(v_message_id) > 998 THEN RAISE EXCEPTION 'Brak lub nieprawidłowy Message-ID'; END IF;
  INSERT INTO public.vendor_email_inbound_events (message_id, from_address, to_address, subject, body_text, raw_payload, status)
  VALUES (v_message_id, NULLIF(btrim(COALESCE(p_from_address, '')), ''), NULLIF(btrim(COALESCE(p_to_address, '')), ''),
    NULLIF(left(btrim(COALESCE(p_subject, '')), 500), ''), NULLIF(left(COALESCE(p_body_text, ''), 20000), ''),
    COALESCE(p_raw_payload, '{}'::jsonb), 'received')
  ON CONFLICT (message_id) DO NOTHING RETURNING id INTO v_ingest_id;
  IF v_ingest_id IS NULL THEN
    SELECT * INTO v_existing FROM public.vendor_email_inbound_events WHERE message_id = v_message_id;
    RETURN jsonb_build_object('ingest_id', v_existing.id, 'issue_id', v_existing.issue_id, 'status', 'duplicate',
      'match_method', v_existing.match_method, 'notify_partner', false);
  END IF;
  v_method := lower(btrim(COALESCE(v_parsed->>'match_method', '')));
  v_event := lower(btrim(COALESCE(v_parsed->>'event_type', '')));
  IF jsonb_typeof(v_parsed->'extracted') = 'object' THEN v_extracted := v_parsed->'extracted'; END IF;
  v_token := private.vendor_email_extract_token(p_to_address, p_subject, p_body_text);
  IF v_token IS NOT NULL THEN
    SELECT * INTO v_dispatch FROM public.issue_email_dispatches WHERE correlation_token = v_token;
    IF v_dispatch.id IS NOT NULL THEN v_method := 'token'; END IF;
  END IF;
  IF v_dispatch.id IS NULL THEN
    v_thread := private.vendor_email_thread_blob(p_raw_payload);
    IF v_thread <> '' THEN
      SELECT d.* INTO v_dispatch FROM public.issue_email_dispatches d
      WHERE d.outbound_message_id IS NOT NULL AND btrim(d.outbound_message_id) <> ''
        AND position(lower(btrim(d.outbound_message_id)) IN v_thread) > 0
      ORDER BY d.sent_at DESC NULLS LAST, d.queued_at DESC LIMIT 1;
      IF v_dispatch.id IS NOT NULL THEN v_method := 'thread'; END IF;
    END IF;
  END IF;
  IF v_dispatch.id IS NULL AND NULLIF(btrim(COALESCE(v_extracted->>'vendor_ticket', '')), '') IS NOT NULL THEN
    SELECT d.* INTO v_dispatch FROM public.issue_email_dispatches d
      WHERE d.vendor_external_ref = btrim(v_extracted->>'vendor_ticket') ORDER BY d.queued_at DESC LIMIT 1;
    IF v_dispatch.id IS NOT NULL THEN v_method := 'vendor_ref'; END IF;
  END IF;
  IF v_dispatch.id IS NULL THEN
    FOR v_cand IN SELECT c.vendor_id FROM public.vendor_email_channels c
      WHERE c.is_enabled = true AND private.vendor_email_from_allowed(p_from_address, c.inbound_from_allowlist)
    LOOP
      IF v_dispatch.id IS NULL THEN
        SELECT d.* INTO v_dispatch FROM public.issue_email_dispatches d
        WHERE d.vendor_id = v_cand AND d.vendor_external_ref IS NOT NULL
          AND strpos(COALESCE(p_subject, '') || ' ' || COALESCE(p_body_text, ''), d.vendor_external_ref) > 0
        ORDER BY d.queued_at DESC LIMIT 1;
        IF v_dispatch.id IS NOT NULL THEN v_method := 'vendor_ref'; END IF;
      END IF;
      IF v_dispatch.id IS NULL THEN
        FOR v_tpl IN SELECT t.* FROM public.vendor_email_inbound_templates t WHERE t.vendor_id = v_cand
          ORDER BY CASE t.event_type WHEN 'completed' THEN 1 WHEN 'assigned_technician' THEN 2 WHEN 'rejected' THEN 3 ELSE 4 END
        LOOP
          IF v_tpl.subject_pattern IS NOT NULL AND btrim(v_tpl.subject_pattern) <> '' THEN
            v_match := private.vendor_email_match_template(v_tpl.subject_pattern, COALESCE(p_subject, ''));
            IF COALESCE((v_match->>'matched')::boolean, false) IS NOT TRUE THEN CONTINUE; END IF;
          END IF;
          v_match := private.vendor_email_match_template(v_tpl.body_pattern, COALESCE(p_body_text, ''));
          IF COALESCE((v_match->>'matched')::boolean, false) THEN
            SELECT d.* INTO v_dispatch FROM public.issue_email_dispatches d
              WHERE d.vendor_id = v_cand AND d.status IN ('queued', 'sent', 'failed') ORDER BY d.queued_at DESC LIMIT 1;
            v_event := v_tpl.event_type; v_extracted := COALESCE(v_match->'extracted', '{}'::jsonb) || v_extracted; v_method := 'template'; EXIT;
          END IF;
        END LOOP;
      END IF;
      EXIT WHEN v_dispatch.id IS NOT NULL;
    END LOOP;
  END IF;
  IF v_dispatch.id IS NOT NULL AND v_event NOT IN ('accepted', 'assigned_technician', 'completed', 'rejected') THEN
    v_guess := private.vendor_email_guess_event(p_subject, p_body_text);
    v_event := COALESCE(NULLIF(v_event, ''), v_guess, 'accepted');
  END IF;
  IF v_method NOT IN ('token', 'vendor_ref', 'template', 'thread', 'manual', 'unmatched') THEN
    v_method := CASE WHEN v_dispatch.id IS NULL THEN 'unmatched' ELSE COALESCE(NULLIF(v_method, ''), 'token') END;
  END IF;
  IF v_dispatch.id IS NOT NULL THEN
    SELECT * INTO v_channel FROM public.vendor_email_channels WHERE vendor_id = v_dispatch.vendor_id;
    v_from_ok := private.vendor_email_from_allowed(p_from_address, COALESCE(v_channel.inbound_from_allowlist, '{}'::text[]));
    IF NOT v_from_ok AND v_method NOT IN ('token', 'thread') THEN
      UPDATE public.vendor_email_inbound_events SET org_id = v_dispatch.org_id, vendor_id = v_dispatch.vendor_id,
        issue_id = v_dispatch.issue_id, dispatch_id = v_dispatch.id, match_method = 'unmatched', status = 'rejected',
        error_detail = 'sender_not_allowed', extracted = v_extracted WHERE id = v_ingest_id;
      RETURN jsonb_build_object('ingest_id', v_ingest_id, 'issue_id', v_dispatch.issue_id, 'status', 'rejected',
        'match_method', 'unmatched', 'notify_partner', false);
    END IF;
  END IF;
  IF v_dispatch.id IS NULL OR v_event NOT IN ('accepted', 'assigned_technician', 'completed', 'rejected') THEN
    SELECT EXISTS (SELECT 1 FROM public.vendor_email_channels c WHERE c.is_enabled = true
      AND COALESCE(cardinality(c.inbound_from_allowlist), 0) > 0
      AND private.vendor_email_from_allowed(p_from_address, c.inbound_from_allowlist)
      AND NOT private.inbound_is_noreply(p_from_address)) INTO v_notify;
    UPDATE public.vendor_email_inbound_events SET org_id = v_dispatch.org_id, vendor_id = v_dispatch.vendor_id,
      issue_id = v_dispatch.issue_id, dispatch_id = v_dispatch.id, match_method = 'unmatched', status = 'unmatched',
      extracted = v_extracted,
      error_detail = CASE WHEN v_dispatch.id IS NULL THEN 'dispatch_not_found' ELSE 'event_type_unknown' END
      WHERE id = v_ingest_id;
    RETURN jsonb_build_object('ingest_id', v_ingest_id, 'issue_id', v_dispatch.issue_id, 'status', 'unmatched',
      'match_method', 'unmatched', 'notify_partner', v_notify);
  END IF;
  PERFORM private.vendor_email_apply_matched(v_dispatch, v_event, v_extracted);
  UPDATE public.vendor_email_inbound_events SET org_id = v_dispatch.org_id, vendor_id = v_dispatch.vendor_id,
    issue_id = v_dispatch.issue_id, dispatch_id = v_dispatch.id, matched_event_type = v_event, extracted = v_extracted,
    match_method = v_method, status = 'applied', error_detail = NULL WHERE id = v_ingest_id;
  RETURN jsonb_build_object('ingest_id', v_ingest_id, 'issue_id', v_dispatch.issue_id, 'dispatch_id', v_dispatch.id,
    'status', 'applied', 'match_method', v_method, 'event_type', v_event, 'notify_partner', false);
END;
$function$;
CREATE OR REPLACE FUNCTION public.authorize_property_issue_transfer(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  UPDATE public.property_issues SET transfer_authorized_at = now() WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
