 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
  SELECT private.begin_legal_consent(
    p_user_id, p_source, p_email, p_ip_address, p_user_agent, p_document_ids
  );
$function$;
CREATE OR REPLACE FUNCTION public.broadcast_property_issue(p_issue_id uuid, p_scope issue_marketplace_scope)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF p_scope IS NULL THEN
    RAISE EXCEPTION 'ISSUE_BROADCAST_SCOPE_REQUIRED';
  END IF;

  UPDATE public.property_issues
  SET
    is_public_broadcast = true,
    marketplace_scope = p_scope
  WHERE id = p_issue_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.broadcast_property_issue(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.broadcast_property_issue(p_issue_id, 'serving'::public.issue_marketplace_scope);
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_access_vehicle_doc(object_name text, need_write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_folder text;
  v_vehicle_id uuid;
  v_org_id uuid;
  v_driver_id uuid;
BEGIN
  v_folder := (storage.foldername(object_name))[1];

  IF v_folder IS NULL OR v_folder !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RETURN false;
  END IF;

  v_vehicle_id := v_folder::uuid;

  SELECT v.org_id, v.assigned_driver_id
    INTO v_org_id, v_driver_id
  FROM public.vehicles v
  WHERE v.id = v_vehicle_id;

  IF v_org_id IS NULL THEN
    RETURN false;
  END IF;

  IF need_write THEN
    RETURN EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.org_id = v_org_id
        AND m.user_id = (SELECT auth.uid())
        AND COALESCE(m.is_active, true) = true
        AND lower(COALESCE(m.role, '')) IN ('owner', 'admin', 'coordinator', 'manager')
    );
  END IF;

  RETURN v_driver_id = (SELECT auth.uid())
     OR EXISTS (
       SELECT 1 FROM public.memberships m
       WHERE m.org_id = v_org_id
         AND m.user_id = (SELECT auth.uid())
         AND COALESCE(m.is_active, true) = true
     );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_manage_location(target_location_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
BEGIN
  -- Pobieramy organizację budynku
  SELECT org_id INTO v_org_id FROM cleaning_locations WHERE id = target_location_id;
  
  -- Jeśli brak budynku, dostęp zabroniony
  IF v_org_id IS NULL THEN RETURN false; END IF;
  
  -- Sprawdzamy uprawnienia (Owner, Manager, Admin, COORDINATOR)
  RETURN EXISTS (
    SELECT 1 FROM memberships
    WHERE org_id = v_org_id
    AND user_id = auth.uid()
    AND role ILIKE ANY (ARRAY['owner', 'manager', 'admin', 'coordinator'])
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_view_org_financials(target_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.memberships m
    JOIN public.organizations o ON o.id = m.org_id
    WHERE m.org_id = target_org_id
      AND m.user_id = (SELECT auth.uid())
      AND COALESCE(m.is_active, true) = true
      AND (
        lower(btrim(COALESCE(m.role, ''))) IN (
          'owner', 'admin', 'administrator', 'wlasciciel', 'właściciel'
        )
        OR (
          lower(btrim(COALESCE(m.role, ''))) IN ('coordinator', 'koordynator')
          AND (
            COALESCE(m.can_view_financials, false)
            OR COALESCE(m.can_view_billing, false)
            OR COALESCE(o.global_coordinator_view_financials, false)
            OR COALESCE((m.permissions ->> 'can_view_financials')::boolean, false)
          )
        )
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.cancel_property_issue(p_issue_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF length(v_reason) < 3 THEN
    RAISE EXCEPTION 'ISSUE_CANCEL_REASON_REQUIRED';
  END IF;
  UPDATE public.property_issues
  SET status = 'cancelled', cancel_reason = v_reason
  WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ceil_started_hours(p_hours numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_hours IS NULL THEN NULL
    WHEN p_hours <= 0 THEN 0
    ELSE CEIL(p_hours)
  END;
$function$;
CREATE OR REPLACE FUNCTION public.check_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.memberships
    WHERE user_id = auth.uid() AND role IN ('owner', 'coordinator')
  );
$function$;
CREATE OR REPLACE FUNCTION public.check_location_manager(target_location_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
BEGIN
  SELECT org_id INTO v_org_id FROM cleaning_locations WHERE id = target_location_id;
  IF v_org_id IS NULL THEN RETURN false; END IF;
  
  -- Sprawdź czy user jest szefem/managerem w tej organizacji
  RETURN EXISTS (
    SELECT 1 FROM memberships
    WHERE org_id = v_org_id
    AND user_id = auth.uid()
    AND role ILIKE ANY (ARRAY['owner', 'manager', 'admin', 'coordinator'])
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_location_proximity(p_location_id uuid, p_user_latitude double precision, p_user_longitude double precision)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lat DOUBLE PRECISION;
  v_lng DOUBLE PRECISION;
  v_geofence_radius_meters DOUBLE PRECISION;
  v_location_geo GEOGRAPHY;
  v_user_geo GEOGRAPHY;
  v_distance_meters DOUBLE PRECISION;
  v_is_within_range BOOLEAN;
BEGIN
  -- Pobieramy tylko nowe współrzędne i promień (domyślnie 100m)
  SELECT 
    latitude,
    longitude,
    COALESCE(geofence_radius_meters, 100.0)
  INTO 
    v_lat,
    v_lng,
    v_geofence_radius_meters
  FROM public.cleaning_locations
  WHERE id = p_location_id;

  -- Jeśli budynek nie ma wpisanych współrzędnych, przerywamy
  IF v_lat IS NULL OR v_lng IS NULL THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Obiekt nie posiada skonfigurowanych współrzędnych GPS (latitude/longitude)'
    );
  END IF;

  -- Budowanie punktów geograficznych (WGS84)
  v_location_geo := ST_SetSRID(ST_MakePoint(v_lng, v_lat), 4326)::GEOGRAPHY;
  v_user_geo := ST_SetSRID(ST_MakePoint(p_user_longitude, p_user_latitude), 4326)::GEOGRAPHY;

  -- Obliczenia precyzyjne za pomocą PostGIS
  v_distance_meters := ST_Distance(v_location_geo, v_user_geo, true);
  v_is_within_range := ST_DWithin(v_location_geo, v_user_geo, v_geofence_radius_meters, true);

  RETURN json_build_object(
    'success', true,
    'is_within_range', v_is_within_range,
    'distance_meters', ROUND(v_distance_meters::numeric, 2),
    'geofence_radius_meters', v_geofence_radius_meters,
    'user_coordinates', json_build_object('lat', p_user_latitude, 'lng', p_user_longitude),
    'location_coordinates', json_build_object('lat', v_lat, 'lng', v_lng)
  );
END;
$function$;
