 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.memberships
    WHERE user_id = auth.uid() AND org_id = p_org_id
  );
$function$;
CREATE OR REPLACE FUNCTION public.claim_fleet_notification_jobs(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
DECLARE v_id uuid; v_items jsonb := '[]'::jsonb; v_payload jsonb; v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 10), 50));
BEGIN
  FOR v_id IN
    SELECT d.id FROM public.fleet_notification_dispatches d
    WHERE d.status IN ('pending', 'failed', 'processing') AND d.next_attempt_at <= now() AND d.attempt_count < 12
    ORDER BY d.next_attempt_at FOR UPDATE OF d SKIP LOCKED LIMIT v_limit
  LOOP
    v_payload := private.lease_fleet_notification_dispatch(v_id);
    IF v_payload IS NOT NULL AND (v_payload->>'already_sent') IS DISTINCT FROM 'true' THEN
      v_items := v_items || jsonb_build_array(v_payload);
    END IF;
  END LOOP;
  RETURN v_items;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_inbound_reject_notice(p_from_address text, p_to_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_from text := lower(btrim(COALESCE(p_from_address, '')));
  v_email text; v_alias text := private.inbound_normalize_alias(p_to_address);
  v_box public.org_inbound_mailboxes%ROWTYPE;
BEGIN
  IF NOT private.vendor_email_is_service_role() THEN RAISE EXCEPTION 'Brak uprawnień.'; END IF;
  v_email := substring(v_from from '<([^>]+)>');
  IF v_email IS NOT NULL THEN v_from := lower(btrim(v_email)); END IF;
  IF private.inbound_is_noreply(v_from) THEN RETURN jsonb_build_object('send', false, 'reason', 'noreply'); END IF;
  IF NOT private.inbound_looks_like_org_alias(v_alias) THEN RETURN jsonb_build_object('send', false, 'reason', 'not_org_alias'); END IF;
  SELECT * INTO v_box FROM public.org_inbound_mailboxes WHERE alias_local_part = v_alias LIMIT 1;
  IF v_box.id IS NOT NULL AND v_box.is_enabled THEN RETURN jsonb_build_object('send', false, 'reason', 'mailbox_ok'); END IF;
  IF EXISTS (SELECT 1 FROM public.inbound_reject_notices n WHERE n.from_address = v_from AND n.to_alias = v_alias AND n.created_at > now() - interval '1 hour') THEN
    RETURN jsonb_build_object('send', false, 'reason', 'rate_limited');
  END IF;
  INSERT INTO public.inbound_reject_notices (from_address, to_alias) VALUES (v_from, v_alias);
  RETURN jsonb_build_object('send', true, 'reason', CASE WHEN v_box.id IS NULL THEN 'unknown_alias' ELSE 'mailbox_disabled' END);
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_legal_welcome_jobs(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
DECLARE
  v_id uuid;
  v_items jsonb := '[]'::jsonb;
  v_payload jsonb;
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 10), 50));
BEGIN
  FOR v_id IN
    SELECT d.id
    FROM public.legal_welcome_dispatches d
    JOIN public.user_consent_batches b ON b.id = d.batch_id
    WHERE b.pdf_storage_path IS NOT NULL
      AND (
        (d.status IN ('pending', 'failed') AND d.next_attempt_at <= now())
        OR (d.status = 'processing' AND d.next_attempt_at <= now())
      )
      AND d.attempt_count < 12
    ORDER BY d.next_attempt_at
    FOR UPDATE OF d SKIP LOCKED
    LIMIT v_limit
  LOOP
    v_payload := private.lease_legal_welcome_dispatch(v_id);
    IF v_payload IS NOT NULL AND (v_payload->>'already_sent') IS DISTINCT FROM 'true' THEN
      v_items := v_items || jsonb_build_array(v_payload);
    END IF;
  END LOOP;

  RETURN v_items;
END;
$function$;
