CREATE OR REPLACE FUNCTION public.close_stale_cleaning_work_sessions()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  closed_count integer;
BEGIN
  UPDATE public.cleaning_work_sessions
  SET
    status = 'auto_closed',
    close_reason = 'stale_timeout',
    ended_at = started_at + interval '8 hours',
    needs_review = true
  WHERE status = 'open'
    AND started_at < now() - interval '8 hours';
  GET DIAGNOSTICS closed_count = ROW_COUNT;
  RETURN closed_count;
END;
$function$;
