CREATE OR REPLACE FUNCTION public.decline_property_issue_transfer(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  UPDATE public.property_issues SET is_transfer_requested = false WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_company_matches_location_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  loc_org uuid;
  comp_org uuid;
BEGIN
  SELECT cl.org_id INTO loc_org
  FROM public.cleaning_locations cl
  WHERE cl.id = NEW.location_id;

  SELECT c.org_id INTO comp_org
  FROM public.companies c
  WHERE c.id = NEW.company_id;

  IF loc_org IS NULL THEN
    RAISE EXCEPTION 'location not found';
  END IF;

  IF comp_org IS NULL THEN
    RAISE EXCEPTION 'company not found';
  END IF;

  IF loc_org IS DISTINCT FROM comp_org THEN
    RAISE EXCEPTION 'company org_id must match cleaning_locations.org_id for this location';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_org_duty_eligible_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.org_duty_state
  SET
    is_duty_enabled = false,
    active_user_id = NULL,
    updated_at = now()
  WHERE org_id = OLD.org_id
    AND active_user_id = OLD.user_id;
  RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_org_duty_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_duty_enabled THEN
    IF NEW.active_user_id IS NULL THEN
      RAISE EXCEPTION 'active_user_id is required when duty is enabled'
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.org_duty_eligible e
      WHERE e.org_id = NEW.org_id
        AND e.user_id = NEW.active_user_id
    ) THEN
      RAISE EXCEPTION 'active_user_id must belong to the duty eligible pool'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_property_issue_billing_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoiced boolean;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.issue_id IS DISTINCT FROM OLD.issue_id
       OR NEW.org_id IS DISTINCT FROM OLD.org_id
       OR NEW.original IS DISTINCT FROM OLD.original
       OR NEW.captured_at IS DISTINCT FROM OLD.captured_at
       OR NEW.captured_by IS DISTINCT FROM OLD.captured_by THEN
      RAISE EXCEPTION 'ISSUE_BILLING_ORIGINAL_LOCKED';
    END IF;

    SELECT COALESCE(is_invoiced, false) INTO v_invoiced
    FROM public.property_issues
    WHERE id = NEW.issue_id;

    IF v_invoiced THEN
      RAISE EXCEPTION 'ISSUE_BILLING_LOCKED';
    END IF;

    IF NEW.invoice_amount IS DISTINCT FROM OLD.invoice_amount THEN
      NEW.adjusted_at := now();
      NEW.adjusted_by := auth.uid();
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_vehicle_document_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (
    SELECT count(*)
    FROM public.vehicle_documents d
    WHERE d.vehicle_id = NEW.vehicle_id
      AND d.kind = NEW.kind
      AND d.id IS DISTINCT FROM NEW.id
  ) >= 3 THEN
    RAISE EXCEPTION 'A vehicle may have at most 3 files per document type';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_vehicle_tire_set_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (
    SELECT count(*)
    FROM public.vehicle_tire_sets s
    WHERE s.vehicle_id = NEW.vehicle_id
      AND s.id IS DISTINCT FROM NEW.id
  ) >= 2 THEN
    RAISE EXCEPTION 'A vehicle may have at most 2 tire sets';
  END IF;

  RETURN NEW;
END;
$function$;
