CREATE OR REPLACE FUNCTION public.list_location_module_presence(p_location_master_id uuid)
 RETURNS TABLE(org_id uuid, org_name text, partner_legal_entity_id uuid, is_cleaning boolean, is_maintenance boolean, is_admin boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_orgs uuid[]; BEGIN IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'MANDATE_AUTH_REQUIRED'; END IF; IF p_location_master_id IS NULL THEN RAISE EXCEPTION 'MANDATE_FORBIDDEN'; END IF; v_orgs := public.current_user_org_ids(); IF NOT public.is_platform_admin() AND NOT EXISTS (SELECT 1 FROM public.cleaning_locations cl WHERE cl.location_master_id = p_location_master_id AND cl.org_id = ANY (v_orgs)) THEN RAISE EXCEPTION 'MANDATE_FORBIDDEN'; END IF; RETURN QUERY SELECT cl.org_id, COALESCE(o.name, cl.org_id::text), (SELECT e.legal_entity_id FROM public.org_legal_entity_enrollments e WHERE e.org_id = cl.org_id ORDER BY e.created_at LIMIT 1), COALESCE(cl.is_cleaning_active, false), COALESCE(cl.is_maintenance_active, false), COALESCE(cl.is_admin_active, false) FROM public.cleaning_locations cl LEFT JOIN public.organizations o ON o.id = cl.org_id WHERE cl.location_master_id = p_location_master_id AND cl.status = 'active'; END; $function$;
CREATE OR REPLACE FUNCTION public.list_org_verification_alerts(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL
     OR (
       NOT public.is_org_management(p_org_id)
       AND NOT public.is_platform_admin()
     )
  THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_UNVERIFIED_FORBIDDEN';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(item ORDER BY item ->> 'createdAt')
      FROM (
        SELECT jsonb_build_object(
          'legalEntityId', le.id,
          'orgId', e.org_id,
          'orgName', o.name,
          'kind', le.kind,
          'nip', le.nip_normalized,
          'shortName', le.short_name,
          'createdAt', le.created_at,
          'reason', le.verification_reason,
          'overlayKind', CASE
            WHEN le.kind IN (
              'housing_community'::public.legal_entity_kind,
              'housing_cooperative'::public.legal_entity_kind
            ) THEN 'community'
            ELSE 'company'
          END,
          'overlayId', COALESCE(c.id, co.id)
        ) AS item
        FROM public.legal_entities le
        INNER JOIN public.org_legal_entity_enrollments e
          ON e.legal_entity_id = le.id
         AND e.org_id = p_org_id
         AND e.status = 'active'
        INNER JOIN public.organizations o ON o.id = e.org_id
        LEFT JOIN public.communities c
          ON c.org_id = e.org_id
         AND c.legal_entity_id = le.id
        LEFT JOIN public.companies co
          ON co.legal_entity_id = le.id
        WHERE le.verification_status = 'pending_manual'::public.legal_entity_verification_status
      ) s
    ),
    '[]'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.list_pending_duty_push_jobs()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  SELECT COALESCE(jsonb_agg(private.duty_push_job_payload(a) ORDER BY a.created_at), '[]'::jsonb)
  FROM public.duty_alerts a
  WHERE a.status = 'pending'
    AND a.attempt_count < a.max_attempts
    AND (a.last_pushed_at IS NULL OR a.last_pushed_at <= now() - interval '45 seconds');
$function$;
CREATE OR REPLACE FUNCTION public.list_platform_verification_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_VERIFY_PLATFORM_ONLY';
  END IF;

  RETURN COALESCE(
    (
      SELECT jsonb_agg(item ORDER BY item ->> 'createdAt')
      FROM (
        SELECT jsonb_build_object(
          'legalEntityId', le.id,
          'orgId', le.created_by_org_id,
          'orgName', o.name,
          'kind', le.kind,
          'nip', le.nip_normalized,
          'shortName', le.short_name,
          'createdAt', le.created_at,
          'reason', le.verification_reason,
          'overlayKind', CASE
            WHEN le.kind IN (
              'housing_community'::public.legal_entity_kind,
              'housing_cooperative'::public.legal_entity_kind
            ) THEN 'community'
            ELSE 'company'
          END,
          'overlayId', COALESCE(c.id, co.id)
        ) AS item
        FROM public.legal_entities le
        LEFT JOIN public.organizations o ON o.id = le.created_by_org_id
        LEFT JOIN LATERAL (
          SELECT id
          FROM public.communities
          WHERE legal_entity_id = le.id
          ORDER BY created_at
          LIMIT 1
        ) c ON true
        LEFT JOIN LATERAL (
          SELECT id
          FROM public.companies
          WHERE legal_entity_id = le.id
          ORDER BY created_at
          LIMIT 1
        ) co ON true
        WHERE le.verification_status = 'pending_manual'::public.legal_entity_verification_status
      ) s
    ),
    '[]'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_property_issue_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_actor uuid;
BEGIN
  v_actor := auth.uid();

  IF TG_OP = 'INSERT' THEN
    v_org := NEW.org_id;
    IF NEW.assigned_staff_id IS NOT NULL THEN
      INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
      VALUES (
        v_org, NEW.id, 'claimed', v_actor,
        jsonb_build_object('assigned_staff_id', NEW.assigned_staff_id)
      );
    END IF;
    RETURN NEW;
  END IF;

  v_org := COALESCE(NEW.org_id, OLD.org_id);

  IF OLD.assigned_staff_id IS NULL AND NEW.assigned_staff_id IS NOT NULL THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (
      v_org, NEW.id, 'claimed', v_actor,
      jsonb_build_object('assigned_staff_id', NEW.assigned_staff_id)
    );
  END IF;

  IF (OLD.started_at IS NULL AND NEW.started_at IS NOT NULL)
     OR (OLD.status IS DISTINCT FROM 'in_progress' AND NEW.status = 'in_progress') THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (v_org, NEW.id, 'started', v_actor, '{}'::jsonb);
  END IF;

  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (v_org, NEW.id, 'cancelled', v_actor, jsonb_build_object('reason', NEW.cancel_reason));
  END IF;

  IF NEW.cancel_requested_at IS NOT NULL AND OLD.cancel_requested_at IS NULL THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (v_org, NEW.id, 'cancel_requested', v_actor, jsonb_build_object('reason', NEW.cancel_request_reason));
  END IF;

  IF NEW.is_transfer_requested IS TRUE AND OLD.is_transfer_requested IS NOT TRUE THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (
      v_org, NEW.id, 'transfer_requested', v_actor,
      jsonb_build_object('transfer_to_vendor_id', NEW.transfer_to_vendor_id, 'reason', NEW.transfer_reason)
    );
  END IF;

  IF NEW.transfer_authorized_at IS NOT NULL AND OLD.transfer_authorized_at IS NULL THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (
      v_org, NEW.id, 'transfer_accepted', v_actor,
      jsonb_build_object('transfer_to_vendor_id', NEW.transfer_to_vendor_id)
    );
  END IF;

  IF NEW.is_transfer_requested IS NOT TRUE
     AND OLD.is_transfer_requested IS TRUE
     AND NEW.delegated_vendor_id IS NOT DISTINCT FROM OLD.delegated_vendor_id
     AND NEW.transfer_authorized_at IS NULL THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (v_org, NEW.id, 'transfer_rejected', v_actor, '{}'::jsonb);
  END IF;

  IF NEW.gps_start_override IS TRUE AND OLD.gps_start_override IS NOT TRUE THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (
      v_org, NEW.id, 'gps_start_override', v_actor,
      jsonb_build_object(
        'distance_m', NEW.gps_start_override_distance_m,
        'lat', NEW.gps_start_lat,
        'lng', NEW.gps_start_lng
      )
    );
  END IF;

  IF NEW.dispatcher_forced_next IS TRUE AND OLD.dispatcher_forced_next IS NOT TRUE THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (
      v_org, NEW.id, 'dispatcher_forced', v_actor,
      jsonb_build_object('assigned_staff_id', NEW.assigned_staff_id)
    );
  END IF;

  IF NEW.dispatcher_forced_next IS NOT TRUE AND OLD.dispatcher_forced_next IS TRUE THEN
    INSERT INTO public.issue_lifecycle_events (org_id, issue_id, event_type, actor_user_id, payload)
    VALUES (v_org, NEW.id, 'dispatcher_unforced', v_actor, '{}'::jsonb);
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_rate_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (OLD.base_hourly_rate IS DISTINCT FROM NEW.base_hourly_rate)
     OR (OLD.snow_hourly_rate IS DISTINCT FROM NEW.snow_hourly_rate)
     OR (OLD.extra_hourly_rate IS DISTINCT FROM NEW.extra_hourly_rate)
     OR (OLD.fixed_salary IS DISTINCT FROM NEW.fixed_salary) THEN
    INSERT INTO public.staff_rate_history (
      staff_id,
      base_hourly_rate,
      snow_hourly_rate,
      extra_hourly_rate,
      fixed_salary,
      changed_by
    )
    VALUES (
      NEW.id,
      NEW.base_hourly_rate,
      NEW.snow_hourly_rate,
      COALESCE(NEW.extra_hourly_rate, 0),
      NEW.fixed_salary,
      auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.lookup_legal_entity_by_nip(p_nip text, p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_digits text;
  v_row public.legal_entities%ROWTYPE;
  v_enrolled boolean;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL OR NOT public.is_org_management(p_org_id) THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_LOOKUP_FORBIDDEN'
      USING HINT = 'Only organisation management may look up a contractor by NIP.';
  END IF;

  v_digits := regexp_replace(COALESCE(p_nip, ''), '[^0-9]', '', 'g');
  IF NOT public.nip_checksum_ok(v_digits) THEN
    RETURN jsonb_build_object(
      'status', 'invalid_nip'::text,
      'entity', NULL,
      'alreadyEnrolledInThisOrg', false
    );
  END IF;

  SELECT * INTO v_row
  FROM public.legal_entities
  WHERE nip_normalized = v_digits;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'not_in_domio'::text,
      'entity', NULL,
      'alreadyEnrolledInThisOrg', false
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.org_legal_entity_enrollments e
    WHERE e.org_id = p_org_id
      AND e.legal_entity_id = v_row.id
  ) INTO v_enrolled;

  RETURN jsonb_build_object(
    'status', 'exists_in_domio'::text,
    'alreadyEnrolledInThisOrg', v_enrolled,
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.lookup_location_by_public_qr_token(p_token text)
 RETURNS TABLE(id uuid, org_id uuid, address text, allow_anonymous_qr_reports boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token text := trim(COALESCE(p_token, ''));
  v_uuid uuid;
BEGIN
  IF length(v_token) < 16 THEN
    RETURN;
  END IF;

  BEGIN
    v_uuid := v_token::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      v_uuid := NULL;
  END;

  RETURN QUERY
  SELECT
    cl.id,
    cl.org_id,
    cl.address,
    COALESCE(cl.allow_anonymous_qr_reports, true)
  FROM public.cleaning_locations cl
  WHERE COALESCE(cl.is_maintenance_active, true) = true
    AND (cl.status IS NULL OR cl.status IN ('active', 'archived'))
    AND (
      (v_uuid IS NOT NULL AND (cl.issue_qr_token = v_uuid OR cl.public_report_token = v_uuid))
      OR (cl.qr_code_token IS NOT NULL AND cl.qr_code_token = v_token)
    )
  LIMIT 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.insert_public_qr_issue(p_token text, p_description text, p_reporter_name text, p_reporter_phone text, p_photos_before text[] DEFAULT NULL::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_location public.cleaning_locations%ROWTYPE;
  v_issue_id uuid;
  v_description text := trim(COALESCE(p_description, ''));
  v_name text := trim(COALESCE(p_reporter_name, ''));
  v_phone text := trim(COALESCE(p_reporter_phone, ''));
BEGIN
  IF length(v_description) < 1 OR length(v_description) > 500 THEN
    RAISE EXCEPTION 'Nieprawidłowy opis zgłoszenia';
  END IF;
  IF length(v_name) < 1 OR length(v_name) > 120 THEN
    RAISE EXCEPTION 'Nieprawidłowe imię zgłaszającego';
  END IF;
  IF length(v_phone) < 1 OR length(v_phone) > 40 THEN
    RAISE EXCEPTION 'Nieprawidłowy numer telefonu';
  END IF;

  SELECT cl.*
  INTO v_location
  FROM public.lookup_location_by_public_qr_token(p_token) loc
  JOIN public.cleaning_locations cl ON cl.id = loc.id
  LIMIT 1;

  IF v_location.id IS NULL THEN
    RAISE EXCEPTION 'Nieprawidłowy lub nieaktywny token QR';
  END IF;

  IF COALESCE(v_location.allow_anonymous_qr_reports, true) = false THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'To zgłoszenie wymaga zalogowania';
    END IF;
    IF NOT public.is_org_member(v_location.org_id)
       AND NOT public.has_location_access(v_location.id) THEN
      RAISE EXCEPTION 'Brak uprawnień do zgłoszenia usterki w tym budynku';
    END IF;
  END IF;

  INSERT INTO public.property_issues (
    location_id,
    org_id,
    description,
    reporter_name,
    reporter_phone,
    reporter_type,
    priority,
    status,
    photos_before,
    source,
    reporter_id
  )
  VALUES (
    v_location.id,
    v_location.org_id,
    v_description,
    v_name,
    v_phone,
    'tenant',
    'medium',
    'pending_admin_approval',
    CASE WHEN p_photos_before IS NOT NULL AND cardinality(p_photos_before) > 0 THEN p_photos_before ELSE NULL END,
    'public_qr',
    auth.uid()
  )
  RETURNING id INTO v_issue_id;

  RETURN v_issue_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_duty_alert_pushed(p_alert_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.duty_alerts;
BEGIN
  UPDATE public.duty_alerts
  SET
    attempt_count = attempt_count + 1,
    last_pushed_at = now(),
    status = CASE WHEN attempt_count + 1 >= max_attempts THEN 'exhausted' ELSE status END
  WHERE id = p_alert_id AND status = 'pending'
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'DUTY_ALERT_NOT_PENDING');
  END IF;

  RETURN jsonb_build_object('ok', true, 'alert_id', v_row.id, 'status', v_row.status, 'attempt_count', v_row.attempt_count);
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_fleet_notification_failed(p_dispatch_id uuid, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_attempts integer;
BEGIN
  SELECT attempt_count INTO v_attempts FROM public.fleet_notification_dispatches WHERE id = p_dispatch_id;
  UPDATE public.fleet_notification_dispatches
  SET status = 'failed',
      last_error = left(COALESCE(NULLIF(btrim(p_error), ''), 'SMTP send failed'), 2000),
      next_attempt_at = now() + (interval '5 minutes' * GREATEST(1, COALESCE(v_attempts, 1)))
  WHERE id = p_dispatch_id AND status IS DISTINCT FROM 'sent';
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_fleet_notification_sent(p_dispatch_id uuid, p_message_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  UPDATE public.fleet_notification_dispatches
  SET status = 'sent', sent_at = COALESCE(sent_at, now()), last_error = NULL,
      provider_message_id = COALESCE(NULLIF(btrim(COALESCE(p_message_id, '')), ''), provider_message_id)
  WHERE id = p_dispatch_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_issue_email_dispatch_failed(p_issue_id uuid, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_dispatch public.issue_email_dispatches%ROWTYPE;
BEGIN
  SELECT * INTO v_dispatch
  FROM public.issue_email_dispatches
  WHERE issue_id = p_issue_id
  FOR UPDATE;

  IF v_dispatch.id IS NULL THEN
    RAISE EXCEPTION 'Brak wątku wysyłki e-mail dla zgłoszenia.';
  END IF;

  PERFORM private.vendor_email_require_management(v_dispatch.org_id);

  UPDATE public.issue_email_dispatches
  SET
    status = 'failed',
    dispatch_error = NULLIF(btrim(COALESCE(p_error, '')), '')
  WHERE id = v_dispatch.id;

  UPDATE public.property_issues
  SET email_dispatch_status = 'failed'
  WHERE id = p_issue_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_issue_email_dispatched(p_issue_id uuid, p_outbound_message_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_dispatch public.issue_email_dispatches%ROWTYPE;
BEGIN
  SELECT * INTO v_dispatch
  FROM public.issue_email_dispatches
  WHERE issue_id = p_issue_id
  FOR UPDATE;

  IF v_dispatch.id IS NULL THEN
    RAISE EXCEPTION 'Brak wątku wysyłki e-mail dla zgłoszenia.';
  END IF;

  PERFORM private.vendor_email_require_management(v_dispatch.org_id);

  UPDATE public.issue_email_dispatches
  SET
    status = 'sent',
    sent_at = COALESCE(sent_at, now()),
    dispatch_error = NULL,
    outbound_message_id = COALESCE(
      NULLIF(btrim(COALESCE(p_outbound_message_id, '')), ''),
      outbound_message_id
    )
  WHERE id = v_dispatch.id;

  UPDATE public.property_issues
  SET email_dispatch_status = 'sent'
  WHERE id = p_issue_id;

  PERFORM private.vendor_email_append_lifecycle(
    v_dispatch.org_id,
    p_issue_id,
    'email_sent',
    jsonb_build_object(
      'dispatch_id', v_dispatch.id,
      'correlation_token', v_dispatch.correlation_token
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_legal_welcome_failed(p_dispatch_id uuid, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_attempts integer;
BEGIN
  SELECT attempt_count INTO v_attempts
  FROM public.legal_welcome_dispatches
  WHERE id = p_dispatch_id;

  UPDATE public.legal_welcome_dispatches
  SET
    status = 'failed',
    last_error = left(COALESCE(NULLIF(btrim(p_error), ''), 'SMTP send failed'), 2000),
    next_attempt_at = now() + (interval '5 minutes' * GREATEST(1, COALESCE(v_attempts, 1)))
  WHERE id = p_dispatch_id
    AND status IS DISTINCT FROM 'sent';
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_legal_welcome_sent(p_dispatch_id uuid, p_message_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  UPDATE public.legal_welcome_dispatches
  SET
    status = 'sent',
    sent_at = COALESCE(sent_at, now()),
    last_error = NULL,
    provider_message_id = COALESCE(NULLIF(btrim(COALESCE(p_message_id, '')), ''), provider_message_id)
  WHERE id = p_dispatch_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_resident_order_dispatch_failed(p_order_id uuid, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.resident_orders%ROWTYPE;
  v_actor uuid := (SELECT auth.uid());
BEGIN
  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role'
     AND NOT public.can_manage_resident_orders(v_order.org_id) THEN
    RAISE EXCEPTION 'Brak uprawnień.';
  END IF;

  UPDATE public.resident_orders
  SET
    status = 'dispatch_failed',
    dispatch_error = NULLIF(btrim(COALESCE(p_error, '')), '')
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(
    p_order_id,
    v_actor,
    'dispatch_failed',
    jsonb_build_object('error', COALESCE(p_error, ''))
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_resident_order_dispatched(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.resident_orders%ROWTYPE;
  v_actor uuid := (SELECT auth.uid());
BEGIN
  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role'
     AND NOT public.can_manage_resident_orders(v_order.org_id) THEN
    RAISE EXCEPTION 'Brak uprawnień.';
  END IF;

  UPDATE public.resident_orders
  SET
    status = 'dispatch_sent',
    dispatched_at = now(),
    dispatch_error = NULL
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(p_order_id, v_actor, 'dispatch_sent', '{}'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_resident_order_offline(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_order public.resident_orders%ROWTYPE;
BEGIN
  v_actor := private.resident_order_require_actor();

  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  PERFORM private.resident_order_require_community_management(v_order.community_id);

  IF v_order.status NOT IN ('pending', 'dispatch_failed') THEN
    RAISE EXCEPTION 'Tego zamówienia nie można oznaczyć jako zamówione poza systemem.';
  END IF;

  UPDATE public.resident_orders
  SET status = 'ordered_offline'
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(p_order_id, v_actor, 'ordered_offline', '{}'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.materials_used_total(p_materials jsonb)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (
      SELECT ROUND(SUM(
        COALESCE((item ->> 'quantity')::numeric, 0)
        * COALESCE((item ->> 'unit_cost')::numeric, 0)
      ), 2)
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(p_materials) = 'array' THEN p_materials ELSE '[]'::jsonb END
      ) AS item
    ),
    0
  );
$function$;
CREATE OR REPLACE FUNCTION public.merge_immutable_issue_comments(p_old jsonb, p_new jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  WITH old_imm AS (
    SELECT value AS item
    FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(p_old) = 'array' THEN p_old ELSE '[]'::jsonb END
    )
    WHERE COALESCE((value ->> 'immutable')::boolean, false)
  ),
  new_arr AS (
    SELECT value AS item
    FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(p_new) = 'array' THEN p_new ELSE '[]'::jsonb END
    )
  ),
  new_without_imm AS (
    SELECT n.item
    FROM new_arr n
    WHERE NOT EXISTS (
      SELECT 1
      FROM old_imm o
      WHERE COALESCE(o.item ->> 'id', '') <> ''
        AND (o.item ->> 'id') = (n.item ->> 'id')
    )
  )
  SELECT COALESCE((SELECT jsonb_agg(item) FROM old_imm), '[]'::jsonb)
      || COALESCE((SELECT jsonb_agg(item) FROM new_without_imm), '[]'::jsonb);
$function$;
CREATE OR REPLACE FUNCTION public.normalize_pl_postal(p_raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN regexp_replace(COALESCE(p_raw, ''), '[^0-9]', '', 'g') ~ '^[0-9]{5}$'
      THEN substr(regexp_replace(p_raw, '[^0-9]', '', 'g'), 1, 2)
        || '-'
        || substr(regexp_replace(p_raw, '[^0-9]', '', 'g'), 3, 3)
    WHEN COALESCE(p_raw, '') ~ '^[0-9]{2}-[0-9]{3}$' THEN p_raw
    ELSE NULL
  END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_protocol_org_code(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text;
BEGIN
  v := upper(regexp_replace(COALESCE(p_raw, ''), '[^a-zA-Z0-9]', '', 'g'));
  IF length(v) > 12 THEN
    v := left(v, 12);
  END IF;
  IF length(v) < 2 THEN
    v := rpad(v, 2, 'X');
  END IF;
  RETURN v;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ensure_org_serwis_billing_settings(p_org_id uuid)
 RETURNS org_serwis_billing_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.org_serwis_billing_settings;
  v_slug text;
  v_base text;
  v_code text;
  v_i integer := 0;
  v_suffix text;
BEGIN
  SELECT * INTO v_row
  FROM public.org_serwis_billing_settings
  WHERE org_id = p_org_id;

  IF FOUND THEN
    RETURN v_row;
  END IF;

  SELECT slug INTO v_slug
  FROM public.organizations
  WHERE id = p_org_id;

  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'ISSUE_PROTOCOL_ORG_REQUIRED';
  END IF;

  v_base := public.normalize_protocol_org_code(v_slug);
  v_code := v_base;

  WHILE EXISTS (
    SELECT 1
    FROM public.org_serwis_billing_settings s
    WHERE s.protocol_org_code = v_code
  )
  LOOP
    v_i := v_i + 1;
    IF v_i > 99 THEN
      RAISE EXCEPTION 'PROTOCOL_ORG_CODE_TAKEN';
    END IF;
    v_suffix := v_i::text;
    v_code := left(v_base, GREATEST(2, 12 - length(v_suffix))) || v_suffix;
  END LOOP;

  INSERT INTO public.org_serwis_billing_settings (
    org_id,
    protocol_org_code
  )
  VALUES (p_org_id, v_code)
  ON CONFLICT (org_id) DO UPDATE
    SET protocol_org_code = public.org_serwis_billing_settings.protocol_org_code
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.assign_next_protocol_number(p_org_id uuid, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year integer;
  v_code text;
  v_next integer;
  v_settings public.org_serwis_billing_settings;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'ISSUE_PROTOCOL_ORG_REQUIRED';
  END IF;

  v_settings := public.ensure_org_serwis_billing_settings(p_org_id);
  v_code := v_settings.protocol_org_code;
  v_year := EXTRACT(YEAR FROM timezone('Europe/Warsaw', COALESCE(p_at, now())))::integer;

  INSERT INTO public.org_serwis_protocol_counters (org_id, year, last_number)
  VALUES (p_org_id, v_year, 1)
  ON CONFLICT (org_id, year) DO UPDATE
    SET last_number = public.org_serwis_protocol_counters.last_number + 1
  RETURNING last_number INTO v_next;

  RETURN lpad(v_next::text, 4, '0') || '/' || v_year::text || '/' || v_code;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_org_serwis_billing_settings(p_org_id uuid)
 RETURNS org_serwis_billing_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'ISSUE_PROTOCOL_ORG_REQUIRED';
  END IF;
  IF NOT (
    public.is_serwis_dispatcher_or_owner(p_org_id)
    OR public.is_serwis_technician_role(p_org_id)
  ) THEN
    RAISE EXCEPTION 'ISSUE_BILLING_FORBIDDEN';
  END IF;

  RETURN public.ensure_org_serwis_billing_settings(p_org_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.normalize_unit_number(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  SELECT NULLIF(
    regexp_replace(
      regexp_replace(
        lower(trim(coalesce(p_value, ''))),
        '^(m|lok|lokal|mieszkanie)[.\s]*',
        '',
        'i'
      ),
      '\s+',
      '',
      'g'
    ),
    ''
  );
$function$;
CREATE OR REPLACE FUNCTION public.org_effective_user_limit(p_org_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer;
BEGIN
  IF p_org_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = '42501';
  END IF;

  IF NOT (public.is_platform_admin() OR public.is_org_member(p_org_id)) THEN
    RAISE EXCEPTION 'Brak uprawnień do podglądu limitu użytkowników'
      USING ERRCODE = '42501';
  END IF;

  SELECT MIN(pp.max_users + COALESCE(os.extra_users, 0))
    INTO v_limit
  FROM public.org_subscriptions os
  JOIN public.pricing_plans pp ON pp.id = os.plan_id
  WHERE os.org_id = p_org_id
    AND lower(trim(COALESCE(os.status, ''))) = 'active'
    AND (os.expires_at IS NULL OR os.expires_at > now())
    AND pp.max_users IS NOT NULL;

  RETURN v_limit;
END;
$function$;
CREATE OR REPLACE FUNCTION public.org_has_current_module_subscription(p_org_id uuid, p_module text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.org_subscriptions s
    INNER JOIN public.applications a ON a.id = s.app_id
    WHERE s.org_id = p_org_id
      AND lower(COALESCE(s.status, '')) = 'active'
      AND (s.expires_at IS NULL OR s.expires_at > now())
      AND (
        (
          p_module = 'maintenance'
          AND (
            a.domain_url ILIKE '%serwis.domio.com.pl%'
            OR lower(a.name) LIKE '%serwis%'
          )
        )
        OR (
          p_module = 'cleaning'
          AND (
            a.domain_url ILIKE '%cleaning.domio.com.pl%'
            OR lower(a.name) LIKE '%cleaning%'
          )
        )
        OR (
          p_module = 'admin'
          AND (
            a.domain_url ILIKE '%admin.domio.com.pl%'
            OR a.domain_url ILIKE '%adm.domio.com.pl%'
            OR lower(a.name) LIKE '%administr%'
          )
        )
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.list_provider_directory(p_acting_org_id uuid, p_module text)
 RETURNS TABLE(org_id uuid, org_name text, city text, nip text, legal_entity_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_acting_org_id IS NULL OR NOT public.is_org_management(p_acting_org_id) THEN
    RAISE EXCEPTION 'PROVIDER_DIRECTORY_FORBIDDEN';
  END IF;

  IF p_module IS NULL OR p_module NOT IN ('maintenance', 'cleaning') THEN
    RAISE EXCEPTION 'PROVIDER_DIRECTORY_MODULE_INVALID';
  END IF;

  IF NOT public.is_platform_admin()
     AND NOT public.org_has_current_module_subscription(p_acting_org_id, 'admin') THEN
    RAISE EXCEPTION 'PROVIDER_DIRECTORY_ADMIN_REQUIRED';
  END IF;

  RETURN QUERY
  SELECT
    o.id,
    o.name,
    o.city,
    le.nip_normalized,
    o.legal_entity_id
  FROM public.organizations o
  INNER JOIN public.legal_entities le ON le.id = o.legal_entity_id
  WHERE o.listed_in_provider_directory = true
    AND o.legal_entity_id IS NOT NULL
    AND o.id <> p_acting_org_id
    AND public.org_has_current_module_subscription(o.id, p_module)
  ORDER BY o.name;
END;
$function$;
CREATE OR REPLACE FUNCTION public.org_serves_issue_location(p_org_id uuid, p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_org_id IS NOT NULL
    AND p_location_id IS NOT NULL
    AND (
      EXISTS (
        SELECT 1
        FROM public.cleaning_locations loc
        WHERE loc.id = p_location_id
          AND loc.org_id = p_org_id
          AND COALESCE(loc.is_active_in_serwis, true) = true
      )
      OR EXISTS (
        SELECT 1
        FROM public.property_contracts pc
        INNER JOIN public.companies c ON c.id = pc.company_id
        INNER JOIN public.cleaning_locations loc ON loc.id = p_location_id
        WHERE c.org_id = p_org_id
          AND c.category = 'contractor'
          AND pc.start_date <= CURRENT_DATE
          AND (pc.end_date IS NULL OR pc.end_date >= CURRENT_DATE)
          AND (
            pc.location_id = p_location_id
            OR (
              pc.community_id IS NOT NULL
              AND loc.community_id IS NOT NULL
              AND pc.community_id = loc.community_id
            )
          )
      )
    );
$function$;
CREATE OR REPLACE FUNCTION public.actor_can_see_open_marketplace(p_is_broadcast boolean, p_scope issue_marketplace_scope, p_location_id uuid, p_claimed_by uuid, p_assigned uuid, p_status issue_status_enum)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_is_broadcast IS TRUE
    AND p_scope IS NOT NULL
    AND p_claimed_by IS NULL
    AND p_assigned IS NULL
    AND p_status = 'open'
    AND public.current_org_has_serwis_access()
    AND (
      p_scope = 'all'
      OR (
        p_scope = 'serving'
        AND public.org_serves_issue_location(
          (SELECT public.get_my_org_id_safe()),
          p_location_id
        )
      )
    );
$function$;
CREATE OR REPLACE FUNCTION public.claim_marketplace_property_issue(p_issue_id uuid, p_assigned_staff_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_issue public.property_issues%ROWTYPE;
  v_updated integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  v_org := public.get_my_org_id_safe();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  SELECT * INTO v_issue
  FROM public.property_issues
  WHERE id = p_issue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF v_issue.claimed_by_org_id IS NOT NULL
     AND v_issue.claimed_by_org_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'ISSUE_MARKETPLACE_ALREADY_CLAIMED';
  END IF;

  IF v_issue.assigned_staff_id IS NOT NULL
     AND v_issue.claimed_by_org_id IS DISTINCT FROM v_org
     AND v_issue.org_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'ISSUE_MARKETPLACE_ALREADY_CLAIMED';
  END IF;

  IF v_issue.claimed_by_org_id IS NULL THEN
    IF v_issue.org_id IS DISTINCT FROM v_org THEN
      IF NOT public.actor_can_see_open_marketplace(
        v_issue.is_public_broadcast,
        v_issue.marketplace_scope,
        v_issue.location_id,
        v_issue.claimed_by_org_id,
        v_issue.assigned_staff_id,
        v_issue.status
      ) THEN
        RAISE EXCEPTION 'ISSUE_MARKETPLACE_FORBIDDEN';
      END IF;
    ELSIF NOT public.current_org_has_serwis_access() THEN
      RAISE EXCEPTION 'ISSUE_MARKETPLACE_FORBIDDEN';
    END IF;
  ELSIF NOT (
    public.is_serwis_dispatcher_or_owner(v_org)
    OR public.is_management_role(v_org)
    OR (p_assigned_staff_id IS NOT DISTINCT FROM v_actor)
  ) THEN
    RAISE EXCEPTION 'ISSUE_MARKETPLACE_FORBIDDEN';
  END IF;

  IF p_assigned_staff_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.memberships m
       WHERE m.org_id = v_org
         AND m.user_id = p_assigned_staff_id
         AND COALESCE(m.is_active, true) = true
     ) THEN
    RAISE EXCEPTION 'ISSUE_MARKETPLACE_FORBIDDEN';
  END IF;

  UPDATE public.property_issues
  SET
    claimed_by_org_id = v_org,
    assigned_staff_id = COALESCE(p_assigned_staff_id, assigned_staff_id),
    is_public_broadcast = false,
    marketplace_scope = NULL,
    status = CASE WHEN status = 'open' THEN status ELSE 'open' END
  WHERE id = p_issue_id
    AND (claimed_by_org_id IS NULL OR claimed_by_org_id = v_org)
    AND (
      assigned_staff_id IS NULL
      OR assigned_staff_id IS NOT DISTINCT FROM COALESCE(p_assigned_staff_id, assigned_staff_id)
    );

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'ISSUE_MARKETPLACE_ALREADY_CLAIMED';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.pause_service_mandate(p_acting_org_id uuid, p_mandate_id uuid)
 RETURNS service_mandates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.pause_service_mandate(p_acting_org_id, p_mandate_id); END; $function$;
CREATE OR REPLACE FUNCTION public.pending_required_legal_documents()
 RETURNS TABLE(id uuid, document_type text, version text, active_from timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
DECLARE
  v_uid uuid := (SELECT auth.uid());
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY
  SELECT p.id, p.document_type, p.version, p.active_from
  FROM private.pending_required_legal_documents(v_uid) p;
END;
$function$;
CREATE OR REPLACE FUNCTION public.place_resident_order(p_catalog_item_id uuid, p_location_id uuid, p_quantity integer DEFAULT 1, p_contact_name text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_item public.resident_order_catalog_items%ROWTYPE;
  v_loc public.cleaning_locations%ROWTYPE;
  v_id uuid;
  v_qty integer := COALESCE(p_quantity, 1);
BEGIN
  v_actor := private.resident_order_require_actor();

  IF v_qty < 1 OR v_qty > 99 THEN
    RAISE EXCEPTION 'Nieprawidłowa ilość.';
  END IF;

  IF NOT public.has_active_location_access(p_location_id) THEN
    RAISE EXCEPTION 'Brak dostępu do tego budynku.';
  END IF;

  SELECT * INTO v_loc
  FROM public.cleaning_locations
  WHERE id = p_location_id;

  IF v_loc.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono budynku.';
  END IF;

  IF v_loc.community_id IS NULL THEN
    RAISE EXCEPTION 'Budynek nie jest przypisany do wspólnoty.';
  END IF;

  SELECT * INTO v_item
  FROM public.resident_order_catalog_items
  WHERE id = p_catalog_item_id
    AND is_active = true;

  IF v_item.id IS NULL THEN
    RAISE EXCEPTION 'Pozycja nie jest dostępna do zamówienia.';
  END IF;

  IF v_item.community_id IS DISTINCT FROM v_loc.community_id THEN
    RAISE EXCEPTION 'Pozycja nie należy do tej wspólnoty.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.resident_order_catalog_item_locations loc WHERE loc.item_id = v_item.id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.resident_order_catalog_item_locations loc
    WHERE loc.item_id = v_item.id
      AND loc.location_id = p_location_id
  ) THEN
    RAISE EXCEPTION 'Ta pozycja nie jest dostępna w tym budynku.';
  END IF;

  INSERT INTO public.resident_orders (
    org_id,
    community_id,
    location_id,
    unit_number,
    resident_user_id,
    catalog_item_id,
    item_name,
    item_price_amount,
    item_price_kind,
    quantity,
    contact_name,
    contact_phone,
    contact_email,
    notes,
    status
  )
  VALUES (
    v_loc.org_id,
    v_loc.community_id,
    p_location_id,
    (
      SELECT la.unit_number
      FROM public.location_access la
      WHERE la.location_id = p_location_id
        AND la.user_id = v_actor
        AND (la.expires_at IS NULL OR la.expires_at > now())
      ORDER BY la.created_at DESC NULLS LAST
      LIMIT 1
    ),
    v_actor,
    v_item.id,
    v_item.name,
    v_item.price_amount,
    v_item.price_kind,
    v_qty,
    NULLIF(btrim(p_contact_name), ''),
    NULLIF(btrim(p_contact_phone), ''),
    NULLIF(btrim(p_contact_email), ''),
    NULLIF(btrim(p_notes), ''),
    'pending'
  )
  RETURNING id INTO v_id;

  PERFORM private.resident_order_append_event(v_id, v_actor, 'created', '{}'::jsonb);
  RETURN v_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.platform_admin_create_legal_entity_without_gus(p_kind legal_entity_kind, p_nip text, p_regon text, p_krs text, p_short_name text, p_legal_name text, p_voivodeship text, p_county text, p_commune text, p_city text, p_postal_code text, p_street text, p_building_number text, p_apartment_number text, p_seat_full_address text, p_email text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.legal_entities%ROWTYPE;
  v_nip text;
BEGIN
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_PLATFORM_ADMIN_ONLY';
  END IF;

  v_nip := regexp_replace(COALESCE(p_nip, ''), '[^0-9]', '', 'g');

  INSERT INTO public.legal_entities (
    kind,
    status,
    nip,
    regon,
    krs,
    short_name,
    legal_name,
    voivodeship,
    county,
    commune,
    city,
    postal_code,
    street,
    building_number,
    apartment_number,
    seat_full_address,
    email,
    phone,
    created_without_gus,
    gus_fetched_at,
    verification_status,
    verification_resolved_at,
    verification_resolved_by,
    updated_by
  )
  VALUES (
    p_kind,
    'active',
    v_nip,
    p_regon,
    NULLIF(btrim(COALESCE(p_krs, '')), ''),
    btrim(p_short_name),
    btrim(p_legal_name),
    btrim(p_voivodeship),
    NULLIF(btrim(COALESCE(p_county, '')), ''),
    NULLIF(btrim(COALESCE(p_commune, '')), ''),
    btrim(p_city),
    public.normalize_pl_postal(p_postal_code),
    NULLIF(btrim(COALESCE(p_street, '')), ''),
    btrim(p_building_number),
    NULLIF(btrim(COALESCE(p_apartment_number, '')), ''),
    btrim(p_seat_full_address),
    btrim(p_email),
    btrim(p_phone),
    true,
    NULL,
    'manually_verified',
    now(),
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'status', 'created_without_gus',
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.preview_promo_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.promo_codes%ROWTYPE;
  v_code text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = '42501';
  END IF;

  v_code := upper(trim(COALESCE(p_code, '')));
  IF v_code = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EMPTY');
  END IF;

  SELECT * INTO v_row
  FROM public.promo_codes
  WHERE upper(code) = v_code
  LIMIT 1;

  IF NOT FOUND OR v_row.is_active IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID');
  END IF;

  IF v_row.valid_until IS NOT NULL AND v_row.valid_until < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EXPIRED');
  END IF;

  IF v_row.max_uses IS NOT NULL AND COALESCE(v_row.used_count, 0) >= v_row.max_uses THEN
    RETURN jsonb_build_object('ok', false, 'error', 'LIMIT');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'code', v_row.code,
    'discount_percent', v_row.discount_percent,
    'discount_amount', v_row.discount_amount
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.property_task_location_id(p_task_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT location_id FROM public.property_tasks WHERE id = p_task_id;
$function$;
CREATE OR REPLACE FUNCTION public.property_task_user_has_access(p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    EXISTS (
      SELECT 1
      FROM public.cleaning_locations cl
      INNER JOIN public.memberships m
        ON m.org_id = cl.org_id
       AND m.user_id = auth.uid()
       AND m.is_active = true
       AND lower(trim(m.role)) = 'owner'
      WHERE cl.id = p_location_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.location_access la
      WHERE la.location_id = p_location_id
        AND la.user_id = auth.uid()
        AND la.access_type = 'administration'
        AND (la.expires_at IS NULL OR la.expires_at > now())
    );
$function$;
CREATE OR REPLACE FUNCTION public.propose_succession(p_acting_org_id uuid, p_community_legal_entity_id uuid, p_location_master_id uuid, p_to_org_id uuid, p_to_legal_entity_id uuid, p_mode succession_mode DEFAULT 'share_read'::succession_mode, p_resource_scope succession_resource[] DEFAULT ARRAY['all'::succession_resource], p_notes text DEFAULT NULL::text)
 RETURNS succession_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.propose_succession(p_acting_org_id, p_community_legal_entity_id, p_location_master_id, p_to_org_id, p_to_legal_entity_id, p_mode, p_resource_scope, p_notes); END; $function$;
CREATE OR REPLACE FUNCTION public.queue_issue_email_dispatch(p_issue_id uuid, p_vendor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_issue public.property_issues%ROWTYPE;
  v_vendor_id uuid;
BEGIN
  SELECT * INTO v_issue FROM public.property_issues WHERE id = p_issue_id;
  IF v_issue.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zgłoszenia.';
  END IF;

  v_vendor_id := COALESCE(p_vendor_id, v_issue.delegated_vendor_id);
  IF v_vendor_id IS NULL THEN
    RAISE EXCEPTION 'ISSUE_TRANSFER_FIELDS_REQUIRED';
  END IF;

  RETURN private.vendor_email_queue_for_issue(p_issue_id, v_vendor_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.queue_resident_order_dispatch(p_order_id uuid, p_company_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_order public.resident_orders%ROWTYPE;
  v_company_id uuid;
  v_email text;
BEGIN
  v_actor := private.resident_order_require_actor();

  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  PERFORM private.resident_order_require_community_management(v_order.community_id);

  IF v_order.status NOT IN ('pending', 'dispatch_failed') THEN
    RAISE EXCEPTION 'Tego zamówienia nie można wysłać do kontrahenta.';
  END IF;

  v_company_id := COALESCE(
    p_company_id,
    v_order.fulfillment_company_id,
    (
      SELECT s.default_company_id
      FROM public.resident_order_settings s
      WHERE s.community_id = v_order.community_id
    )
  );

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Przypisz podmiot realizacji zamówień.';
  END IF;

  SELECT c.email INTO v_email FROM public.companies c WHERE c.id = v_company_id;
  IF v_email IS NULL OR btrim(v_email) = '' THEN
    RAISE EXCEPTION 'Wybrana firma nie ma adresu e-mail.';
  END IF;

  UPDATE public.resident_orders
  SET
    status = 'dispatch_queued',
    fulfillment_company_id = v_company_id,
    dispatch_error = NULL
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(
    p_order_id,
    v_actor,
    'dispatch_queued',
    jsonb_build_object('company_id', v_company_id)
  );

  RETURN public.get_resident_order_email_payload(p_order_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.redeem_promo_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.promo_codes%ROWTYPE;
  v_code text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = '42501';
  END IF;

  v_code := upper(trim(COALESCE(p_code, '')));
  IF v_code = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EMPTY');
  END IF;

  SELECT * INTO v_row
  FROM public.promo_codes
  WHERE upper(code) = v_code
  FOR UPDATE;

  IF NOT FOUND OR v_row.is_active IS NOT TRUE THEN
    RETURN jsonb_build_object('ok', false, 'error', 'INVALID');
  END IF;

  IF v_row.valid_until IS NOT NULL AND v_row.valid_until < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EXPIRED');
  END IF;

  IF v_row.max_uses IS NOT NULL AND COALESCE(v_row.used_count, 0) >= v_row.max_uses THEN
    RETURN jsonb_build_object('ok', false, 'error', 'LIMIT');
  END IF;

  UPDATE public.promo_codes
  SET used_count = COALESCE(used_count, 0) + 1
  WHERE id = v_row.id
    AND (max_uses IS NULL OR COALESCE(used_count, 0) < max_uses)
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'LIMIT');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'code', v_row.code,
    'discount_percent', v_row.discount_percent,
    'discount_amount', v_row.discount_amount
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.register_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_user_agent text DEFAULT NULL::text, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS push_subscriptions
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.push_subscriptions;
  v_user uuid := (SELECT auth.uid());
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;
  IF length(btrim(COALESCE(p_endpoint, ''))) = 0
     OR length(btrim(COALESCE(p_p256dh, ''))) = 0
     OR length(btrim(COALESCE(p_auth, ''))) = 0 THEN
    RAISE EXCEPTION 'PUSH_SUBSCRIPTION_INVALID';
  END IF;

  INSERT INTO public.push_subscriptions (
    user_id, org_id, endpoint, p256dh, auth, user_agent, last_seen_at
  ) VALUES (
    v_user, p_org_id, btrim(p_endpoint), btrim(p_p256dh), btrim(p_auth), p_user_agent, now()
  )
  ON CONFLICT (endpoint) DO UPDATE
  SET
    user_id = v_user,
    org_id = COALESCE(EXCLUDED.org_id, public.push_subscriptions.org_id),
    p256dh = EXCLUDED.p256dh,
    auth = EXCLUDED.auth,
    user_agent = EXCLUDED.user_agent,
    last_seen_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reject_cleaning_extra_job(p_job_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.cleaning_extra_jobs%ROWTYPE;
BEGIN
  SELECT * INTO job FROM public.cleaning_extra_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Extra job not found';
  END IF;
  IF NOT public.is_cleaning_org_manager(job.org_id) THEN
    RAISE EXCEPTION 'Only coordinators and owners can reject extra jobs';
  END IF;

  UPDATE public.cleaning_extra_jobs
  SET
    approval_status = 'rejected',
    rejection_reason = NULLIF(btrim(COALESCE(p_reason, '')), ''),
    employee_total = NULL,
    client_total = NULL,
    applied_employee_rate = NULL,
    applied_client_rate = NULL
  WHERE id = p_job_id;

  UPDATE public.cleaning_tasks
  SET total_cost = NULL, applied_hourly_rate = NULL,
      status = CASE WHEN status = 'in_progress' THEN 'cancelled' ELSE status END
  WHERE id = job.task_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reject_property_issue(p_issue_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF length(v_reason) < 3 THEN
    RAISE EXCEPTION 'ISSUE_CANCEL_REASON_REQUIRED';
  END IF;
  UPDATE public.property_issues
  SET status = 'rejected', resolution_notes = v_reason
  WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reject_succession(p_acting_org_id uuid, p_succession_id uuid)
 RETURNS succession_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.reject_succession(p_acting_org_id, p_succession_id); END; $function$;
CREATE OR REPLACE FUNCTION public.release_cleaning_property_issue(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_issue public.property_issues%ROWTYPE;
  v_skip boolean := false;
  v_next public.issue_status_enum;
  v_updated integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  SELECT * INTO v_issue
  FROM public.property_issues
  WHERE id = p_issue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF NOT public.issue_is_in_cleaning_queue(
    v_issue.source,
    v_issue.released_from_cleaning_at,
    v_issue.reporter_type
  ) THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RELEASE_FORBIDDEN';
  END IF;

  IF NOT (
    public.is_management_role(v_issue.org_id)
    OR (
      v_issue.reporter_id IS NOT DISTINCT FROM v_actor
      AND EXISTS (
        SELECT 1
        FROM public.cleaning_locations loc
        WHERE loc.id = v_issue.location_id
          AND loc.auto_notify_issues IS TRUE
      )
    )
  ) THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RELEASE_FORBIDDEN';
  END IF;

  SELECT COALESCE(loc.skip_cleaning_issue_approval, false)
  INTO v_skip
  FROM public.cleaning_locations loc
  WHERE loc.id = v_issue.location_id;

  IF COALESCE(v_skip, false) THEN
    v_next := 'open'::public.issue_status_enum;
  ELSE
    v_next := 'pending_admin_approval'::public.issue_status_enum;
  END IF;

  UPDATE public.property_issues
  SET
    released_from_cleaning_at = now(),
    notification_status = 'sent',
    status = v_next
  WHERE id = p_issue_id
    AND released_from_cleaning_at IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RELEASE_FORBIDDEN';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.replace_inspection_campaign_days(p_campaign_id uuid, p_days jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_row jsonb;
  v_kind text;
BEGIN
  SELECT org_id INTO v_org
  FROM public.inspection_campaigns
  WHERE id = p_campaign_id;

  IF v_org IS NULL OR NOT public.is_serwis_dispatcher_or_owner(v_org) THEN
    RAISE EXCEPTION 'Brak uprawnień do edycji harmonogramu.' USING ERRCODE = '42501';
  END IF;

  IF p_days IS NULL OR jsonb_typeof(p_days) <> 'array' OR jsonb_array_length(p_days) < 1 THEN
    RAISE EXCEPTION 'Podaj co najmniej jeden dzień przeglądu.';
  END IF;

  DELETE FROM public.inspection_campaign_days
  WHERE campaign_id = p_campaign_id;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_days)
  LOOP
    v_kind := COALESCE(v_row ->> 'kind', 'primary');
    IF v_kind NOT IN ('primary', 'supplementary') THEN
      v_kind := 'primary';
    END IF;

    INSERT INTO public.inspection_campaign_days (
      campaign_id, visit_date, start_time, end_time, kind, notes
    ) VALUES (
      p_campaign_id,
      (v_row ->> 'visit_date')::date,
      (v_row ->> 'start_time')::time,
      (v_row ->> 'end_time')::time,
      v_kind::public.inspection_visit_kind,
      NULLIF(v_row ->> 'notes', '')
    );
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.request_property_issue_cancel(p_issue_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF length(v_reason) < 3 THEN
    RAISE EXCEPTION 'ISSUE_CANCEL_REASON_REQUIRED';
  END IF;
  UPDATE public.property_issues
  SET cancel_requested_at = now(), cancel_request_reason = v_reason
  WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.request_property_issue_transfer(p_issue_id uuid, p_vendor_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF p_vendor_id IS NULL OR length(v_reason) < 3 THEN
    RAISE EXCEPTION 'ISSUE_TRANSFER_FIELDS_REQUIRED';
  END IF;
  UPDATE public.property_issues
  SET is_transfer_requested = true,
      transfer_to_vendor_id = p_vendor_id,
      transfer_reason = v_reason,
      transfer_authorized_at = NULL,
      transfer_authorized_by = NULL
  WHERE id = p_issue_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resident_belongs_to_community(p_community_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.cleaning_locations cl
    INNER JOIN public.location_access la ON la.location_id = cl.id
    WHERE cl.community_id = p_community_id
      AND la.user_id = (SELECT auth.uid())
      AND (la.expires_at IS NULL OR la.expires_at > now())
  );
$function$;
CREATE OR REPLACE FUNCTION public.resident_can_see_catalog_item(p_item_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.resident_order_catalog_items i
    JOIN public.cleaning_locations cl ON cl.community_id = i.community_id
    JOIN public.location_access la ON la.location_id = cl.id
    WHERE i.id = p_item_id
      AND i.is_active = true
      AND la.user_id = (SELECT auth.uid())
      AND (la.expires_at IS NULL OR la.expires_at > now())
      AND (
        NOT EXISTS (
          SELECT 1
          FROM public.resident_order_catalog_item_locations loc
          WHERE loc.item_id = i.id
        )
        OR EXISTS (
          SELECT 1
          FROM public.resident_order_catalog_item_locations loc
          WHERE loc.item_id = i.id
            AND loc.location_id = la.location_id
        )
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.resident_matches_inspection_campaign(p_campaign_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.unit_inspection_records r
    JOIN public.inspection_campaigns c ON c.id = r.campaign_id
    JOIN public.location_access la
      ON la.location_id = c.location_id
     AND la.user_id = auth.uid()
    WHERE r.campaign_id = p_campaign_id
      AND (la.expires_at IS NULL OR la.expires_at > now())
      AND public.normalize_unit_number(la.unit_number)
          IS NOT DISTINCT FROM public.normalize_unit_number(r.unit_number)
      AND public.normalize_unit_number(r.unit_number) IS NOT NULL
  );
$function$;
CREATE OR REPLACE FUNCTION public.resident_matches_unit_inspection_record(p_record_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.unit_inspection_records r
    JOIN public.inspection_campaigns c ON c.id = r.campaign_id
    JOIN public.location_access la
      ON la.location_id = c.location_id
     AND la.user_id = auth.uid()
    WHERE r.id = p_record_id
      AND (la.expires_at IS NULL OR la.expires_at > now())
      AND public.normalize_unit_number(la.unit_number)
          IS NOT DISTINCT FROM public.normalize_unit_number(r.unit_number)
      AND public.normalize_unit_number(r.unit_number) IS NOT NULL
  );
$function$;
CREATE OR REPLACE FUNCTION public.guard_unit_inspection_record_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  SELECT c.org_id INTO v_org
  FROM public.inspection_campaigns c
  WHERE c.id = OLD.campaign_id;

  IF v_org IS NOT NULL AND public.is_serwis_dispatcher_or_owner(v_org) THEN
    RETURN NEW;
  END IF;

  IF public.resident_matches_unit_inspection_record(OLD.id)
     AND NEW.campaign_id IS NOT DISTINCT FROM OLD.campaign_id
     AND NEW.unit_number IS NOT DISTINCT FROM OLD.unit_number
     AND NEW.building_identifier IS NOT DISTINCT FROM OLD.building_identifier
     AND NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.notes IS NOT DISTINCT FROM OLD.notes
     AND NEW.inspection_date IS NOT DISTINCT FROM OLD.inspection_date
     AND NEW.photo_url IS NOT DISTINCT FROM OLD.photo_url
     AND NEW.signature_url IS NOT DISTINCT FROM OLD.signature_url
  THEN
    NEW.resident_home_by := auth.uid();
    NEW.resident_home_at := CASE
      WHEN NEW.resident_is_home THEN now()
      ELSE NULL
    END;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF public.is_inspection_campaign_assignee(OLD.campaign_id) THEN
    NEW.campaign_id := OLD.campaign_id;
    NEW.unit_number := OLD.unit_number;
    NEW.building_identifier := OLD.building_identifier;
    NEW.resident_is_home := OLD.resident_is_home;
    NEW.resident_home_at := OLD.resident_home_at;
    NEW.resident_home_by := OLD.resident_home_by;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Brak uprawnień do aktualizacji rekordu przeglądu.'
    USING ERRCODE = '42501';
END;
$function$;
CREATE OR REPLACE FUNCTION public.list_my_unit_inspections()
 RETURNS TABLE(campaign_id uuid, record_id uuid, title text, location_id uuid, unit_number text, status unit_inspection_status, resident_is_home boolean, start_date date, end_date date, days jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    c.id,
    r.id,
    c.title,
    c.location_id,
    r.unit_number,
    r.status,
    r.resident_is_home,
    c.start_date,
    c.end_date,
    COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'visit_date', d.visit_date,
            'start_time', d.start_time,
            'end_time', d.end_time,
            'kind', d.kind
          )
          ORDER BY d.visit_date
        )
        FROM public.inspection_campaign_days d
        WHERE d.campaign_id = c.id
      ),
      '[]'::jsonb
    )
  FROM public.unit_inspection_records r
  JOIN public.inspection_campaigns c ON c.id = r.campaign_id
  WHERE public.resident_matches_unit_inspection_record(r.id)
    AND CURRENT_DATE BETWEEN c.start_date AND c.end_date;
$function$;
CREATE OR REPLACE FUNCTION public.mark_unit_inspection_home(p_record_id uuid, p_is_home boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie.' USING ERRCODE = '42501';
  END IF;

  IF NOT public.resident_matches_unit_inspection_record(p_record_id) THEN
    RAISE EXCEPTION 'Brak dostępu do tego lokalu.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.unit_inspection_records
  SET resident_is_home = p_is_home,
      resident_home_at = CASE WHEN p_is_home THEN now() ELSE NULL END,
      resident_home_by = auth.uid(),
      updated_at = now()
  WHERE id = p_record_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_cleaning_released_property_issue(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_issue public.property_issues%ROWTYPE;
  v_updated integer;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  SELECT * INTO v_issue
  FROM public.property_issues
  WHERE id = p_issue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF NOT public.is_management_role(v_issue.org_id) THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;

  IF lower(btrim(COALESCE(v_issue.source::text, ''))) NOT IN ('cleaning', 'cleaning_app') THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;

  IF v_issue.released_from_cleaning_at IS NULL THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;

  IF v_issue.status IS DISTINCT FROM 'pending_admin_approval'::public.issue_status_enum
     AND v_issue.status IS DISTINCT FROM 'open'::public.issue_status_enum
     AND v_issue.status IS DISTINCT FROM 'new'::public.issue_status_enum THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;

  IF v_issue.assigned_staff_id IS NOT NULL
     OR v_issue.delegated_vendor_id IS NOT NULL
     OR v_issue.claimed_by_org_id IS NOT NULL
     OR v_issue.is_public_broadcast IS TRUE THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;

  UPDATE public.property_issues
  SET
    status = 'resolved',
    resolved_at = COALESCE(resolved_at, now())
  WHERE id = p_issue_id
    AND released_from_cleaning_at IS NOT NULL
    AND assigned_staff_id IS NULL
    AND delegated_vendor_id IS NULL
    AND claimed_by_org_id IS NULL
    AND COALESCE(is_public_broadcast, false) IS NOT TRUE
    AND status IN (
      'pending_admin_approval'::public.issue_status_enum,
      'open'::public.issue_status_enum,
      'new'::public.issue_status_enum
    );

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated = 0 THEN
    RAISE EXCEPTION 'ISSUE_CLEANING_RESOLVE_FORBIDDEN';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_cleaning_scope_document(p_admin_location_id uuid)
 RETURNS TABLE(contract_id uuid, contract_number text, contract_type text, company_name text, document_url text, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_loc public.cleaning_locations;
BEGIN
  PERFORM private.cleaning_scope_require_actor();
  v_loc := private.assert_can_access_admin_location(p_admin_location_id);

  RETURN QUERY
  SELECT *
  FROM private.resolve_scope_document(v_loc);
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_emergency_vendor(p_community_id uuid, p_location_id uuid, p_trade_category text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_vendor uuid;
  v_trade text := btrim(COALESCE(p_trade_category, ''));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;
  IF p_community_id IS NULL OR length(v_trade) = 0 THEN RAISE EXCEPTION 'EMERGENCY_VENDOR_ARGS'; END IF;

  SELECT c.org_id INTO v_org FROM public.communities c WHERE c.id = p_community_id;
  IF v_org IS NULL OR NOT public.can_manage_serwis_duty(v_org) THEN
    RAISE EXCEPTION 'EMERGENCY_MANAGE_FORBIDDEN';
  END IF;

  IF p_location_id IS NOT NULL THEN
    SELECT cep.vendor_partner_id INTO v_vendor
    FROM public.community_emergency_providers cep
    JOIN public.vendor_partners vp ON vp.id = cep.vendor_partner_id
    WHERE cep.community_id = p_community_id
      AND cep.location_id = p_location_id
      AND cep.trade_category = v_trade
      AND vp.is_emergency_24h = true
    LIMIT 1;
    IF v_vendor IS NOT NULL THEN RETURN v_vendor; END IF;
  END IF;

  SELECT cep.vendor_partner_id INTO v_vendor
  FROM public.community_emergency_providers cep
  JOIN public.vendor_partners vp ON vp.id = cep.vendor_partner_id
  WHERE cep.community_id = p_community_id
    AND cep.location_id IS NULL
    AND cep.trade_category = v_trade
    AND vp.is_emergency_24h = true
  LIMIT 1;

  IF v_vendor IS NULL THEN RAISE EXCEPTION 'EMERGENCY_VENDOR_MISSING'; END IF;
  RETURN v_vendor;
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_emergency_issue(p_location_id uuid, p_category text, p_description text, p_photos_before text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_community uuid;
  v_vendor uuid;
  v_issue uuid;
  v_desc text := btrim(COALESCE(p_description, ''));
  v_cat text := btrim(COALESCE(p_category, ''));
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;
  IF p_location_id IS NULL OR length(v_cat) = 0 OR length(v_desc) < 10 THEN
    RAISE EXCEPTION 'EMERGENCY_ISSUE_INVALID';
  END IF;

  v_org := public.get_my_org_id_safe();
  IF v_org IS NULL OR NOT public.can_manage_serwis_duty(v_org) THEN
    RAISE EXCEPTION 'EMERGENCY_MANAGE_FORBIDDEN';
  END IF;

  SELECT cl.community_id INTO v_community
  FROM public.cleaning_locations cl
  WHERE cl.id = p_location_id AND cl.org_id = v_org;

  IF v_community IS NULL THEN RAISE EXCEPTION 'EMERGENCY_LOCATION_FORBIDDEN'; END IF;

  v_vendor := public.resolve_emergency_vendor(v_community, p_location_id, v_cat);

  INSERT INTO public.property_issues (
    org_id, location_id, category, description, priority, status, source,
    reporter_type, reporter_id, photos_before,
    immediate_fulfillment, emergency_mode, emergency_vendor_id, delegated_vendor_id
  ) VALUES (
    v_org, p_location_id, v_cat, v_desc, 'critical', 'delegated', 'admin_ui',
    'admin', (SELECT auth.uid()), p_photos_before, true, true, v_vendor, v_vendor
  )
  RETURNING id INTO v_issue;

  RETURN jsonb_build_object('issue_id', v_issue, 'vendor_id', v_vendor);
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_inbound_mailbox(p_to_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_alias text := private.inbound_normalize_alias(p_to_address);
  v_box public.org_inbound_mailboxes%ROWTYPE;
  v_limit integer;
  v_used integer;
  v_month date := private.inbound_month_start();
  v_looks boolean;
  v_enabled boolean;
  v_reject text;
BEGIN
  v_looks := private.inbound_looks_like_org_alias(v_alias);

  IF v_alias IS NULL THEN
    RETURN jsonb_build_object(
      'found', false,
      'looks_like_org_alias', false,
      'reject_reason', 'unrecognized_recipient'
    );
  END IF;

  SELECT * INTO v_box
  FROM public.org_inbound_mailboxes
  WHERE alias_local_part = v_alias
  LIMIT 1;

  IF v_box.id IS NULL THEN
    RETURN jsonb_build_object(
      'found', false,
      'alias_local_part', v_alias,
      'looks_like_org_alias', v_looks,
      'reject_reason', CASE WHEN v_looks THEN 'unknown_alias' ELSE 'unrecognized_recipient' END
    );
  END IF;

  IF v_box.module = 'cleaning' THEN
    v_enabled := false;
    v_reject := 'cleaning_app_only';
  ELSIF v_box.is_enabled THEN
    v_enabled := true;
    v_reject := NULL;
  ELSE
    v_enabled := false;
    v_reject := 'mailbox_disabled';
  END IF;

  v_limit := private.inbound_ai_monthly_limit(v_box.org_id);

  SELECT COALESCE(u.parse_count, 0)
    INTO v_used
  FROM public.org_ai_usage_monthly u
  WHERE u.org_id = v_box.org_id
    AND u.year_month = v_month;

  v_used := COALESCE(v_used, 0);

  RETURN jsonb_build_object(
    'found', true,
    'mailbox_id', v_box.id,
    'org_id', v_box.org_id,
    'module', v_box.module,
    'alias_local_part', v_box.alias_local_part,
    'ingest_mode', v_box.ingest_mode,
    'is_enabled', v_enabled,
    'auto_create_threshold', v_box.auto_create_threshold,
    'has_ai_auto', private.inbound_has_ai_auto(v_box.org_id),
    'ai_parses_limit', v_limit,
    'ai_parses_used', v_used,
    'ai_parses_remaining', GREATEST(v_limit - v_used, 0),
    'allow_ai_parse', (v_enabled AND GREATEST(v_limit - v_used, 0) > 0),
    'looks_like_org_alias', v_looks,
    'reject_reason', v_reject
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_legal_entity_verification(p_legal_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.legal_entities%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_VERIFY_PLATFORM_ONLY';
  END IF;

  SELECT * INTO v_row
  FROM public.legal_entities
  WHERE id = p_legal_entity_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_NOT_FOUND';
  END IF;

  IF v_row.verification_status <> 'pending_manual'::public.legal_entity_verification_status THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_ALREADY_VERIFIED';
  END IF;

  PERFORM public.legal_entity_mark_rpc_writer();

  UPDATE public.legal_entities
  SET
    verification_status = 'manually_verified',
    verification_resolved_at = now(),
    verification_resolved_by = auth.uid()
  WHERE id = p_legal_entity_id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'status', 'manually_verified',
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_orgs_for_legal_entity(p_legal_entity_id uuid)
 RETURNS TABLE(org_id uuid, org_name text, is_admin boolean, is_cleaning boolean, is_maintenance boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'MANDATE_AUTH_REQUIRED';
  END IF;

  IF p_legal_entity_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.legal_entities le WHERE le.id = p_legal_entity_id) THEN
    RAISE EXCEPTION 'MANDATE_PARTNER_NOT_FOUND';
  END IF;

  RETURN QUERY
  SELECT
    e.org_id,
    COALESCE(o.name, e.org_id::text) AS org_name,
    e.is_admin,
    e.is_cleaning,
    e.is_maintenance
  FROM public.org_legal_entity_enrollments e
  LEFT JOIN public.organizations o ON o.id = e.org_id
  WHERE e.legal_entity_id = p_legal_entity_id
    AND e.status = 'active'
  ORDER BY o.name NULLS LAST;
END;
$function$;
CREATE OR REPLACE FUNCTION public.respond_equipment_protocol(p_protocol_id uuid, p_accept boolean, p_condition_notes text DEFAULT NULL::text, p_photo_urls text[] DEFAULT NULL::text[], p_rejection_reason text DEFAULT NULL::text)
 RETURNS equipment_protocols
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
  SELECT * FROM private.respond_equipment_protocol(
    p_protocol_id, p_accept, p_condition_notes, p_photo_urls, p_rejection_reason
  );
$function$;
CREATE OR REPLACE FUNCTION public.respond_estate_invite(p_member_id uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := private.estate_require_actor();
  v_row public.estate_members%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.estate_members
  WHERE id = p_member_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zaproszenia.';
  END IF;

  PERFORM private.estate_require_community_management(v_row.community_id);

  IF v_row.status <> 'invited' THEN
    RAISE EXCEPTION 'To zaproszenie nie oczekuje na decyzję.';
  END IF;

  IF p_accept THEN
    UPDATE public.estate_members
    SET status = 'accepted',
        consented_at = now(),
        consented_by = v_actor
    WHERE id = p_member_id;
  ELSE
    UPDATE public.estate_members
    SET status = 'rejected',
        consented_at = now(),
        consented_by = v_actor
    WHERE id = p_member_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.resume_service_mandate(p_acting_org_id uuid, p_mandate_id uuid)
 RETURNS service_mandates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.resume_service_mandate(p_acting_org_id, p_mandate_id); END; $function$;
CREATE OR REPLACE FUNCTION public.retire_equipment_asset(p_asset_id uuid)
 RETURNS equipment_assets
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
  SELECT * FROM private.retire_equipment_asset(p_asset_id);
$function$;
CREATE OR REPLACE FUNCTION public.revoke_service_mandate(p_acting_org_id uuid, p_mandate_id uuid)
 RETURNS service_mandates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.revoke_service_mandate(p_acting_org_id, p_mandate_id); END; $function$;
CREATE OR REPLACE FUNCTION public.save_resident_order_settings(p_community_id uuid, p_default_company_id uuid, p_email_subject_template text, p_email_body_template text)
 RETURNS resident_order_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_row public.resident_order_settings;
BEGIN
  v_org := private.resident_order_require_community_management(p_community_id);

  IF p_default_company_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.companies c WHERE c.id = p_default_company_id
  ) THEN
    RAISE EXCEPTION 'Nie znaleziono firmy.';
  END IF;

  INSERT INTO public.resident_order_settings (
    community_id,
    org_id,
    default_company_id,
    email_subject_template,
    email_body_template,
    updated_by
  )
  VALUES (
    p_community_id,
    v_org,
    p_default_company_id,
    btrim(p_email_subject_template),
    btrim(p_email_body_template),
    (SELECT auth.uid())
  )
  ON CONFLICT (community_id) DO UPDATE
  SET
    default_company_id = EXCLUDED.default_company_id,
    email_subject_template = EXCLUDED.email_subject_template,
    email_body_template = EXCLUDED.email_body_template,
    updated_by = EXCLUDED.updated_by;

  SELECT * INTO v_row
  FROM public.resident_order_settings
  WHERE community_id = p_community_id;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.search_communities_for_estate_invite(p_query text, p_estate_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(community_id uuid, display_name text, nip text, is_own boolean, link_status estate_member_status)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_q text := btrim(COALESCE(p_query, ''));
  v_nip text;
BEGIN
  PERFORM private.estate_require_actor();

  SELECT public.get_my_org_id_safe() INTO v_org;
  IF v_org IS NULL OR NOT public.is_org_management(v_org) THEN
    RAISE EXCEPTION 'Brak uprawnień do wyszukiwania wspólnot.';
  END IF;

  IF length(v_q) < 3 THEN
    RAISE EXCEPTION 'Wpisz co najmniej 3 znaki (NIP lub nazwa).';
  END IF;

  v_nip := regexp_replace(v_q, '[^0-9]', '', 'g');

  RETURN QUERY
  SELECT
    c.id,
    COALESCE(NULLIF(btrim(c.legal_name), ''), NULLIF(btrim(c.name), ''), 'Wspólnota') AS display_name,
    c.nip,
    (c.org_id = v_org) AS is_own,
    (
      SELECT em.status
      FROM public.estate_members em
      WHERE em.community_id = c.id
        AND (p_estate_id IS NULL OR em.estate_id = p_estate_id)
        AND em.status IN ('invited', 'accepted')
      ORDER BY CASE WHEN p_estate_id IS NOT NULL AND em.estate_id = p_estate_id THEN 0 ELSE 1 END
      LIMIT 1
    ) AS link_status
  FROM public.communities c
  WHERE (c.status IS NULL OR c.status = 'active')
    AND (
      (length(v_nip) >= 6 AND regexp_replace(COALESCE(c.nip, ''), '[^0-9]', '', 'g') = v_nip)
      OR (
        length(v_nip) < 6
        AND (
          c.name ILIKE '%' || v_q || '%'
          OR c.legal_name ILIKE '%' || v_q || '%'
        )
      )
    )
  ORDER BY (c.org_id = v_org) DESC, display_name
  LIMIT 10;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_building_cleaning_scope_contract(p_admin_location_id uuid, p_contract_id uuid)
 RETURNS TABLE(contract_id uuid, contract_number text, contract_type text, company_name text, document_url text, source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_loc public.cleaning_locations;
BEGIN
  PERFORM private.cleaning_scope_require_actor();
  v_loc := private.assert_can_access_admin_location(p_admin_location_id);

  IF NOT private.user_can_set_cleaning_scope_contract(v_loc.org_id) THEN
    RAISE EXCEPTION 'CLEANING_SCOPE_FORBIDDEN';
  END IF;

  IF p_contract_id IS NOT NULL
     AND NOT private.contract_eligible_for_cleaning_scope(
       p_contract_id,
       v_loc.org_id,
       v_loc.id,
       v_loc.community_id
     )
  THEN
    RAISE EXCEPTION 'CLEANING_SCOPE_CONTRACT_INVALID';
  END IF;

  UPDATE public.cleaning_locations
  SET cleaning_scope_contract_id = p_contract_id
  WHERE id = v_loc.id
  RETURNING * INTO v_loc;

  RETURN QUERY
  SELECT *
  FROM private.resolve_scope_document(v_loc);
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_dispatcher_forced_next(p_issue_id uuid, p_forced boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_staff uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  SELECT org_id, assigned_staff_id
  INTO v_org, v_staff
  FROM public.property_issues
  WHERE id = p_issue_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF v_org IS NULL OR NOT public.is_management_role(v_org) THEN
    RAISE EXCEPTION 'ISSUE_FORCED_NEXT_FORBIDDEN';
  END IF;

  IF p_forced THEN
    IF v_staff IS NULL THEN
      RAISE EXCEPTION 'ISSUE_FORCED_NEXT_NEEDS_ASSIGNEE';
    END IF;

    UPDATE public.property_issues
    SET dispatcher_forced_next = false, dispatcher_forced_at = NULL, dispatcher_forced_by = NULL
    WHERE org_id = v_org
      AND assigned_staff_id = v_staff
      AND dispatcher_forced_next = true
      AND id IS DISTINCT FROM p_issue_id;

    UPDATE public.property_issues
    SET dispatcher_forced_next = true, dispatcher_forced_at = now(), dispatcher_forced_by = auth.uid()
    WHERE id = p_issue_id;
  ELSE
    UPDATE public.property_issues
    SET dispatcher_forced_next = false, dispatcher_forced_at = NULL, dispatcher_forced_by = NULL
    WHERE id = p_issue_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_equipment_protocol_evidence(p_protocol_id uuid, p_condition_notes text DEFAULT NULL::text, p_photo_urls text[] DEFAULT NULL::text[])
 RETURNS equipment_protocols
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
  SELECT * FROM private.set_equipment_protocol_evidence(p_protocol_id, p_condition_notes, p_photo_urls);
$function$;
CREATE OR REPLACE FUNCTION public.set_inspection_campaign_assignees(p_campaign_id uuid, p_technician_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_id uuid;
BEGIN
  SELECT org_id INTO v_org
  FROM public.inspection_campaigns
  WHERE id = p_campaign_id;

  IF v_org IS NULL OR NOT public.is_serwis_dispatcher_or_owner(v_org) THEN
    RAISE EXCEPTION 'Brak uprawnień do przydziału techników.' USING ERRCODE = '42501';
  END IF;

  IF p_technician_ids IS NOT NULL THEN
    FOREACH v_id IN ARRAY p_technician_ids
    LOOP
      IF NOT EXISTS (
        SELECT 1
        FROM public.memberships m
        WHERE m.org_id = v_org
          AND m.user_id = v_id
          AND COALESCE(m.is_active, true) = true
          AND m.role IN (
            'technik', 'technician',
            'coordinator', 'koordynator',
            'owner', 'wlasciciel',
            'admin', 'administrator', 'manager'
          )
      ) THEN
        RAISE EXCEPTION 'Technik nie należy do zespołu tej organizacji.';
      END IF;
    END LOOP;
  END IF;

  DELETE FROM public.inspection_campaign_assignees
  WHERE campaign_id = p_campaign_id;

  IF p_technician_ids IS NOT NULL THEN
    INSERT INTO public.inspection_campaign_assignees (campaign_id, technician_id, assigned_by)
    SELECT DISTINCT p_campaign_id, t_id, auth.uid()
    FROM unnest(p_technician_ids) AS t_id
    WHERE t_id IS NOT NULL;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_org_duty_eligible(p_org_id uuid, p_user_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ids uuid[] := COALESCE(p_user_ids, ARRAY[]::uuid[]);
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;
  IF p_org_id IS NULL THEN RAISE EXCEPTION 'DUTY_ORG_REQUIRED'; END IF;
  IF NOT public.can_manage_serwis_duty(p_org_id) THEN RAISE EXCEPTION 'DUTY_MANAGE_FORBIDDEN'; END IF;

  DELETE FROM public.org_duty_eligible
  WHERE org_id = p_org_id AND NOT (user_id = ANY (v_ids));

  INSERT INTO public.org_duty_eligible (org_id, user_id, added_by)
  SELECT p_org_id, u, (SELECT auth.uid())
  FROM unnest(v_ids) AS u
  ON CONFLICT (org_id, user_id) DO NOTHING;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_org_duty_state(p_org_id uuid, p_enabled boolean, p_active_user_id uuid DEFAULT NULL::uuid)
 RETURNS org_duty_state
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.org_duty_state;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED'; END IF;
  IF p_org_id IS NULL THEN RAISE EXCEPTION 'DUTY_ORG_REQUIRED'; END IF;
  IF NOT public.can_manage_serwis_duty(p_org_id) THEN RAISE EXCEPTION 'DUTY_MANAGE_FORBIDDEN'; END IF;

  INSERT INTO public.org_duty_state (org_id, is_duty_enabled, active_user_id, updated_by)
  VALUES (
    p_org_id,
    COALESCE(p_enabled, false),
    CASE WHEN COALESCE(p_enabled, false) THEN p_active_user_id ELSE NULL END,
    (SELECT auth.uid())
  )
  ON CONFLICT (org_id) DO UPDATE
  SET
    is_duty_enabled = EXCLUDED.is_duty_enabled,
    active_user_id = EXCLUDED.active_user_id,
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_org_listed_in_provider_directory(p_org_id uuid, p_listed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_le uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL OR NOT public.is_org_management(p_org_id) THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_ENROLL_FORBIDDEN';
  END IF;

  SELECT legal_entity_id INTO v_le
  FROM public.organizations
  WHERE id = p_org_id;

  IF COALESCE(p_listed, false) AND v_le IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PROVIDER_DIRECTORY_NIP_REQUIRED');
  END IF;

  UPDATE public.organizations
  SET listed_in_provider_directory = COALESCE(p_listed, false)
  WHERE id = p_org_id;

  RETURN jsonb_build_object(
    'ok', true,
    'listed', COALESCE(p_listed, false),
    'legalEntityId', v_le
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_org_subscription_extra_users(p_org_id uuid, p_app_id uuid, p_extra_users integer)
 RETURNS org_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_platform_admin boolean;
  v_existing public.org_subscriptions%ROWTYPE;
  v_plan public.pricing_plans%ROWTYPE;
  v_interval text;
  v_unit_price numeric;
  v_member_count integer;
  v_new_limit integer;
  v_row public.org_subscriptions%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = '42501';
  END IF;

  IF p_extra_users IS NULL OR p_extra_users < 0 THEN
    RAISE EXCEPTION 'Liczba dodatkowych użytkowników musi być liczbą całkowitą ≥ 0'
      USING ERRCODE = '22023';
  END IF;

  v_is_platform_admin := public.is_platform_admin();

  IF NOT (v_is_platform_admin OR public.is_org_billing_owner(p_org_id)) THEN
    RAISE EXCEPTION 'Tylko właściciel firmy może dokupić dodatkowych użytkowników'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
    INTO v_existing
  FROM public.org_subscriptions
  WHERE org_id = p_org_id
    AND app_id = p_app_id
  FOR UPDATE;

  IF NOT FOUND
     OR lower(trim(COALESCE(v_existing.status, ''))) <> 'active'
     OR (v_existing.expires_at IS NOT NULL AND v_existing.expires_at <= now()) THEN
    RAISE EXCEPTION 'Brak aktywnej subskrypcji tego modułu'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_existing.plan_id IS NULL THEN
    RAISE EXCEPTION 'Brak przypisanego planu — nie można dokupić użytkowników'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT *
    INTO v_plan
  FROM public.pricing_plans
  WHERE id = v_existing.plan_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Przypisany plan jest niedostępny'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_extra_users > 0 AND v_plan.max_users IS NULL THEN
    RAISE EXCEPTION 'Ten plan nie ma limitu użytkowników, dodatkowe miejsca nie są dostępne'
      USING ERRCODE = 'P0001';
  END IF;

  v_interval := lower(trim(COALESCE(v_existing.billing_interval, 'monthly')));
  IF v_interval = 'yearly' THEN
    v_unit_price := v_plan.extra_user_price_yearly;
  ELSE
    v_unit_price := v_plan.extra_user_price_monthly;
  END IF;

  IF p_extra_users > 0 AND NOT v_is_platform_admin AND v_unit_price IS NULL THEN
    IF v_interval = 'yearly' THEN
      RAISE EXCEPTION 'Plan nie ma ceny dodatkowego użytkownika w rozliczeniu rocznym'
        USING ERRCODE = 'P0001';
    END IF;
    RAISE EXCEPTION 'Plan nie ma ceny dodatkowego użytkownika w rozliczeniu miesięcznym'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.org_subscriptions
  SET extra_users = p_extra_users
  WHERE id = v_existing.id
  RETURNING * INTO v_row;

  SELECT MIN(pp.max_users + COALESCE(os.extra_users, 0))
    INTO v_new_limit
  FROM public.org_subscriptions os
  JOIN public.pricing_plans pp ON pp.id = os.plan_id
  WHERE os.org_id = p_org_id
    AND os.status = 'active'
    AND (os.expires_at IS NULL OR os.expires_at > now())
    AND pp.max_users IS NOT NULL;

  SELECT COUNT(*)::integer
    INTO v_member_count
  FROM public.memberships
  WHERE org_id = p_org_id;

  IF v_new_limit IS NOT NULL AND v_member_count > v_new_limit THEN
    RAISE EXCEPTION 'Nie można zmniejszyć liczby miejsc poniżej liczby użytkowników w organizacji (%)', v_member_count
      USING ERRCODE = 'P0001';
  END IF;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_resident_order_company(p_order_id uuid, p_company_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_order public.resident_orders%ROWTYPE;
BEGIN
  v_actor := private.resident_order_require_actor();

  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  PERFORM private.resident_order_require_community_management(v_order.community_id);

  IF p_company_id IS NULL THEN
    RAISE EXCEPTION 'Wybierz firmę.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.companies c WHERE c.id = p_company_id) THEN
    RAISE EXCEPTION 'Nie znaleziono firmy.';
  END IF;

  UPDATE public.resident_orders
  SET fulfillment_company_id = p_company_id
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(
    p_order_id,
    v_actor,
    'company_changed',
    jsonb_build_object(
      'from_company_id', v_order.fulfillment_company_id,
      'to_company_id', p_company_id
    )
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_resident_order_stock_delivery(p_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_order public.resident_orders%ROWTYPE;
BEGIN
  v_actor := private.resident_order_require_actor();

  SELECT * INTO v_order FROM public.resident_orders WHERE id = p_order_id FOR UPDATE;
  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zamówienia.';
  END IF;

  PERFORM private.resident_order_require_community_management(v_order.community_id);

  IF v_order.status NOT IN ('pending', 'dispatch_failed') THEN
    RAISE EXCEPTION 'Tego zamówienia nie można przekazać ze stanu.';
  END IF;

  UPDATE public.resident_orders
  SET status = 'stock_delivery'
  WHERE id = p_order_id;

  PERFORM private.resident_order_append_event(p_order_id, v_actor, 'stock_assigned', '{}'::jsonb);
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_row_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.set_vehicle_child_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT v.org_id INTO NEW.org_id
  FROM public.vehicles v
  WHERE v.id = NEW.vehicle_id;

  IF NEW.org_id IS NULL THEN
    RAISE EXCEPTION 'Vehicle does not exist';
