$function$;
CREATE OR REPLACE FUNCTION public.snapshot_extra_job_totals(p_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.cleaning_extra_jobs%ROWTYPE;
  emp_rate numeric;
  client_rate numeric;
  hours numeric;
  emp_total numeric;
  client_total numeric;
  loc_rate numeric;
  profile_rate numeric;
BEGIN
  SELECT * INTO job FROM public.cleaning_extra_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Extra job not found';
  END IF;
  IF job.approval_status IS DISTINCT FROM 'approved' THEN
    RETURN;
  END IF;
  IF job.duration_minutes IS NULL THEN
    RETURN;
  END IF;

  hours := LEAST(job.duration_minutes / 60.0, 16);

  SELECT COALESCE(extra_hourly_rate, 0) INTO profile_rate
  FROM public.profiles
  WHERE id = job.assigned_staff_id;

  SELECT COALESCE(extra_work_rate, 0) INTO loc_rate
  FROM public.cleaning_locations
  WHERE id = job.location_id;

  emp_rate := COALESCE(job.employee_hourly_rate, profile_rate, 0);
  client_rate := COALESCE(job.client_hourly_rate, loc_rate, 0);

  IF job.pay_mode = 'fixed' THEN
    emp_total := COALESCE(job.employee_fixed_amount, 0);
    client_total := COALESCE(job.client_fixed_amount, 0);
    emp_rate := NULL;
    client_rate := NULL;
  ELSE
    emp_total := ROUND((hours * emp_rate)::numeric, 2);
    client_total := ROUND((hours * client_rate)::numeric, 2);
  END IF;

  UPDATE public.cleaning_extra_jobs
  SET
    applied_employee_rate = emp_rate,
    applied_client_rate = client_rate,
    employee_total = emp_total,
    client_total = client_total
  WHERE id = p_job_id;

  UPDATE public.cleaning_tasks
  SET
    applied_hourly_rate = emp_rate,
    total_cost = emp_total
  WHERE id = job.task_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.approve_cleaning_extra_job(p_job_id uuid, p_pay_mode text DEFAULT NULL::text, p_employee_hourly_rate numeric DEFAULT NULL::numeric, p_client_hourly_rate numeric DEFAULT NULL::numeric, p_employee_fixed_amount numeric DEFAULT NULL::numeric, p_client_fixed_amount numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.cleaning_extra_jobs%ROWTYPE;
  v_pay_mode text;
BEGIN
  SELECT * INTO job FROM public.cleaning_extra_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Extra job not found';
  END IF;
  IF NOT public.is_cleaning_org_manager(job.org_id) THEN
    RAISE EXCEPTION 'Only coordinators and owners can approve extra jobs';
  END IF;

  v_pay_mode := COALESCE(p_pay_mode, job.pay_mode, 'hourly');
  IF v_pay_mode NOT IN ('hourly', 'fixed') THEN
    RAISE EXCEPTION 'Invalid pay mode';
  END IF;
  IF v_pay_mode = 'fixed' AND COALESCE(p_employee_fixed_amount, job.employee_fixed_amount) IS NULL THEN
    RAISE EXCEPTION 'Fixed extra jobs require an employee amount';
  END IF;

  UPDATE public.cleaning_extra_jobs
  SET
    pay_mode = v_pay_mode,
    employee_hourly_rate = COALESCE(p_employee_hourly_rate, employee_hourly_rate),
    client_hourly_rate = COALESCE(p_client_hourly_rate, client_hourly_rate),
    employee_fixed_amount = COALESCE(p_employee_fixed_amount, employee_fixed_amount),
    client_fixed_amount = COALESCE(p_client_fixed_amount, client_fixed_amount),
    approval_status = 'approved',
    approved_by = auth.uid(),
    approved_at = now(),
    rejection_reason = NULL
  WHERE id = p_job_id;

  PERFORM public.snapshot_extra_job_totals(p_job_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.complete_cleaning_extra_job(p_job_id uuid, p_work_report text, p_ended_at timestamp with time zone DEFAULT now())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.cleaning_extra_jobs%ROWTYPE;
  v_report text := btrim(COALESCE(p_work_report, ''));
  v_started timestamptz;
  v_minutes integer;
  v_photo_count integer;
BEGIN
  SELECT * INTO job FROM public.cleaning_extra_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Extra job not found';
  END IF;
  IF job.assigned_staff_id IS DISTINCT FROM auth.uid()
     AND NOT public.is_cleaning_org_manager(job.org_id) THEN
    RAISE EXCEPTION 'Not allowed to complete this extra job';
  END IF;
  IF job.approval_status = 'rejected' THEN
    RAISE EXCEPTION 'Rejected extra jobs cannot be completed';
  END IF;
  IF v_report = '' THEN
    RAISE EXCEPTION 'Work report is required';
  END IF;

  SELECT COUNT(*) INTO v_photo_count
  FROM public.cleaning_extra_job_photos
  WHERE extra_job_id = p_job_id;

  IF job.requires_photo AND v_photo_count < 1 THEN
    RAISE EXCEPTION 'At least one photo is required';
  END IF;

  SELECT started_at INTO v_started FROM public.cleaning_tasks WHERE id = job.task_id;
  IF v_started IS NULL THEN
    RAISE EXCEPTION 'Extra job has not been started';
  END IF;

  v_minutes := GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (COALESCE(p_ended_at, now()) - v_started)) / 60)::integer);

  UPDATE public.cleaning_extra_jobs
  SET work_report = v_report, duration_minutes = v_minutes
  WHERE id = p_job_id;

  UPDATE public.cleaning_tasks
  SET status = 'done', completed_at = COALESCE(p_ended_at, now()), actual_performer_id = COALESCE(job.assigned_staff_id, auth.uid())
  WHERE id = job.task_id;

  UPDATE public.cleaning_work_sessions
  SET status = 'closed', close_reason = 'manual', ended_at = COALESCE(p_ended_at, now())
  WHERE task_id = job.task_id AND status = 'open' AND session_kind = 'extra_paid';

  PERFORM public.snapshot_extra_job_totals(p_job_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.start_employee_extra_job(p_org_id uuid, p_location_id uuid, p_title text DEFAULT 'Praca ekstra'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_task_id uuid;
  v_job_id uuid;
  v_title text := btrim(COALESCE(NULLIF(p_title, ''), 'Praca ekstra'));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.is_org_member(p_org_id) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  INSERT INTO public.cleaning_tasks (
    org_id, location_id, assigned_staff_id, status, task_type, scheduled_at, started_at, coordinator_notes, section_id
  )
  VALUES (
    p_org_id, p_location_id, auth.uid(), 'in_progress', 'extra_paid', now(), now(), v_title, NULL
  )
  RETURNING id INTO v_task_id;

  INSERT INTO public.cleaning_extra_jobs (
    org_id, task_id, location_id, assigned_staff_id, created_by, origin, title, approval_status, pay_mode, gps_required
  )
  VALUES (
    p_org_id, v_task_id, p_location_id, auth.uid(), auth.uid(), 'employee', v_title, 'pending_review', 'hourly', true
  )
  RETURNING id INTO v_job_id;

  RETURN v_job_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.start_task_with_validation(p_task_id uuid, p_user_lat double precision, p_user_lon double precision, p_scanned_qr text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_task RECORD;
    v_distance FLOAT;
    v_user_geo geography; -- Usunięto prefiks extensions.
BEGIN
    -- 1. Pobierz dane zadania i powiązanej lokalizacji
    SELECT t.*, l.geo_location, l.geofence_radius_meters, l.qr_code_token, l.validation_config
    INTO v_task
    FROM public.cleaning_tasks t
    JOIN public.cleaning_locations l ON t.location_id = l.id
    WHERE t.id = p_task_id AND t.assigned_staff_id = auth.uid();

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Zadanie nie istnieje lub nie masz do niego uprawnień.';
    END IF;

    -- 2. Walidacja kodu QR (jeśli wymagana)
    IF (v_task.validation_config->>'qr_required')::BOOLEAN AND v_task.qr_code_token != p_scanned_qr THEN
        RAISE EXCEPTION 'Nieprawidłowy kod QR dla tej lokalizacji.';
    END IF;

    -- 3. Walidacja GPS (jeśli wymagana)
    IF (v_task.validation_config->>'gps_required')::BOOLEAN THEN
        -- Tworzymy punkt geograficzny z parametrów
        v_user_geo := ST_SetSRID(ST_MakePoint(p_user_lon, p_user_lat), 4326)::geography;
        
        -- Obliczamy dystans w metrach
        v_distance := ST_Distance(v_user_geo, v_task.geo_location);

        IF v_distance > v_task.geofence_radius_meters THEN
            RAISE EXCEPTION 'Jesteś poza wyznaczonym obszarem pracy (Odległość: %m).', ROUND(v_distance::numeric, 2);
        END IF;
    END IF;

    -- 4. Aktualizacja statusu zadania
    UPDATE public.cleaning_tasks
    SET 
        status = 'in_progress',
        started_at = NOW(),
        check_in_metadata = jsonb_build_object(
            'lat', p_user_lat,
            'lon', p_user_lon,
            'distance_m', v_distance,
            'qr_verified', true,
            'timestamp', NOW()
        )
    WHERE id = p_task_id;

    RETURN jsonb_build_object('status', 'success', 'started_at', NOW(), 'distance_m', v_distance);
END;
$function$;
CREATE OR REPLACE FUNCTION public.suggested_invoice_amount(p_material_cost numeric, p_labor_cost numeric, p_surcharge_amount numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT ROUND(
    COALESCE(p_material_cost, 0)
    + COALESCE(p_labor_cost, 0)
    + COALESCE(p_surcharge_amount, 0),
    2
  );
$function$;
CREATE OR REPLACE FUNCTION public.adjust_property_issue_billing(p_issue_id uuid, p_labor_hours numeric, p_labor_cost numeric, p_materials jsonb, p_surcharge_kind text, p_surcharge_amount numeric, p_invoice_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_issue public.property_issues%ROWTYPE;
  v_hours numeric;
  v_kind text;
  v_surcharge numeric;
  v_materials jsonb;
  v_material_total numeric;
  v_labor numeric;
  v_invoice numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;

  SELECT * INTO v_issue
  FROM public.property_issues
  WHERE id = p_issue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF NOT public.is_serwis_dispatcher_or_owner(v_issue.org_id) THEN
    RAISE EXCEPTION 'ISSUE_BILLING_FORBIDDEN';
  END IF;

  IF v_issue.status IS DISTINCT FROM 'resolved' THEN
    RAISE EXCEPTION 'ISSUE_NOT_FOUND';
  END IF;

  IF v_issue.is_invoiced IS TRUE THEN
    RAISE EXCEPTION 'ISSUE_BILLING_LOCKED';
  END IF;

  IF p_surcharge_kind IS NOT NULL AND p_surcharge_kind NOT IN ('on_call', 'urgent') THEN
    RAISE EXCEPTION 'ISSUE_BILLING_INVALID_SURCHARGE';
  END IF;

  v_hours := public.ceil_started_hours(p_labor_hours);
  v_kind := p_surcharge_kind;
  v_surcharge := ROUND(COALESCE(p_surcharge_amount, 0), 2);
  IF v_surcharge < 0 OR COALESCE(p_labor_cost, 0) < 0 OR COALESCE(p_invoice_amount, 0) < 0 THEN
    RAISE EXCEPTION 'ISSUE_BILLING_INVALID_AMOUNT';
  END IF;

  v_materials := CASE WHEN jsonb_typeof(p_materials) = 'array' THEN p_materials ELSE '[]'::jsonb END;
  v_material_total := public.materials_used_total(v_materials);
  v_labor := ROUND(COALESCE(p_labor_cost, 0), 2);
  v_invoice := COALESCE(
    CASE WHEN p_invoice_amount IS NULL THEN NULL ELSE ROUND(p_invoice_amount, 2) END,
    public.suggested_invoice_amount(v_material_total, v_labor, v_surcharge)
  );

  UPDATE public.property_issues
  SET
    labor_hours = v_hours,
    labor_cost = v_labor,
    materials_used = v_materials,
    total_material_cost = v_material_total,
    surcharge_kind = v_kind,
    surcharge_amount = v_surcharge
  WHERE id = p_issue_id;

  INSERT INTO public.property_issue_billing (
    issue_id,
    org_id,
    invoice_amount,
    original,
    captured_at,
    captured_by,
    adjusted_at,
    adjusted_by
  )
  VALUES (
    p_issue_id,
    v_issue.org_id,
    v_invoice,
    jsonb_build_object(
      'labor_hours', v_issue.labor_hours,
      'labor_cost', v_issue.labor_cost,
      'hourly_rate_applied', v_issue.hourly_rate_applied,
      'materials_used', COALESCE(v_issue.materials_used, '[]'::jsonb),
      'total_material_cost', COALESCE(v_issue.total_material_cost, 0),
      'surcharge_amount', v_issue.surcharge_amount,
      'surcharge_kind', v_issue.surcharge_kind,
      'invoice_amount', v_invoice
    ),
    now(),
    auth.uid(),
    now(),
    auth.uid()
  )
  ON CONFLICT (issue_id) DO UPDATE
    SET invoice_amount = EXCLUDED.invoice_amount,
        adjusted_at = now(),
        adjusted_by = auth.uid();
END;
$function$;
CREATE OR REPLACE FUNCTION public.capture_property_issue_billing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice numeric;
BEGIN
  IF NEW.status IS DISTINCT FROM 'resolved' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.property_issue_billing b WHERE b.issue_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  v_invoice := public.suggested_invoice_amount(
    NEW.total_material_cost,
    NEW.labor_cost,
    NEW.surcharge_amount
  );

  INSERT INTO public.property_issue_billing (
    issue_id,
    org_id,
    invoice_amount,
    original,
    captured_at,
    captured_by
  )
  VALUES (
    NEW.id,
    NEW.org_id,
    v_invoice,
    jsonb_build_object(
      'labor_hours', NEW.labor_hours,
      'labor_cost', NEW.labor_cost,
      'hourly_rate_applied', NEW.hourly_rate_applied,
      'materials_used', COALESCE(NEW.materials_used, '[]'::jsonb),
      'total_material_cost', COALESCE(NEW.total_material_cost, 0),
      'surcharge_amount', NEW.surcharge_amount,
      'surcharge_kind', NEW.surcharge_kind,
      'invoice_amount', v_invoice
    ),
    now(),
    auth.uid()
  )
  ON CONFLICT (issue_id) DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.suggested_labor_hours_from_range(p_started_at timestamp with time zone, p_ended_at timestamp with time zone)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_started_at IS NULL OR p_ended_at IS NULL THEN NULL
    WHEN p_ended_at <= p_started_at THEN 0
    ELSE public.ceil_started_hours(
      EXTRACT(EPOCH FROM (p_ended_at - p_started_at)) / 3600.0
    )
  END;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_property_issue_billing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings public.org_serwis_billing_settings;
  v_mgmt boolean;
  v_tech boolean;
  v_resolving boolean;
  v_financial_changed boolean;
BEGIN
  v_mgmt := NEW.org_id IS NOT NULL AND public.is_serwis_dispatcher_or_owner(NEW.org_id);
  v_tech := NEW.org_id IS NOT NULL AND public.is_serwis_technician_role(NEW.org_id);
  v_resolving := NEW.status = 'resolved' AND OLD.status IS DISTINCT FROM 'resolved';

  v_financial_changed :=
    NEW.labor_hours IS DISTINCT FROM OLD.labor_hours
    OR NEW.labor_cost IS DISTINCT FROM OLD.labor_cost
    OR NEW.materials_used IS DISTINCT FROM OLD.materials_used
    OR NEW.total_material_cost IS DISTINCT FROM OLD.total_material_cost
    OR NEW.surcharge_kind IS DISTINCT FROM OLD.surcharge_kind
    OR NEW.surcharge_amount IS DISTINCT FROM OLD.surcharge_amount
    OR NEW.hourly_rate_applied IS DISTINCT FROM OLD.hourly_rate_applied;

  IF OLD.is_invoiced IS TRUE AND v_financial_changed THEN
    RAISE EXCEPTION 'ISSUE_BILLING_LOCKED'
      USING HINT = 'Financial fields cannot change after the issue is invoiced.';
  END IF;

  IF OLD.protocol_number IS NOT NULL THEN
    NEW.protocol_number := OLD.protocol_number;
  ELSIF NEW.status = 'resolved' AND NEW.protocol_number IS NULL AND NEW.org_id IS NOT NULL THEN
    NEW.protocol_number := public.assign_next_protocol_number(
      NEW.org_id,
      COALESCE(NEW.resolved_at, now())
    );
  ELSIF NEW.status IS DISTINCT FROM 'resolved' THEN
    NEW.protocol_number := NULL;
  END IF;

  IF NEW.surcharge_kind IS NULL THEN
    IF NOT v_mgmt THEN
      NEW.surcharge_amount := COALESCE(NEW.surcharge_amount, 0);
    END IF;
  END IF;

  IF v_resolving THEN
    v_settings := public.ensure_org_serwis_billing_settings(NEW.org_id);
    NEW.hourly_rate_applied := COALESCE(NEW.hourly_rate_applied, v_settings.default_hourly_rate);

    IF NEW.labor_hours IS NULL THEN
      NEW.labor_hours := public.suggested_labor_hours_from_range(
        NEW.started_at,
        COALESCE(NEW.resolved_at, now())
      );
    ELSE
      NEW.labor_hours := public.ceil_started_hours(NEW.labor_hours);
    END IF;

    IF NEW.surcharge_kind = 'on_call' THEN
      NEW.surcharge_amount := COALESCE(NEW.surcharge_amount, v_settings.on_call_surcharge);
    ELSIF NEW.surcharge_kind = 'urgent' THEN
      NEW.surcharge_amount := COALESCE(NEW.surcharge_amount, v_settings.urgent_surcharge);
    ELSE
      NEW.surcharge_amount := COALESCE(NEW.surcharge_amount, 0);
    END IF;

    IF NEW.labor_cost IS NULL OR NEW.labor_cost = 0 THEN
      NEW.labor_cost := ROUND(
        COALESCE(NEW.labor_hours, 0) * COALESCE(NEW.hourly_rate_applied, 0),
        2
      );
    END IF;

    NEW.total_material_cost := public.materials_used_total(NEW.materials_used);
    NEW.resolved_at := COALESCE(NEW.resolved_at, now());
  ELSIF NEW.labor_hours IS NOT NULL AND NEW.labor_hours IS DISTINCT FROM OLD.labor_hours THEN
    NEW.labor_hours := public.ceil_started_hours(NEW.labor_hours);
  END IF;

  IF NOT v_mgmt AND v_tech AND NEW.protocol_number IS DISTINCT FROM OLD.protocol_number
     AND OLD.protocol_number IS NOT NULL THEN
    RAISE EXCEPTION 'ISSUE_PROTOCOL_LOCKED';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.swap_vehicle_tire_sets(p_vehicle_id uuid, p_mounted_set_id uuid, p_dismounted_set_id uuid, p_dismounted_to tire_set_location, p_swapped_on date, p_mileage integer DEFAULT NULL::integer, p_notes text DEFAULT NULL::text, p_dismounted_warehouse_number text DEFAULT NULL::text, p_dismounted_receipt_photo_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mounted_from public.tire_set_location;
  v_mounted_name text;
  v_mounted_size text;
  v_swap_id uuid;
  v_first uuid;
  v_second uuid;
BEGIN
  IF p_mounted_set_id = p_dismounted_set_id THEN
    RAISE EXCEPTION 'Mounted and dismounted sets must differ';
  END IF;

  IF p_dismounted_to = 'on_vehicle' THEN
    RAISE EXCEPTION 'Dismounted set cannot stay on the vehicle';
  END IF;

  IF p_mounted_set_id < p_dismounted_set_id THEN
    v_first := p_mounted_set_id;
    v_second := p_dismounted_set_id;
  ELSE
    v_first := p_dismounted_set_id;
    v_second := p_mounted_set_id;
  END IF;

  PERFORM 1 FROM public.vehicle_tire_sets WHERE id = v_first AND vehicle_id = p_vehicle_id FOR UPDATE;
  PERFORM 1 FROM public.vehicle_tire_sets WHERE id = v_second AND vehicle_id = p_vehicle_id FOR UPDATE;

  SELECT s.location, s.name, s.size_info
    INTO v_mounted_from, v_mounted_name, v_mounted_size
  FROM public.vehicle_tire_sets s
  WHERE s.id = p_mounted_set_id
    AND s.vehicle_id = p_vehicle_id;

  IF v_mounted_from IS NULL THEN
    RAISE EXCEPTION 'Mounted tire set not found';
  END IF;

  UPDATE public.vehicle_tire_sets
  SET
    location = p_dismounted_to,
    warehouse_number = COALESCE(NULLIF(btrim(p_dismounted_warehouse_number), ''), warehouse_number),
    receipt_photo_path = COALESCE(p_dismounted_receipt_photo_path, receipt_photo_path)
  WHERE id = p_dismounted_set_id
    AND vehicle_id = p_vehicle_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dismounted tire set not found';
  END IF;

  UPDATE public.vehicle_tire_sets
  SET location = 'on_vehicle'
  WHERE id = p_mounted_set_id
    AND vehicle_id = p_vehicle_id;

  INSERT INTO public.vehicle_tire_swaps (
    vehicle_id,
    swapped_on,
    mileage,
    mounted_set_id,
    dismounted_set_id,
    mounted_from,
    dismounted_to,
    notes,
    performed_by
  )
  VALUES (
    p_vehicle_id,
    p_swapped_on,
    p_mileage,
    p_mounted_set_id,
    p_dismounted_set_id,
    v_mounted_from,
    p_dismounted_to,
    NULLIF(btrim(p_notes), ''),
    auth.uid()
  )
  RETURNING id INTO v_swap_id;

  UPDATE public.vehicles
  SET
    tire_change_date = p_swapped_on,
    tire_info = NULLIF(btrim(concat_ws(' ', v_mounted_name, v_mounted_size)), '')
  WHERE id = p_vehicle_id;

  RETURN v_swap_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_inspection_campaign_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_campaign_id uuid;
  v_min date;
  v_max date;
  v_start time;
  v_end time;
BEGIN
  v_campaign_id := COALESCE(NEW.campaign_id, OLD.campaign_id);
  IF v_campaign_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT MIN(d.visit_date), MAX(d.visit_date)
    INTO v_min, v_max
  FROM public.inspection_campaign_days d
  WHERE d.campaign_id = v_campaign_id;

  IF v_min IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT d.start_time, d.end_time
    INTO v_start, v_end
  FROM public.inspection_campaign_days d
  WHERE d.campaign_id = v_campaign_id
    AND d.kind = 'primary'
  ORDER BY d.visit_date
  LIMIT 1;

  IF v_start IS NULL THEN
    SELECT d.start_time, d.end_time
      INTO v_start, v_end
    FROM public.inspection_campaign_days d
    WHERE d.campaign_id = v_campaign_id
    ORDER BY d.visit_date
    LIMIT 1;
  END IF;

  UPDATE public.inspection_campaigns
  SET start_date = v_min,
      end_date = v_max,
      start_time = v_start,
      end_time = v_end
  WHERE id = v_campaign_id;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_legal_entity_legacy_overlay(p_entity legal_entities, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_reactivated integer := 0;
BEGIN
  PERFORM private.community_set_rpc_flag();

  IF p_entity.kind IN (
    'housing_community'::public.legal_entity_kind,
    'housing_cooperative'::public.legal_entity_kind
  ) THEN
    INSERT INTO public.communities (
      org_id,
      name,
      nip,
      legal_name,
      regon,
      status,
      legal_entity_id
    )
    SELECT
      p_org_id,
      p_entity.short_name,
      p_entity.nip_normalized,
      p_entity.legal_name,
      p_entity.regon_normalized,
      'active',
      p_entity.id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.communities c
      WHERE c.org_id = p_org_id
        AND c.legal_entity_id = p_entity.id
    );

    UPDATE public.communities
    SET
      status = 'active',
      deactivated_at = NULL,
      deactivated_by = NULL
    WHERE org_id = p_org_id
      AND legal_entity_id = p_entity.id
      AND status IS DISTINCT FROM 'active';
    GET DIAGNOSTICS v_reactivated = ROW_COUNT;

    IF v_reactivated > 0 THEN
      UPDATE public.cleaning_locations cl
      SET is_admin_active = true
      FROM public.communities c
      WHERE cl.org_id = p_org_id
        AND cl.community_id = c.id
        AND c.org_id = p_org_id
        AND c.legal_entity_id = p_entity.id
        AND cl.is_admin_active IS DISTINCT FROM true;
    END IF;
  ELSE
    INSERT INTO public.companies (
      org_id,
      name,
      tax_id,
      category,
      address,
      email,
      phone,
      legal_entity_id
    )
    SELECT
      p_org_id,
      p_entity.legal_name,
      p_entity.nip_normalized,
      CASE
        WHEN p_entity.kind = 'property_manager'::public.legal_entity_kind
          THEN 'contractor'::public.company_category
        ELSE 'other'::public.company_category
      END,
      p_entity.seat_full_address,
      p_entity.email,
      p_entity.phone,
      p_entity.id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.companies c
      WHERE c.legal_entity_id = p_entity.id
    );
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.enroll_legal_entity_for_org(p_org_id uuid, p_legal_entity_id uuid, p_is_cleaning boolean DEFAULT false, p_is_maintenance boolean DEFAULT false, p_is_admin boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.legal_entities%ROWTYPE;
  v_enroll public.org_legal_entity_enrollments%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL
     OR (
       NOT public.is_org_management(p_org_id)
       AND NOT public.is_platform_admin()
     )
  THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_ENROLL_FORBIDDEN';
  END IF;

  SELECT * INTO v_row
  FROM public.legal_entities
  WHERE id = p_legal_entity_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_NOT_FOUND';
  END IF;

  INSERT INTO public.org_legal_entity_enrollments (
    org_id,
    legal_entity_id,
    is_cleaning,
    is_maintenance,
    is_admin,
    status
  )
  VALUES (
    p_org_id,
    p_legal_entity_id,
    COALESCE(p_is_cleaning, false),
    COALESCE(p_is_maintenance, false),
    COALESCE(p_is_admin, false),
    'active'
  )
  ON CONFLICT (org_id, legal_entity_id) DO UPDATE
    SET
      is_cleaning = public.org_legal_entity_enrollments.is_cleaning OR EXCLUDED.is_cleaning,
      is_maintenance = public.org_legal_entity_enrollments.is_maintenance OR EXCLUDED.is_maintenance,
      is_admin = public.org_legal_entity_enrollments.is_admin OR EXCLUDED.is_admin,
      status = 'active'
  RETURNING * INTO v_enroll;

  PERFORM public.sync_legal_entity_legacy_overlay(v_row, p_org_id);

  RETURN jsonb_build_object(
    'status', 'enrolled',
    'enrollmentId', v_enroll.id,
    'alreadyEnrolledInThisOrg', true,
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.attach_legal_entity_to_building(p_org_id uuid, p_cleaning_location_id uuid, p_legal_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_loc public.cleaning_locations%ROWTYPE;
  v_master public.locations%ROWTYPE;
  v_owner public.legal_entities%ROWTYPE;
  v_community_id uuid;
  v_community_status text;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL OR NOT public.is_org_management(p_org_id) THEN
    RAISE EXCEPTION 'BUILDING_ENROLL_FORBIDDEN';
  END IF;

  IF p_legal_entity_id IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_REQUIRED_FOR_ATTACH';
  END IF;

  SELECT * INTO v_loc
  FROM public.cleaning_locations
  WHERE id = p_cleaning_location_id
    AND org_id = p_org_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BUILDING_NOT_FOUND';
  END IF;

  SELECT c.id, c.status INTO v_community_id, v_community_status
  FROM public.communities c
  WHERE c.legal_entity_id = p_legal_entity_id
    AND c.org_id = p_org_id
  LIMIT 1;

  IF v_community_status = 'inactive' THEN
    RAISE EXCEPTION 'COMMUNITY_INACTIVE';
  END IF;

  PERFORM public.enroll_legal_entity_for_org(p_org_id, p_legal_entity_id, false, false, false);

  IF v_loc.location_master_id IS NULL THEN
    RAISE EXCEPTION 'BUILDING_MASTER_MISSING';
  END IF;

  SELECT * INTO v_master
  FROM public.locations
  WHERE id = v_loc.location_master_id;

  IF v_master.legal_entity_id IS NOT NULL
     AND v_master.legal_entity_id IS DISTINCT FROM p_legal_entity_id THEN
    SELECT * INTO v_owner FROM public.legal_entities WHERE id = v_master.legal_entity_id;
    RAISE EXCEPTION 'ADDRESS_OWNED_BY_OTHER_ENTITY'
      USING DETAIL = jsonb_build_object(
        'ownerNip', v_owner.nip_normalized,
        'ownerName', v_owner.short_name
      )::text;
  END IF;

  IF v_master.legal_entity_id IS NULL THEN
    UPDATE public.locations
    SET legal_entity_id = p_legal_entity_id
    WHERE id = v_master.id
    RETURNING * INTO v_master;
  END IF;

  SELECT c.id INTO v_community_id
  FROM public.communities c
  WHERE c.legal_entity_id = p_legal_entity_id
    AND c.org_id = p_org_id
  LIMIT 1;

  UPDATE public.cleaning_locations
  SET community_id = COALESCE(community_id, v_community_id)
  WHERE id = v_loc.id
  RETURNING * INTO v_loc;

  RETURN jsonb_build_object(
    'status', 'attached',
    'cleaningLocationId', v_loc.id,
    'locationMasterId', v_master.id,
    'legalEntityId', v_master.legal_entity_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_legal_entity_from_gus(p_org_id uuid, p_kind legal_entity_kind, p_gus jsonb, p_email text, p_phone text, p_short_name text, p_is_cleaning boolean DEFAULT false, p_is_maintenance boolean DEFAULT false, p_is_admin boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nip text;
  v_regon text;
  v_krs text;
  v_legal_name text;
  v_short text;
  v_city text;
  v_postal text;
  v_street text;
  v_building text;
  v_apt text;
  v_voiv text;
  v_county text;
  v_commune text;
  v_seat text;
  v_email text;
  v_phone text;
  v_row public.legal_entities%ROWTYPE;
  v_existing uuid;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;
  IF p_org_id IS NULL OR NOT public.is_org_management(p_org_id) THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_CREATE_FORBIDDEN';
  END IF;
  IF p_gus IS NULL OR jsonb_typeof(p_gus) <> 'object' THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_GUS_PAYLOAD_REQUIRED';
  END IF;

  v_nip := regexp_replace(COALESCE(p_gus ->> 'nip', ''), '[^0-9]', '', 'g');
  v_regon := regexp_replace(COALESCE(p_gus ->> 'regon', ''), '[^0-9]', '', 'g');
  v_krs := NULLIF(regexp_replace(COALESCE(p_gus ->> 'krs', ''), '[^0-9]', '', 'g'), '');
  v_legal_name := NULLIF(btrim(COALESCE(p_gus ->> 'legalName', '')), '');
  v_short := NULLIF(btrim(COALESCE(p_short_name, '')), '');
  v_city := NULLIF(btrim(COALESCE(p_gus ->> 'city', '')), '');
  v_postal := public.normalize_pl_postal(p_gus ->> 'postalCode');
  v_street := NULLIF(btrim(COALESCE(p_gus ->> 'street', '')), '');
  v_building := NULLIF(btrim(COALESCE(p_gus ->> 'buildingNumber', '')), '');
  v_apt := NULLIF(btrim(COALESCE(p_gus ->> 'apartmentNumber', '')), '');
  v_voiv := COALESCE(NULLIF(btrim(COALESCE(p_gus ->> 'voivodeship', '')), ''), 'nieustalone');
  v_county := NULLIF(btrim(COALESCE(p_gus ->> 'county', '')), '');
  v_commune := NULLIF(btrim(COALESCE(p_gus ->> 'commune', '')), '');
  v_email := NULLIF(btrim(COALESCE(p_email, '')), '');
  v_phone := NULLIF(btrim(COALESCE(p_phone, '')), '');
  IF v_short IS NULL THEN v_short := left(COALESCE(v_legal_name, ''), 80); END IF;
  IF v_building IS NULL THEN v_building := 'b.n.'; END IF;
  v_seat := NULLIF(btrim(COALESCE(p_gus ->> 'seatFullAddress', '')), '');
  IF v_seat IS NULL THEN
    v_seat := concat_ws(', ',
      NULLIF(concat_ws(' ', v_street, v_building, v_apt), ''),
      NULLIF(concat_ws(' ', v_postal, v_city), ''));
  END IF;

  IF NOT public.nip_checksum_ok(v_nip)
     OR v_legal_name IS NULL OR v_city IS NULL OR v_postal IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  IF v_email IS NOT NULL
     AND v_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  IF v_phone IS NOT NULL
     AND char_length(regexp_replace(v_phone, '[^0-9+]', '', 'g')) < 9 THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  SELECT id INTO v_existing FROM public.legal_entities WHERE nip_normalized = v_nip;
  IF v_existing IS NOT NULL THEN
    RETURN public.enroll_legal_entity_for_org(
      p_org_id, v_existing, p_is_cleaning, p_is_maintenance, p_is_admin
    ) || jsonb_build_object('status', 'exists_in_domio');
  END IF;

  INSERT INTO public.legal_entities (
    kind, status, nip, regon, krs, short_name, legal_name,
    voivodeship, county, commune, city, postal_code, street,
    building_number, apartment_number, seat_full_address, email, phone,
    gus_legal_form_code, gus_legal_form_name, gus_fetched_at, gus_payload,
    created_without_gus, created_by_org_id, updated_by
  ) VALUES (
    p_kind, 'active', v_nip, v_regon, v_krs, v_short, v_legal_name,
    v_voiv, v_county, v_commune, v_city, v_postal, v_street,
    v_building, v_apt, v_seat, v_email, v_phone,
    NULLIF(btrim(COALESCE(p_gus ->> 'legalFormCode', '')), ''),
    NULLIF(btrim(COALESCE(p_gus ->> 'legalFormName', '')), ''),
    now(), p_gus, false, p_org_id, auth.uid()
  ) RETURNING * INTO v_row;

  PERFORM public.enroll_legal_entity_for_org(p_org_id, v_row.id, p_is_cleaning, p_is_maintenance, p_is_admin);
  PERFORM public.sync_legal_entity_legacy_overlay(v_row, p_org_id);

  RETURN jsonb_build_object(
    'status', 'created',
    'alreadyEnrolledInThisOrg', true,
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.create_legal_entity_unverified(p_org_id uuid, p_kind legal_entity_kind, p_nip text, p_short_name text, p_legal_name text, p_email text, p_phone text, p_city text, p_postal_code text, p_reason text, p_street text DEFAULT NULL::text, p_building_number text DEFAULT NULL::text, p_voivodeship text DEFAULT NULL::text, p_is_cleaning boolean DEFAULT false, p_is_maintenance boolean DEFAULT false, p_is_admin boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nip text;
  v_short text;
  v_legal text;
  v_city text;
  v_postal text;
  v_street text;
  v_building text;
  v_voiv text;
  v_seat text;
  v_email text;
  v_phone text;
  v_existing uuid;
  v_row public.legal_entities%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL
     OR (
       NOT public.is_org_management(p_org_id)
       AND NOT public.is_platform_admin()
     )
  THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_UNVERIFIED_FORBIDDEN';
  END IF;

  IF p_reason IS NULL OR p_reason NOT IN ('gus_unavailable', 'gus_not_configured') THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INVALID_VERIFICATION_REASON';
  END IF;

  v_nip := regexp_replace(COALESCE(p_nip, ''), '[^0-9]', '', 'g');
  v_short := NULLIF(btrim(COALESCE(p_short_name, '')), '');
  v_legal := NULLIF(btrim(COALESCE(p_legal_name, '')), '');
  v_city := NULLIF(btrim(COALESCE(p_city, '')), '');
  v_postal := public.normalize_pl_postal(p_postal_code);
  v_street := NULLIF(btrim(COALESCE(p_street, '')), '');
  v_building := NULLIF(btrim(COALESCE(p_building_number, '')), '');
  v_voiv := NULLIF(btrim(COALESCE(p_voivodeship, '')), '');
  v_email := NULLIF(btrim(COALESCE(p_email, '')), '');
  v_phone := NULLIF(btrim(COALESCE(p_phone, '')), '');

  IF v_short IS NULL THEN
    v_short := left(COALESCE(v_legal, ''), 80);
  END IF;
  IF v_legal IS NULL THEN
    v_legal := v_short;
  END IF;
  IF v_voiv IS NULL THEN
    v_voiv := 'nieustalone';
  END IF;
  IF v_building IS NULL THEN
    v_building := 'b.n.';
  END IF;

  v_seat := concat_ws(
    ', ',
    NULLIF(concat_ws(' ', v_street, v_building), ''),
    NULLIF(concat_ws(' ', v_postal, v_city), '')
  );

  IF NOT public.nip_checksum_ok(v_nip)
     OR v_short IS NULL
     OR v_legal IS NULL
     OR v_city IS NULL
     OR v_postal IS NULL
  THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  IF v_email IS NOT NULL
     AND v_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  IF v_phone IS NOT NULL
     AND char_length(regexp_replace(v_phone, '[^0-9+]', '', 'g')) < 9 THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  SELECT id INTO v_existing
  FROM public.legal_entities
  WHERE nip_normalized = v_nip;

  IF v_existing IS NOT NULL THEN
    RETURN public.enroll_legal_entity_for_org(
      p_org_id,
      v_existing,
      p_is_cleaning,
      p_is_maintenance,
      p_is_admin
    ) || jsonb_build_object('status', 'exists_in_domio');
  END IF;

  PERFORM public.legal_entity_mark_rpc_writer();

  INSERT INTO public.legal_entities (
    kind, status, nip, regon, krs, short_name, legal_name,
    voivodeship, county, commune, city, postal_code, street,
    building_number, apartment_number, seat_full_address, email, phone,
    created_without_gus, gus_fetched_at, verification_status,
    verification_reason, verification_requested_at, created_by_org_id, updated_by
  )
  VALUES (
    p_kind, 'active', v_nip, NULL, NULL, v_short, v_legal,
    v_voiv, NULL, NULL, v_city, v_postal, v_street,
    v_building, NULL, v_seat, v_email, v_phone,
    false, NULL, 'pending_manual', p_reason, now(), p_org_id, auth.uid()
  )
  RETURNING * INTO v_row;

  PERFORM public.enroll_legal_entity_for_org(
    p_org_id, v_row.id, p_is_cleaning, p_is_maintenance, p_is_admin
  );

  RETURN jsonb_build_object(
    'status', 'created_unverified',
    'alreadyEnrolledInThisOrg', true,
    'entity', public.legal_entity_public_json(v_row)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_org_inbound_mailbox_aliases(p_org_id uuid)
 RETURNS SETOF org_inbound_mailboxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_slug text;
  v_mod text;
  v_alias text;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Brak organizacji.';
  END IF;

  IF NOT (SELECT public.is_platform_admin())
     AND NOT (SELECT public.is_org_management(p_org_id)) THEN
    RAISE EXCEPTION 'Brak uprawnień do konfiguracji skrzynek.';
  END IF;

  SELECT lower(regexp_replace(COALESCE(o.slug, ''), '[^a-z0-9]+', '', 'g'))
    INTO v_slug
  FROM public.organizations o
  WHERE o.id = p_org_id;

  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono organizacji.';
  END IF;

  IF v_slug = '' OR length(v_slug) < 2 THEN
    v_slug := substr(replace(p_org_id::text, '-', ''), 1, 12);
  END IF;

  FOREACH v_mod IN ARRAY ARRAY['serwis', 'administracja'] LOOP
    v_alias := 'usterki+' || v_mod || '-' || v_slug;
    IF length(v_alias) > 64 THEN
      v_alias := left(v_alias, 64);
    END IF;

    BEGIN
      UPDATE public.org_inbound_mailboxes
      SET alias_local_part = v_alias
      WHERE org_id = p_org_id
        AND module = v_mod
        AND alias_local_part IS DISTINCT FROM v_alias;
    EXCEPTION
      WHEN unique_violation THEN
        v_alias := left(
          'usterki+' || v_mod || '-' || v_slug || substr(replace(p_org_id::text, '-', ''), 1, 6),
          64
        );
        UPDATE public.org_inbound_mailboxes
        SET alias_local_part = v_alias
        WHERE org_id = p_org_id
          AND module = v_mod
          AND alias_local_part IS DISTINCT FROM v_alias;
    END;
  END LOOP;

  RETURN QUERY
  SELECT *
  FROM public.org_inbound_mailboxes
  WHERE org_id = p_org_id
    AND module IN ('serwis', 'administracja')
  ORDER BY module;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_vehicle_document_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_vehicle_id uuid;
  v_kind public.vehicle_document_kind;
  v_path text;
BEGIN
  v_vehicle_id := COALESCE(NEW.vehicle_id, OLD.vehicle_id);
  v_kind := COALESCE(NEW.kind, OLD.kind);

  SELECT d.storage_path
    INTO v_path
  FROM public.vehicle_documents d
  WHERE d.vehicle_id = v_vehicle_id
    AND d.kind = v_kind
  ORDER BY d.sort_order ASC, d.created_at ASC
  LIMIT 1;

  IF v_kind = 'policy' THEN
    UPDATE public.vehicles SET policy_url = v_path WHERE id = v_vehicle_id;
  ELSE
    UPDATE public.vehicles SET reg_doc_url = v_path WHERE id = v_vehicle_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_vehicle_tire_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_vehicle_id uuid;
  v_name text;
  v_size text;
BEGIN
  v_vehicle_id := COALESCE(NEW.vehicle_id, OLD.vehicle_id);

  SELECT s.name, s.size_info
    INTO v_name, v_size
  FROM public.vehicle_tire_sets s
  WHERE s.vehicle_id = v_vehicle_id
    AND s.location = 'on_vehicle'
  LIMIT 1;

  UPDATE public.vehicles
  SET tire_info = NULLIF(btrim(concat_ws(' ', v_name, v_size)), '')
  WHERE id = v_vehicle_id;

  RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.technician_has_other_forced_issue(p_org_id uuid, p_staff_id uuid, p_except_issue_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.property_issues i
    WHERE i.org_id = p_org_id
      AND i.assigned_staff_id = p_staff_id
      AND i.dispatcher_forced_next = true
      AND i.id IS DISTINCT FROM p_except_issue_id
      AND i.status IN ('open', 'in_progress', 'waiting_for_parts')
  );
$function$;
CREATE OR REPLACE FUNCTION public.enforce_dispatcher_forced_and_gps_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_mgmt boolean;
  v_self boolean;
  v_taking boolean;
  v_starting boolean;
  v_forced_cols_changed boolean;
  v_auto_clear boolean;
BEGIN
  v_org := COALESCE(NEW.org_id, OLD.org_id);
  v_mgmt := v_org IS NOT NULL AND public.is_management_role(v_org);
  v_self := auth.uid() IS NOT NULL
    AND auth.uid() IS NOT DISTINCT FROM COALESCE(NEW.assigned_staff_id, OLD.assigned_staff_id);

  NEW.internal_comments := public.merge_immutable_issue_comments(
    OLD.internal_comments,
    NEW.internal_comments
  );

  IF OLD.gps_start_override IS TRUE THEN
    NEW.gps_start_override := true;
    NEW.gps_start_override_at := OLD.gps_start_override_at;
    NEW.gps_start_override_by := OLD.gps_start_override_by;
    NEW.gps_start_override_distance_m := OLD.gps_start_override_distance_m;
    NEW.gps_start_lat := OLD.gps_start_lat;
    NEW.gps_start_lng := OLD.gps_start_lng;
  ELSIF NEW.gps_start_override IS TRUE THEN
    NEW.gps_start_override_at := COALESCE(NEW.gps_start_override_at, now());
    NEW.gps_start_override_by := COALESCE(NEW.gps_start_override_by, auth.uid());
  ELSE
    NEW.gps_start_override_at := NULL;
    NEW.gps_start_override_by := NULL;
    NEW.gps_start_override_distance_m := NULL;
    NEW.gps_start_lat := NULL;
    NEW.gps_start_lng := NULL;
  END IF;

  IF NEW.status IN ('resolved', 'cancelled') THEN
    NEW.dispatcher_forced_next := false;
  END IF;

  IF NEW.assigned_staff_id IS DISTINCT FROM OLD.assigned_staff_id
     AND NOT (v_mgmt AND NEW.dispatcher_forced_next IS TRUE) THEN
    NEW.dispatcher_forced_next := false;
  END IF;

  IF NEW.dispatcher_forced_next IS NOT TRUE THEN
    NEW.dispatcher_forced_at := NULL;
    NEW.dispatcher_forced_by := NULL;
  ELSIF NEW.dispatcher_forced_next IS TRUE AND OLD.dispatcher_forced_next IS NOT TRUE THEN
    IF NEW.assigned_staff_id IS NULL THEN
      RAISE EXCEPTION 'ISSUE_FORCED_NEXT_NEEDS_ASSIGNEE';
    END IF;
    NEW.dispatcher_forced_at := COALESCE(NEW.dispatcher_forced_at, now());
    NEW.dispatcher_forced_by := COALESCE(NEW.dispatcher_forced_by, auth.uid());
  END IF;

  v_forced_cols_changed :=
    NEW.dispatcher_forced_next IS DISTINCT FROM OLD.dispatcher_forced_next
    OR NEW.dispatcher_forced_at IS DISTINCT FROM OLD.dispatcher_forced_at
    OR NEW.dispatcher_forced_by IS DISTINCT FROM OLD.dispatcher_forced_by;

  v_auto_clear :=
    OLD.dispatcher_forced_next IS TRUE
    AND NEW.dispatcher_forced_next IS NOT TRUE
    AND (
      NEW.status IN ('resolved', 'cancelled')
      OR NEW.assigned_staff_id IS DISTINCT FROM OLD.assigned_staff_id
    );

  IF v_forced_cols_changed AND NOT v_mgmt AND NOT v_auto_clear THEN
    RAISE EXCEPTION 'ISSUE_FORCED_NEXT_FORBIDDEN';
  END IF;

  v_taking :=
    v_self
    AND OLD.assigned_staff_id IS DISTINCT FROM NEW.assigned_staff_id
    AND NEW.assigned_staff_id = auth.uid();
  v_starting :=
    v_self
    AND NEW.status = 'in_progress'
    AND OLD.status IS DISTINCT FROM 'in_progress';

  IF (v_taking OR v_starting)
     AND public.technician_has_other_forced_issue(v_org, auth.uid(), NEW.id) THEN
    RAISE EXCEPTION 'ISSUE_FORCED_NEXT_REQUIRED';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_cleaning_extra_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_cleaning_org_manager(NEW.org_id) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.origin IS DISTINCT FROM 'employee'
       OR NEW.created_by IS DISTINCT FROM auth.uid()
       OR NEW.assigned_staff_id IS DISTINCT FROM auth.uid()
       OR NEW.approval_status IS DISTINCT FROM 'pending_review'
       OR NEW.pay_mode IS DISTINCT FROM 'hourly'
       OR NEW.employee_hourly_rate IS NOT NULL
       OR NEW.client_hourly_rate IS NOT NULL
       OR NEW.employee_fixed_amount IS NOT NULL
       OR NEW.client_fixed_amount IS NOT NULL
       OR NEW.employee_total IS NOT NULL
       OR NEW.client_total IS NOT NULL
       OR NEW.applied_employee_rate IS NOT NULL
       OR NEW.applied_client_rate IS NOT NULL
    THEN
      RAISE EXCEPTION 'Workers can only create pending extra jobs assigned to themselves';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.assigned_staff_id IS DISTINCT FROM auth.uid()
     AND OLD.created_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Workers can only update their own extra jobs';
  END IF;

  IF OLD.org_id IS DISTINCT FROM NEW.org_id
     OR OLD.task_id IS DISTINCT FROM NEW.task_id
     OR OLD.location_id IS DISTINCT FROM NEW.location_id
     OR OLD.origin IS DISTINCT FROM NEW.origin
     OR OLD.created_by IS DISTINCT FROM NEW.created_by
     OR OLD.pay_mode IS DISTINCT FROM NEW.pay_mode
     OR OLD.employee_hourly_rate IS DISTINCT FROM NEW.employee_hourly_rate
     OR OLD.client_hourly_rate IS DISTINCT FROM NEW.client_hourly_rate
     OR OLD.employee_fixed_amount IS DISTINCT FROM NEW.employee_fixed_amount
     OR OLD.client_fixed_amount IS DISTINCT FROM NEW.client_fixed_amount
     OR OLD.applied_employee_rate IS DISTINCT FROM NEW.applied_employee_rate
     OR OLD.applied_client_rate IS DISTINCT FROM NEW.applied_client_rate
     OR OLD.employee_total IS DISTINCT FROM NEW.employee_total
     OR OLD.client_total IS DISTINCT FROM NEW.client_total
     OR OLD.approval_status IS DISTINCT FROM NEW.approval_status
     OR OLD.approved_by IS DISTINCT FROM NEW.approved_by
     OR OLD.approved_at IS DISTINCT FROM NEW.approved_at
     OR OLD.requires_photo IS DISTINCT FROM NEW.requires_photo
     OR OLD.gps_required IS DISTINCT FROM NEW.gps_required
     OR OLD.qr_required IS DISTINCT FROM NEW.qr_required
     OR OLD.biometric_required IS DISTINCT FROM NEW.biometric_required
  THEN
    RAISE EXCEPTION 'Workers cannot change extra job financial or verification fields';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_cleaning_extra_jobs_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_cleaning_work_sessions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_cleaning_org_manager(NEW.org_id) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'Workers can only open their own work sessions';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Workers can only update their own work sessions';
  END IF;

  IF OLD.started_at IS DISTINCT FROM NEW.started_at THEN
    RAISE EXCEPTION 'Workers cannot change session start time';
  END IF;

  IF OLD.is_paid IS DISTINCT FROM NEW.is_paid THEN
    RAISE EXCEPTION 'Workers cannot mark sessions as paid';
  END IF;

  IF OLD.status <> 'open' THEN
    RAISE EXCEPTION 'Workers cannot edit a closed work session';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_fill_location_continuity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_master uuid;
  v_org uuid;
BEGIN
  IF TG_TABLE_NAME = 'unit_inspection_records' THEN
    SELECT ic.location_master_id, ic.org_id INTO v_master, v_org FROM public.inspection_campaigns ic WHERE ic.id = NEW.campaign_id;
    NEW.location_master_id := COALESCE(NEW.location_master_id, v_master);
    NEW.org_id := COALESCE(NEW.org_id, v_org);
    NEW.origin_org_id := COALESCE(NEW.origin_org_id, v_org);
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'location_access' THEN
    SELECT cl.location_master_id INTO v_master FROM public.cleaning_locations cl WHERE cl.id = NEW.location_id;
    NEW.location_master_id := COALESCE(NEW.location_master_id, v_master);
    RETURN NEW;
  END IF;
  SELECT cl.location_master_id, cl.org_id INTO v_master, v_org FROM public.cleaning_locations cl WHERE cl.id = NEW.location_id;
  NEW.location_master_id := COALESCE(NEW.location_master_id, v_master);
  IF TG_TABLE_NAME = 'property_issues' THEN
    NEW.origin_org_id := COALESCE(NEW.origin_org_id, NEW.org_id, v_org);
  ELSIF TG_TABLE_NAME = 'inspection_campaigns' THEN
    NEW.origin_org_id := COALESCE(NEW.origin_org_id, NEW.org_id, v_org);
  ELSE
    NEW.org_id := COALESCE(NEW.org_id, v_org);
    NEW.origin_org_id := COALESCE(NEW.origin_org_id, NEW.org_id, v_org);
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_issue_email_dispatch_set_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_issue_org uuid;
  v_vendor_org uuid;
BEGIN
  SELECT pi.org_id INTO v_issue_org
  FROM public.property_issues pi
  WHERE pi.id = NEW.issue_id;

  SELECT vp.org_id INTO v_vendor_org
  FROM public.vendor_partners vp
  WHERE vp.id = NEW.vendor_id;

  IF v_issue_org IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono zgłoszenia.';
  END IF;
  IF v_vendor_org IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono partnera.';
  END IF;
  IF v_issue_org IS DISTINCT FROM v_vendor_org THEN
    RAISE EXCEPTION 'Partner nie należy do organizacji zgłoszenia.';
  END IF;

  NEW.org_id := v_issue_org;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_legacy_identity_requires_legal_entity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.legal_entity_id IS NULL AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'LEGACY_IDENTITY_LEGAL_ENTITY_REQUIRED'
      USING HINT = 'Create the contractor via NIP lookup (legal_entities), not a direct insert.';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_legal_entities_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.legal_entity_audit_log (legal_entity_id, actor_id, action, after_row)
    VALUES (NEW.id, auth.uid(), 'insert', to_jsonb(NEW) - 'gus_payload');
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.legal_entity_audit_log (legal_entity_id, actor_id, action, before_row, after_row)
    VALUES (NEW.id, auth.uid(), 'update', to_jsonb(OLD) - 'gus_payload', to_jsonb(NEW) - 'gus_payload');
    RETURN NEW;
  ELSE
    INSERT INTO public.legal_entity_audit_log (legal_entity_id, actor_id, action, before_row)
    VALUES (OLD.id, auth.uid(), 'delete', to_jsonb(OLD) - 'gus_payload');
    RETURN OLD;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_legal_entities_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.updated_at := now();
    NEW.updated_by := COALESCE(NEW.updated_by, auth.uid());
    IF NEW.created_without_gus IS TRUE AND NOT public.is_platform_admin() THEN
      RAISE EXCEPTION 'LEGAL_ENTITY_GUS_REQUIRED'
        USING HINT = 'Only a platform admin may create a legal entity that is not in GUS.';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
    NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
    IF current_setting('app.legal_entity_writer', true) = 'rpc' THEN
      RETURN NEW;
    END IF;
    IF NOT public.is_platform_admin() THEN
      RAISE EXCEPTION 'LEGAL_ENTITY_PLATFORM_ADMIN_ONLY'
        USING HINT = 'Registry identity may be corrected only by a Domio platform admin.';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF NOT public.is_platform_admin() THEN
      RAISE EXCEPTION 'LEGAL_ENTITY_PLATFORM_ADMIN_ONLY';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_memberships_guard_owner_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := (SELECT auth.uid());
  v_owner_class text[] := ARRAY['owner', 'admin', 'administrator', 'wlasciciel', 'właściciel'];
  v_new_role text := lower(btrim(COALESCE(NEW.role, '')));
  v_old_role text := CASE WHEN TG_OP = 'UPDATE' THEN lower(btrim(COALESCE(OLD.role, ''))) ELSE NULL END;
  v_new_is_owner boolean := v_new_role = ANY (v_owner_class);
  v_old_is_owner boolean := TG_OP = 'UPDATE' AND v_old_role = ANY (v_owner_class);
BEGIN
  -- Kontekst serwerowy: service_role, edytor SQL, migracje. Bez zmian,
  -- dlatego blokada w create-worker jest nadal potrzebna.
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  -- UPDATE nietykajacy roli (is_active, specializations, GPS) przechodzi.
  -- DELETE nie ma BEFORE UPDATE/INSERT - dezaktywacja i usuniecie czlonka
  -- pozostaja bez zmian.
  IF TG_OP = 'UPDATE' AND v_new_role = v_old_role THEN
    RETURN NEW;
  END IF;

  -- Ani nadanie, ani odebranie roli wlascicielskiej.
  IF NOT v_new_is_owner AND NOT v_old_is_owner THEN
    RETURN NEW;
  END IF;

  IF public.is_platform_admin() THEN
    RETURN NEW;
  END IF;

  -- Dzialajacy sam ma role wlascicielska w tej organizacji -
  -- moze zarowno nadac, jak i odebrac.
  IF EXISTS (
    SELECT 1 FROM public.memberships m
    WHERE m.org_id = NEW.org_id
      AND m.user_id = v_actor
      AND COALESCE(m.is_active, true) = true
      AND lower(btrim(COALESCE(m.role, ''))) = ANY (v_owner_class)
  ) THEN
    RETURN NEW;
  END IF;

  -- Bootstrap zakladania firmy: tylko NADANIE owner samemu sobie,
  -- gdy organizacja nie ma jeszcze wlasciciela. Nie dotyczy odebrania.
  IF v_new_is_owner AND NEW.user_id = v_actor AND NOT EXISTS (
    SELECT 1 FROM public.memberships m
    WHERE m.org_id = NEW.org_id
      AND lower(btrim(COALESCE(m.role, ''))) = ANY (v_owner_class)
      AND (TG_OP = 'INSERT' OR m.id <> NEW.id)
  ) THEN
    RETURN NEW;
  END IF;

  IF v_old_is_owner AND NOT v_new_is_owner THEN
    RAISE EXCEPTION 'Brak uprawnień do odebrania roli właścicielskiej w tej organizacji'
      USING ERRCODE = '42501';
  END IF;

  RAISE EXCEPTION 'Brak uprawnień do nadania roli właścicielskiej w tej organizacji'
    USING ERRCODE = '42501';
END;
$function$;
