CREATE OR REPLACE FUNCTION public.tg_org_subscriptions_grant_fleet_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF lower(btrim(COALESCE(NEW.status, ''))) <> 'active' THEN
    RETURN NEW;
  END IF;
  IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= now() THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.applications a
    WHERE a.id = NEW.app_id
      AND a.is_active = true
      AND public.application_matches_module_slug(a.name, a.domain_url, a.api_url, 'flota')
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM public.grant_fleet_admin_to_org_owners(NEW.org_id);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_profiles_guard_role_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := (SELECT auth.uid());
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.platform_role IS DISTINCT FROM OLD.platform_role THEN
    IF NOT public.is_platform_admin() THEN
      RAISE EXCEPTION 'Brak uprawnień do zmiany roli platformy'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.fleet_role IS DISTINCT FROM OLD.fleet_role THEN
    IF current_setting('app.granting_fleet_admin', true) = 'on'
       AND NEW.fleet_role IS NOT DISTINCT FROM 'admin'::public.fleet_role THEN
      RETURN NEW;
    END IF;

    IF NOT (
      public.is_platform_admin()
      OR EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = v_actor AND p.fleet_role = 'admin'
      )
    ) THEN
      RAISE EXCEPTION 'Brak uprawnień do zmiany roli we flocie'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.tg_resident_order_catalog_location_matches_community()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item_community uuid;
  v_item_org uuid;
  v_loc_community uuid;
  v_loc_org uuid;
BEGIN
  SELECT i.community_id, i.org_id
  INTO v_item_community, v_item_org
  FROM public.resident_order_catalog_items i
  WHERE i.id = NEW.item_id;

  SELECT cl.community_id, cl.org_id
  INTO v_loc_community, v_loc_org
  FROM public.cleaning_locations cl
  WHERE cl.id = NEW.location_id;

  IF v_item_community IS NULL OR v_loc_org IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono pozycji katalogu albo budynku.';
  END IF;

  IF v_loc_org IS DISTINCT FROM v_item_org OR v_loc_community IS DISTINCT FROM v_item_community THEN
    RAISE EXCEPTION 'Budynek nie należy do tej wspólnoty.';
  END IF;

  RETURN NEW;
END;
$function$;
