CREATE OR REPLACE FUNCTION public.update_org_inbound_mailbox(p_id uuid, p_display_address text DEFAULT NULL::text, p_is_enabled boolean DEFAULT NULL::boolean, p_ingest_mode text DEFAULT NULL::text, p_auto_create_threshold numeric DEFAULT NULL::numeric)
 RETURNS org_inbound_mailboxes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  v_box public.org_inbound_mailboxes%ROWTYPE;
  v_mode text;
BEGIN
  SELECT * INTO v_box FROM public.org_inbound_mailboxes WHERE id = p_id;
  IF v_box.id IS NULL THEN RAISE EXCEPTION 'Nie znaleziono skrzynki.'; END IF;
  IF NOT (SELECT public.is_platform_admin()) AND NOT (SELECT public.is_org_management(v_box.org_id)) THEN
    RAISE EXCEPTION 'Brak uprawnień do edycji skrzynki.';
  END IF;
  v_mode := COALESCE(p_ingest_mode, v_box.ingest_mode);
  IF v_mode = 'ai_auto' AND NOT private.inbound_has_ai_auto(v_box.org_id) THEN
    RAISE EXCEPTION 'Tryb automatycznej analizy wymaga planu z funkcjami AI.';
  END IF;
  UPDATE public.org_inbound_mailboxes
  SET display_address = CASE WHEN p_display_address IS NULL THEN display_address ELSE NULLIF(btrim(p_display_address), '') END,
      is_enabled = COALESCE(p_is_enabled, is_enabled),
      ingest_mode = v_mode,
      auto_create_threshold = COALESCE(p_auto_create_threshold, auto_create_threshold)
  WHERE id = p_id
  RETURNING * INTO v_box;
  RETURN v_box;
END;
$function$;
CREATE OR REPLACE FUNCTION public.upsert_billing_org_legal_entity(p_org_id uuid, p_nip text, p_legal_name text, p_city text, p_postal_code text, p_address text, p_phone text, p_gus jsonb, p_kind legal_entity_kind DEFAULT 'company'::legal_entity_kind, p_listed_in_provider_directory boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nip text;
  v_name text;
  v_city text;
  v_postal text;
  v_phone text;
  v_email text;
  v_kind public.legal_entity_kind;
  v_existing uuid;
  v_row public.legal_entities%ROWTYPE;
  v_regon text;
  v_krs text;
  v_street text;
  v_building text;
  v_apt text;
  v_voiv text;
  v_county text;
  v_commune text;
  v_seat text;
  v_short text;
  v_created boolean := false;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_org_id IS NULL OR NOT public.is_org_management(p_org_id) THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_ENROLL_FORBIDDEN';
  END IF;

  v_nip := regexp_replace(COALESCE(p_nip, ''), '[^0-9]', '', 'g');
  v_name := NULLIF(btrim(COALESCE(p_legal_name, '')), '');
  v_city := NULLIF(btrim(COALESCE(p_city, '')), '');
  v_postal := public.normalize_pl_postal(p_postal_code);
  v_phone := regexp_replace(COALESCE(p_phone, ''), '[^0-9+]', '', 'g');
  v_kind := COALESCE(p_kind, 'company'::public.legal_entity_kind);

  SELECT email INTO v_email
  FROM auth.users
  WHERE id = (SELECT auth.uid());
  v_email := NULLIF(btrim(COALESCE(v_email, '')), '');

  IF v_nip = '' THEN
    UPDATE public.organizations
    SET
      legal_entity_id = NULL,
      listed_in_provider_directory = false
    WHERE id = p_org_id;

    RETURN jsonb_build_object(
      'ok', true,
      'status', 'cleared',
      'legalEntityId', NULL,
      'listed', false
    );
  END IF;

  IF NOT public.nip_checksum_ok(v_nip) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_nip');
  END IF;

  SELECT id INTO v_existing
  FROM public.legal_entities
  WHERE nip_normalized = v_nip;

  IF v_existing IS NULL AND (p_gus IS NULL OR jsonb_typeof(p_gus) <> 'object') THEN
    IF p_listed_in_provider_directory THEN
      RETURN jsonb_build_object('ok', false, 'error', 'PROVIDER_DIRECTORY_GUS_REQUIRED');
    END IF;
    UPDATE public.organizations
    SET listed_in_provider_directory = false
    WHERE id = p_org_id
      AND legal_entity_id IS NULL;
    RETURN jsonb_build_object(
      'ok', true,
      'status', 'skipped',
      'legalEntityId', NULL,
      'listed', false
    );
  END IF;

  IF v_existing IS NULL THEN
    IF v_email IS NULL
       OR char_length(v_phone) < 9
       OR v_name IS NULL
       OR v_city IS NULL
       OR v_postal IS NULL
    THEN
      IF p_listed_in_provider_directory THEN
        RETURN jsonb_build_object('ok', false, 'error', 'PROVIDER_DIRECTORY_CONTACT_REQUIRED');
      END IF;
      RETURN jsonb_build_object(
        'ok', true,
        'status', 'skipped',
        'legalEntityId', NULL,
        'listed', false
      );
    END IF;

    v_regon := regexp_replace(COALESCE(p_gus ->> 'regon', ''), '[^0-9]', '', 'g');
    v_krs := NULLIF(regexp_replace(COALESCE(p_gus ->> 'krs', ''), '[^0-9]', '', 'g'), '');
    v_street := NULLIF(btrim(COALESCE(p_gus ->> 'street', '')), '');
    v_building := NULLIF(btrim(COALESCE(p_gus ->> 'buildingNumber', p_gus ->> 'building_number', '')), '');
    v_apt := NULLIF(btrim(COALESCE(p_gus ->> 'apartmentNumber', p_gus ->> 'apartment_number', '')), '');
    v_voiv := NULLIF(btrim(COALESCE(p_gus ->> 'voivodeship', '')), '');
    v_county := NULLIF(btrim(COALESCE(p_gus ->> 'county', '')), '');
    v_commune := NULLIF(btrim(COALESCE(p_gus ->> 'commune', '')), '');
    v_seat := NULLIF(btrim(COALESCE(p_gus ->> 'seatFullAddress', p_gus ->> 'seat_full_address', p_address, '')), '');
    v_short := left(v_name, 80);

    IF v_voiv IS NULL THEN
      v_voiv := 'nieustalone';
    END IF;
    IF v_building IS NULL THEN
      v_building := 'b.n.';
    END IF;
    IF v_seat IS NULL THEN
      v_seat := concat_ws(
        ', ',
        NULLIF(btrim(COALESCE(p_address, '')), ''),
        NULLIF(concat_ws(' ', v_postal, v_city), '')
      );
    END IF;
    IF v_kind = 'housing_cooperative'::public.legal_entity_kind
       AND COALESCE(v_krs, '') !~ '^[0-9]{10}$' THEN
      v_kind := 'company'::public.legal_entity_kind;
    END IF;
    IF NOT public.regon_checksum_ok(v_regon) THEN
      IF p_listed_in_provider_directory THEN
        RETURN jsonb_build_object('ok', false, 'error', 'PROVIDER_DIRECTORY_GUS_REQUIRED');
      END IF;
      RETURN jsonb_build_object(
        'ok', true,
        'status', 'skipped',
        'legalEntityId', NULL,
        'listed', false
      );
    END IF;

    INSERT INTO public.legal_entities (
      kind, status, nip, regon, krs, short_name, legal_name, voivodeship, county, commune,
      city, postal_code, street, building_number, apartment_number, seat_full_address,
      email, phone, gus_legal_form_code, gus_legal_form_name, gus_fetched_at, gus_payload,
      created_without_gus, created_by_org_id, updated_by
    )
    VALUES (
      v_kind, 'active', v_nip, v_regon, v_krs, v_short, v_name, v_voiv, v_county, v_commune,
      v_city, v_postal, v_street, v_building, v_apt, v_seat, v_email, v_phone,
      NULLIF(btrim(COALESCE(p_gus ->> 'legalFormCode', p_gus ->> 'legal_form_code', '')), ''),
      NULLIF(btrim(COALESCE(p_gus ->> 'legalFormName', p_gus ->> 'legal_form_name', '')), ''),
      now(), p_gus, false, p_org_id, auth.uid()
    )
    RETURNING * INTO v_row;

    v_existing := v_row.id;
    v_created := true;
  END IF;

  PERFORM public.link_billing_org_legal_entity_enrollment(p_org_id, v_existing);

  UPDATE public.organizations
  SET
    legal_entity_id = v_existing,
    listed_in_provider_directory = COALESCE(p_listed_in_provider_directory, false)
  WHERE id = p_org_id;

  RETURN jsonb_build_object(
    'ok', true,
    'status', CASE WHEN v_created THEN 'created' ELSE 'linked' END,
    'legalEntityId', v_existing,
    'listed', COALESCE(p_listed_in_provider_directory, false)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.upsert_building_cooperation_link(p_acting_org_id uuid, p_location_master_id uuid, p_community_legal_entity_id uuid, p_cleaning_org_id uuid, p_maintenance_org_id uuid, p_cleaning_issues_to_serwis boolean DEFAULT true, p_skip_admin_triage boolean DEFAULT false)
 RETURNS building_cooperation_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$ BEGIN RETURN private.upsert_building_cooperation_link(p_acting_org_id, p_location_master_id, p_community_legal_entity_id, p_cleaning_org_id, p_maintenance_org_id, p_cleaning_issues_to_serwis, p_skip_admin_triage); END; $function$;
CREATE OR REPLACE FUNCTION public.upsert_company_by_tax_id(p_org_id uuid, p_name text, p_tax_id text, p_category company_category, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS companies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.companies;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'p_org_id is required';
  END IF;

  -- Authenticated users: must be active member of the target org (n8n / service role without uid skips).
  IF auth.uid() IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.memberships m
      WHERE m.org_id = p_org_id
        AND m.user_id = auth.uid()
        AND coalesce(m.is_active, true) = true
    ) THEN
      RAISE EXCEPTION 'forbidden: not a member of this organization'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.companies (name, tax_id, category, email, phone, address, org_id)
  VALUES (
    trim(p_name),
    trim(p_tax_id),
    p_category,
    p_email,
    p_phone,
    p_address,
    p_org_id
  )
  ON CONFLICT ON CONSTRAINT companies_tax_id_org_id_key DO UPDATE SET
    name = EXCLUDED.name,
    category = EXCLUDED.category,
    email = COALESCE(EXCLUDED.email, companies.email),
    phone = COALESCE(EXCLUDED.phone, companies.phone),
    address = COALESCE(EXCLUDED.address, companies.address),
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.upsert_org_serwis_billing_settings(p_org_id uuid, p_default_hourly_rate numeric, p_on_call_surcharge numeric, p_urgent_surcharge numeric, p_protocol_org_code text)
 RETURNS org_serwis_billing_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_code text;
  v_row public.org_serwis_billing_settings;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'ISSUE_AUTH_REQUIRED';
  END IF;
  IF p_org_id IS NULL OR NOT public.is_serwis_dispatcher_or_owner(p_org_id) THEN
    RAISE EXCEPTION 'ISSUE_BILLING_FORBIDDEN';
  END IF;
  IF COALESCE(p_default_hourly_rate, -1) < 0
     OR COALESCE(p_on_call_surcharge, -1) < 0
     OR COALESCE(p_urgent_surcharge, -1) < 0 THEN
    RAISE EXCEPTION 'ISSUE_BILLING_INVALID_AMOUNT';
  END IF;

  v_code := public.normalize_protocol_org_code(p_protocol_org_code);

  IF EXISTS (
    SELECT 1
    FROM public.org_serwis_billing_settings s
    WHERE s.protocol_org_code = v_code
      AND s.org_id IS DISTINCT FROM p_org_id
  ) THEN
    RAISE EXCEPTION 'PROTOCOL_ORG_CODE_TAKEN';
  END IF;

  INSERT INTO public.org_serwis_billing_settings (
    org_id,
    default_hourly_rate,
    on_call_surcharge,
    urgent_surcharge,
    protocol_org_code,
    updated_at,
    updated_by
  )
  VALUES (
    p_org_id,
    ROUND(p_default_hourly_rate, 2),
    ROUND(p_on_call_surcharge, 2),
    ROUND(p_urgent_surcharge, 2),
    v_code,
    now(),
    auth.uid()
  )
  ON CONFLICT (org_id) DO UPDATE
    SET default_hourly_rate = EXCLUDED.default_hourly_rate,
        on_call_surcharge = EXCLUDED.on_call_surcharge,
        urgent_surcharge = EXCLUDED.urgent_surcharge,
        protocol_org_code = EXCLUDED.protocol_org_code,
        updated_at = now(),
        updated_by = auth.uid()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
CREATE OR REPLACE FUNCTION public.user_can_assign_location_legal_entity(p_legal_entity_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.is_platform_admin()
    OR EXISTS (
      SELECT 1
      FROM public.org_legal_entity_enrollments e
      WHERE e.legal_entity_id = p_legal_entity_id
        AND e.status = 'active'
        AND public.is_org_management(e.org_id)
    );
$function$;
CREATE OR REPLACE FUNCTION public.tg_locations_legal_entity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.legal_entity_id IS NOT DISTINCT FROM OLD.legal_entity_id THEN
    RETURN NEW;
  END IF;

  IF public.is_platform_admin() THEN
    RETURN NEW;
  END IF;

  IF NEW.legal_entity_id IS NULL THEN
    IF TG_OP = 'INSERT' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'LOCATION_LEGAL_ENTITY_CLEAR_FORBIDDEN'
      USING HINT = 'Only a platform admin may detach an address from a legal entity.';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.legal_entity_id IS NOT NULL THEN
    RAISE EXCEPTION 'LOCATION_LEGAL_ENTITY_REASSIGN_FORBIDDEN'
      USING HINT = 'An address already belongs to another contractor. Platform admin must reassign.';
  END IF;

  IF NOT public.user_can_assign_location_legal_entity(NEW.legal_entity_id) THEN
    RAISE EXCEPTION 'LOCATION_LEGAL_ENTITY_ASSIGN_FORBIDDEN'
      USING HINT = 'Enroll the contractor in your organisation before attaching buildings.';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.user_can_read_community_contact_board(p_community_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    p_community_id IS NOT NULL
    AND (
      public.is_platform_admin()
      OR public.is_active_org_member(p_org_id)
      OR public.resident_belongs_to_community(p_community_id)
    );
$function$;
CREATE OR REPLACE FUNCTION public.user_can_read_legal_entity(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.is_platform_admin()
    OR EXISTS (
      SELECT 1
      FROM public.org_legal_entity_enrollments e
      WHERE e.legal_entity_id = p_id
        AND public.is_active_org_member(e.org_id)
    )
    OR EXISTS (
      SELECT 1
      FROM public.location_access la
      INNER JOIN public.cleaning_locations cl ON cl.id = la.location_id
      INNER JOIN public.locations loc ON loc.id = cl.location_master_id
      WHERE la.user_id = (SELECT auth.uid())
        AND loc.legal_entity_id = p_id
    );
$function$;
CREATE OR REPLACE FUNCTION public.user_can_see_estate(p_estate_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    p_estate_id IS NOT NULL
    AND (
      EXISTS (
        SELECT 1
        FROM public.estates e
        WHERE e.id = p_estate_id
          AND public.is_org_member(e.created_by_org_id)
      )
      OR EXISTS (
        SELECT 1
        FROM public.estate_members em
        WHERE em.estate_id = p_estate_id
          AND public.is_org_member(em.org_id)
      )
      OR public.has_estate_social_access(p_estate_id)
    );
$function$;
CREATE OR REPLACE FUNCTION public.list_estate_members(p_estate_id uuid)
 RETURNS TABLE(member_id uuid, community_id uuid, org_id uuid, status estate_member_status, community_name text, nip text, invited_by_org_id uuid, consented_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
BEGIN
  PERFORM private.estate_require_actor();

  IF NOT public.user_can_see_estate(p_estate_id) THEN
    RAISE EXCEPTION 'Brak dostępu do tego osiedla.';
  END IF;

  SELECT public.get_my_org_id_safe() INTO v_org;

  RETURN QUERY
  SELECT
    em.id,
    em.community_id,
    em.org_id,
    em.status,
    COALESCE(NULLIF(btrim(c.legal_name), ''), NULLIF(btrim(c.name), ''), 'Wspólnota'),
    c.nip,
    em.invited_by_org_id,
    em.consented_at,
    (em.org_id = v_org)
  FROM public.estate_members em
  JOIN public.communities c ON c.id = em.community_id
  WHERE em.estate_id = p_estate_id
  ORDER BY
    CASE em.status
      WHEN 'accepted' THEN 0
      WHEN 'invited' THEN 1
      ELSE 2
    END,
    5;
END;
$function$;
