AS $function$
  SELECT
    public.is_platform_admin()
    OR EXISTS (
      SELECT 1
      FROM public.org_legal_entity_enrollments e
      WHERE e.legal_entity_id = p_id
        AND e.status = 'active'
        AND public.is_org_management(e.org_id)
    );
$function$;
CREATE OR REPLACE FUNCTION public.apply_legal_entity_gus_data(p_legal_entity_id uuid, p_gus jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.legal_entities%ROWTYPE;
  v_regon text;
  v_krs text;
  v_legal_name text;
  v_city text;
  v_postal text;
  v_street text;
  v_building text;
  v_apt text;
  v_voiv text;
  v_county text;
  v_commune text;
  v_seat text;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_AUTH_REQUIRED';
  END IF;

  IF p_legal_entity_id IS NULL OR NOT public.user_can_verify_legal_entity(p_legal_entity_id) THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_UNVERIFIED_FORBIDDEN';
  END IF;

  IF p_gus IS NULL OR jsonb_typeof(p_gus) <> 'object' THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_GUS_PAYLOAD_REQUIRED';
  END IF;

  SELECT * INTO v_row
  FROM public.legal_entities
  WHERE id = p_legal_entity_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_NOT_FOUND';
  END IF;

  IF v_row.verification_status <> 'pending_manual'::public.legal_entity_verification_status THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_ALREADY_VERIFIED';
  END IF;

  IF NULLIF(btrim(COALESCE(p_gus ->> 'endedAt', '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'GUS_INACTIVE';
  END IF;

  v_regon := NULLIF(regexp_replace(COALESCE(p_gus ->> 'regon', ''), '[^0-9]', '', 'g'), '');
  v_krs := NULLIF(regexp_replace(COALESCE(p_gus ->> 'krs', ''), '[^0-9]', '', 'g'), '');
  v_legal_name := NULLIF(btrim(COALESCE(p_gus ->> 'legalName', '')), '');
  v_city := NULLIF(btrim(COALESCE(p_gus ->> 'city', '')), '');
  v_postal := public.normalize_pl_postal(p_gus ->> 'postalCode');
  v_street := NULLIF(btrim(COALESCE(p_gus ->> 'street', '')), '');
  v_building := NULLIF(btrim(COALESCE(p_gus ->> 'buildingNumber', '')), '');
  v_apt := NULLIF(btrim(COALESCE(p_gus ->> 'apartmentNumber', '')), '');
  v_voiv := NULLIF(btrim(COALESCE(p_gus ->> 'voivodeship', '')), '');
  v_county := NULLIF(btrim(COALESCE(p_gus ->> 'county', '')), '');
  v_commune := NULLIF(btrim(COALESCE(p_gus ->> 'commune', '')), '');

  IF v_voiv IS NULL THEN
    v_voiv := v_row.voivodeship;
  END IF;
  IF v_building IS NULL THEN
    v_building := COALESCE(v_row.building_number, 'b.n.');
  END IF;
  IF v_city IS NULL THEN
    v_city := v_row.city;
  END IF;
  IF v_postal IS NULL THEN
    v_postal := v_row.postal_code;
  END IF;
  IF v_legal_name IS NULL THEN
    v_legal_name := v_row.legal_name;
  END IF;

  v_seat := NULLIF(btrim(COALESCE(p_gus ->> 'seatFullAddress', '')), '');
  IF v_seat IS NULL THEN
    v_seat := concat_ws(
      ', ',
      NULLIF(concat_ws(' ', v_street, v_building, v_apt), ''),
      NULLIF(concat_ws(' ', v_postal, v_city), '')
    );
  END IF;

  IF v_legal_name IS NULL OR v_city IS NULL OR v_postal IS NULL THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  IF v_row.kind = 'housing_cooperative'::public.legal_entity_kind
     AND (v_krs IS NULL OR v_krs !~ '^[0-9]{10}$')
  THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_INCOMPLETE_DATA';
  END IF;

  PERFORM public.legal_entity_mark_rpc_writer();

  UPDATE public.legal_entities
  SET
    regon = v_regon,
    krs = v_krs,
    legal_name = v_legal_name,
    voivodeship = v_voiv,
    county = v_county,
    commune = v_commune,
    city = v_city,
    postal_code = v_postal,
    street = COALESCE(v_street, street),
    building_number = v_building,
    apartment_number = COALESCE(v_apt, apartment_number),
    seat_full_address = v_seat,
    gus_legal_form_code = NULLIF(btrim(COALESCE(p_gus ->> 'legalFormCode', '')), ''),
    gus_legal_form_name = NULLIF(btrim(COALESCE(p_gus ->> 'legalFormName', '')), ''),
    gus_fetched_at = now(),
    gus_payload = p_gus,
    verification_status = 'gus_verified',
    verification_reason = NULL,
    verification_resolved_at = now(),
    verification_resolved_by = auth.uid()
  WHERE id = p_legal_entity_id
  RETURNING * INTO v_row;

  UPDATE public.communities
  SET
    nip = v_row.nip_normalized,
    legal_name = v_row.legal_name,
    regon = v_row.regon_normalized,
    updated_at = now()
  WHERE legal_entity_id = v_row.id;

  UPDATE public.companies
  SET
    tax_id = v_row.nip_normalized,
    address = v_row.seat_full_address,
    updated_at = now()
  WHERE legal_entity_id = v_row.id;

  RETURN jsonb_build_object(
    'status', 'gus_verified',
    'entity', public.legal_entity_public_json(v_row)
  );
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'LEGAL_ENTITY_REGON_TAKEN';
END;
$function$;
CREATE OR REPLACE FUNCTION public.user_has_location_access_docs(p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.location_access la
    WHERE la.location_id = p_location_id
      AND la.user_id = auth.uid()
      AND (la.expires_at IS NULL OR la.expires_at > now())
  );
$function$;
CREATE OR REPLACE FUNCTION public.user_has_module_access(p_module_slug text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    (SELECT auth.uid()) IS NOT NULL
    AND (
      public.is_platform_admin()
      OR EXISTS (
        SELECT 1
        FROM public.applications a
        WHERE a.is_active = true
          AND COALESCE(a.is_free, false) = true
          AND public.application_matches_module_slug(a.name, a.domain_url, a.api_url, p_module_slug)
      )
      OR (
        EXISTS (
          SELECT 1
          FROM public.memberships m
          JOIN public.org_subscriptions s ON s.org_id = m.org_id
          JOIN public.applications a ON a.id = s.app_id
          WHERE m.user_id = (SELECT auth.uid())
            AND COALESCE(m.is_active, true) = true
            AND a.is_active = true
            AND public.application_matches_module_slug(a.name, a.domain_url, a.api_url, p_module_slug)
            AND lower(btrim(COALESCE(s.status, ''))) = 'active'
            AND (s.expires_at IS NULL OR s.expires_at > now())
        )
        AND (
          lower(btrim(COALESCE(p_module_slug, ''))) <> 'flota'
          OR EXISTS (
            SELECT 1
            FROM public.profiles p
            WHERE p.id = (SELECT auth.uid())
              AND lower(btrim(COALESCE(p.fleet_role::text, ''))) IN ('admin', 'driver')
          )
          OR EXISTS (
            SELECT 1
            FROM public.memberships m
            JOIN public.org_subscriptions s ON s.org_id = m.org_id
            JOIN public.applications a ON a.id = s.app_id
            WHERE m.user_id = (SELECT auth.uid())
              AND COALESCE(m.is_active, true) = true
              AND lower(btrim(COALESCE(m.role, ''))) = ANY (
                ARRAY['owner', 'admin', 'administrator', 'wlasciciel', 'właściciel']
              )
              AND a.is_active = true
              AND public.application_matches_module_slug(a.name, a.domain_url, a.api_url, 'flota')
              AND lower(btrim(COALESCE(s.status, ''))) = 'active'
              AND (s.expires_at IS NULL OR s.expires_at > now())
          )
        )
      )
      OR (
        lower(btrim(COALESCE(p_module_slug, ''))) = 'flota'
        AND EXISTS (
          SELECT 1
          FROM public.profiles p
          WHERE p.id = (SELECT auth.uid())
            AND lower(btrim(COALESCE(p.fleet_role::text, ''))) IN ('admin', 'driver')
        )
        AND EXISTS (
          SELECT 1
          FROM public.vehicles v
          JOIN public.org_subscriptions s ON s.org_id = v.org_id
          JOIN public.applications a ON a.id = s.app_id
          WHERE v.assigned_driver_id = (SELECT auth.uid())
            AND a.is_active = true
            AND public.application_matches_module_slug(a.name, a.domain_url, a.api_url, 'flota')
            AND lower(btrim(COALESCE(s.status, ''))) = 'active'
            AND (s.expires_at IS NULL OR s.expires_at > now())
        )
      )
    );
$function$;
CREATE OR REPLACE FUNCTION public.verify_user_consent(p_consent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'private', 'public', 'pg_catalog'
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'Wymagane logowanie'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF NOT (SELECT public.is_platform_admin()) THEN
    RAISE EXCEPTION 'Brak uprawnień'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN private.verify_user_consent(p_consent_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.withdraw_estate_membership(p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.estate_members%ROWTYPE;
  v_estate public.estates%ROWTYPE;
BEGIN
  PERFORM private.estate_require_actor();

  SELECT * INTO v_row
  FROM public.estate_members
  WHERE id = p_member_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Nie znaleziono członkostwa osiedla.';
  END IF;

  SELECT * INTO v_estate FROM public.estates WHERE id = v_row.estate_id;

  IF v_row.status = 'invited' THEN
    IF NOT (
      public.is_org_management(v_row.org_id)
      OR public.is_org_management(v_row.invited_by_org_id)
      OR (v_estate.id IS NOT NULL AND public.is_org_management(v_estate.created_by_org_id))
    ) THEN
      RAISE EXCEPTION 'Brak uprawnień do anulowania zaproszenia.';
    END IF;
  ELSIF v_row.status = 'accepted' THEN
    PERFORM private.estate_require_community_management(v_row.community_id);
  ELSE
    RAISE EXCEPTION 'Tego członkostwa nie można wypisać.';
  END IF;

  UPDATE public.estate_members
  SET status = 'withdrawn',
      consented_at = CASE WHEN v_row.status = 'accepted' THEN now() ELSE consented_at END,
      consented_by = CASE WHEN v_row.status = 'accepted' THEN (SELECT auth.uid()) ELSE consented_by END
  WHERE id = p_member_id;
END;
$function$;

CREATE OR REPLACE VIEW public.cleaner_recent_activity
WITH (security_invoker = true) AS
 SELECT id, task_id, user_id, action_type, notes, created_at
   FROM task_execution_logs
  WHERE user_id = auth.uid() AND created_at >= (now() - '24:00:00'::interval);

CREATE OR REPLACE VIEW public.user_app_access
WITH (security_invoker = true) AS
 SELECT DISTINCT m.user_id, os.app_id, a.name AS app_name, a.domain_url AS app_domain_url,
    a.api_url AS app_api_url, m.org_id, o.name AS org_name, os.status AS subscription_status
   FROM memberships m
     JOIN org_subscriptions os ON os.org_id = m.org_id
     JOIN applications a ON a.id = os.app_id
     JOIN organizations o ON o.id = m.org_id
  WHERE os.status = 'active'::text AND COALESCE(a.is_active, true) = true
    AND (os.expires_at IS NULL OR os.expires_at > now());

CREATE OR REPLACE VIEW public.v_upcoming_deadlines
WITH (security_invoker = true) AS
 SELECT v.id AS vehicle_id, v.org_id, v.reg_no, v.model, 'inspection'::text AS alert_type,
    v.next_inspection AS deadline_date, v.next_inspection - CURRENT_DATE AS days_left,
    p.full_name AS driver_name, p.email AS driver_email
   FROM vehicles v LEFT JOIN profiles p ON p.id = v.assigned_driver_id
UNION ALL
 SELECT v.id, v.org_id, v.reg_no, v.model, 'insurance'::text, v.insurance_expiry,
    v.insurance_expiry - CURRENT_DATE, p.full_name, p.email
   FROM vehicles v LEFT JOIN profiles p ON p.id = v.assigned_driver_id
UNION ALL
 SELECT v.id, v.org_id, v.reg_no, v.model, 'tire_change'::text, v.tire_change_date,
    v.tire_change_date - CURRENT_DATE, p.full_name, p.email
   FROM vehicles v LEFT JOIN profiles p ON p.id = v.assigned_driver_id
  WHERE v.tire_change_date IS NOT NULL;

CREATE OR REPLACE VIEW public.v_active_notifications
WITH (security_invoker = true) AS
 SELECT v.id AS vehicle_id, v.org_id, v.reg_no, v.model, v.assigned_driver_id,
    p.full_name AS driver_name, p.email AS driver_email, nt.type AS alert_type,
    nt.send_to, nt.days_before, nt.subject, nt.body_template, d.deadline_date,
    d.deadline_date - CURRENT_DATE AS days_left
   FROM vehicles v
     LEFT JOIN profiles p ON p.id = v.assigned_driver_id
     JOIN LATERAL (
       SELECT DISTINCT ON (t.type) t.type, t.subject, t.body_template, t.days_before, t.send_to
       FROM notification_templates t
       WHERE t.type = ANY (ARRAY['inspection'::text, 'insurance'::text, 'tire_change'::text])
         AND (t.org_id = v.org_id OR t.org_id IS NULL)
       ORDER BY t.type, (t.org_id IS NOT NULL) DESC
     ) nt ON true
     CROSS JOIN LATERAL (
       SELECT CASE nt.type
         WHEN 'inspection'::text THEN v.next_inspection
         WHEN 'insurance'::text THEN v.insurance_expiry
         WHEN 'tire_change'::text THEN v.tire_change_date
         ELSE NULL::date
       END AS deadline_date
     ) d
  WHERE d.deadline_date IS NOT NULL
    AND d.deadline_date >= CURRENT_DATE
    AND d.deadline_date <= (CURRENT_DATE + nt.days_before);


-- Triggers
DROP TRIGGER IF EXISTS "trg_building_cooperation_links_updated_at" ON public."building_cooperation_links";
CREATE TRIGGER trg_building_cooperation_links_updated_at BEFORE UPDATE ON public.building_cooperation_links FOR EACH ROW EXECUTE FUNCTION handle_updated_at();
DROP TRIGGER IF EXISTS "trg_coop_links_via_rpc" ON public."building_cooperation_links";
CREATE TRIGGER trg_coop_links_via_rpc BEFORE INSERT OR DELETE OR UPDATE ON public.building_cooperation_links FOR EACH ROW EXECUTE FUNCTION private.tg_mandate_tables_via_rpc();
DROP TRIGGER IF EXISTS "trg_building_inspections_set_updated_at" ON public."building_inspections";
