DROP TRIGGER IF EXISTS "vendor_email_inbound_templates_set_updated_at" ON public."vendor_email_inbound_templates";
CREATE TRIGGER vendor_email_inbound_templates_set_updated_at BEFORE UPDATE ON public.vendor_email_inbound_templates FOR EACH ROW EXECUTE FUNCTION handle_updated_at();

