-- Policies
DROP POLICY IF EXISTS "admin_contracts_org_delete" ON public."admin_contracts";
CREATE POLICY "admin_contracts_org_delete" ON public."admin_contracts" AS PERMISSIVE FOR DELETE TO "authenticated" USING (is_org_member(org_id));
DROP POLICY IF EXISTS "admin_contracts_org_insert" ON public."admin_contracts";
CREATE POLICY "admin_contracts_org_insert" ON public."admin_contracts" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (is_org_member(org_id));
DROP POLICY IF EXISTS "admin_contracts_org_select" ON public."admin_contracts";
CREATE POLICY "admin_contracts_org_select" ON public."admin_contracts" AS PERMISSIVE FOR SELECT TO "authenticated" USING (is_org_member(org_id));
DROP POLICY IF EXISTS "admin_contracts_org_update" ON public."admin_contracts";
CREATE POLICY "admin_contracts_org_update" ON public."admin_contracts" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (is_org_member(org_id)) WITH CHECK (is_org_member(org_id));
DROP POLICY IF EXISTS "Platform admin full access applications" ON public."applications";
CREATE POLICY "Platform admin full access applications" ON public."applications" AS PERMISSIVE FOR ALL TO "authenticated" USING (is_platform_admin()) WITH CHECK (is_platform_admin());
DROP POLICY IF EXISTS "Public apps are viewable by everyone" ON public."applications";
CREATE POLICY "Public apps are viewable by everyone" ON public."applications" AS PERMISSIVE FOR SELECT TO public USING ((is_active = true));
DROP POLICY IF EXISTS "Public can read active applications" ON public."applications";
CREATE POLICY "Public can read active applications" ON public."applications" AS PERMISSIVE FOR SELECT TO "anon", "authenticated" USING ((COALESCE(is_active, true) = true));
DROP POLICY IF EXISTS "building_cooperation_links_select" ON public."building_cooperation_links";
CREATE POLICY "building_cooperation_links_select" ON public."building_cooperation_links" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((( SELECT is_platform_admin() AS is_platform_admin) OR ( SELECT is_active_org_member(building_cooperation_links.admin_org_id) AS is_active_org_member) OR ((cleaning_org_id IS NOT NULL) AND ( SELECT is_active_org_member(building_cooperation_links.cleaning_org_id) AS is_active_org_member)) OR ((maintenance_org_id IS NOT NULL) AND ( SELECT is_active_org_member(building_cooperation_links.maintenance_org_id) AS is_active_org_member))));
DROP POLICY IF EXISTS "building_inspections_org_delete" ON public."building_inspections";
CREATE POLICY "building_inspections_org_delete" ON public."building_inspections" AS PERMISSIVE FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = building_inspections.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "building_inspections_org_insert" ON public."building_inspections";
CREATE POLICY "building_inspections_org_insert" ON public."building_inspections" AS PERMISSIVE FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = building_inspections.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "building_inspections_org_select" ON public."building_inspections";
CREATE POLICY "building_inspections_org_select" ON public."building_inspections" AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = building_inspections.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "building_inspections_org_update" ON public."building_inspections";
CREATE POLICY "building_inspections_org_update" ON public."building_inspections" AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = building_inspections.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = building_inspections.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_credentials_org_insert" ON public."ckob_credentials";
CREATE POLICY "ckob_credentials_org_insert" ON public."ckob_credentials" AS PERMISSIVE FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = ckob_credentials.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_credentials_org_update" ON public."ckob_credentials";
CREATE POLICY "ckob_credentials_org_update" ON public."ckob_credentials" AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = ckob_credentials.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = ckob_credentials.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_credentials_service_role_select" ON public."ckob_credentials";
CREATE POLICY "ckob_credentials_service_role_select" ON public."ckob_credentials" AS PERMISSIVE FOR SELECT TO public USING (((auth.jwt() ->> 'role'::text) = 'service_role'::text));
DROP POLICY IF EXISTS "ckob_property_mappings_org_delete" ON public."ckob_property_mappings";
CREATE POLICY "ckob_property_mappings_org_delete" ON public."ckob_property_mappings" AS PERMISSIVE FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM (cleaning_locations cl
     JOIN memberships m ON ((m.org_id = cl.org_id)))
  WHERE ((cl.id = ckob_property_mappings.location_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_property_mappings_org_insert" ON public."ckob_property_mappings";
CREATE POLICY "ckob_property_mappings_org_insert" ON public."ckob_property_mappings" AS PERMISSIVE FOR INSERT TO public WITH CHECK ((EXISTS ( SELECT 1
   FROM (cleaning_locations cl
     JOIN memberships m ON ((m.org_id = cl.org_id)))
  WHERE ((cl.id = ckob_property_mappings.location_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_property_mappings_org_select" ON public."ckob_property_mappings";
CREATE POLICY "ckob_property_mappings_org_select" ON public."ckob_property_mappings" AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM (cleaning_locations cl
     JOIN memberships m ON ((m.org_id = cl.org_id)))
  WHERE ((cl.id = ckob_property_mappings.location_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_property_mappings_org_update" ON public."ckob_property_mappings";
CREATE POLICY "ckob_property_mappings_org_update" ON public."ckob_property_mappings" AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM (cleaning_locations cl
     JOIN memberships m ON ((m.org_id = cl.org_id)))
  WHERE ((cl.id = ckob_property_mappings.location_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM (cleaning_locations cl
     JOIN memberships m ON ((m.org_id = cl.org_id)))
  WHERE ((cl.id = ckob_property_mappings.location_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true)))));
DROP POLICY IF EXISTS "ckob_sync_logs_org_insert" ON public."ckob_sync_logs";
CREATE POLICY "ckob_sync_logs_org_insert" ON public."ckob_sync_logs" AS PERMISSIVE FOR INSERT TO public WITH CHECK ((((auth.jwt() ->> 'role'::text) = 'service_role'::text) OR (EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = ckob_sync_logs.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true))))));
DROP POLICY IF EXISTS "ckob_sync_logs_org_select" ON public."ckob_sync_logs";
CREATE POLICY "ckob_sync_logs_org_select" ON public."ckob_sync_logs" AS PERMISSIVE FOR SELECT TO public USING ((((auth.jwt() ->> 'role'::text) = 'service_role'::text) OR (EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = ckob_sync_logs.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true))))));
DROP POLICY IF EXISTS "Manager Catalog Access" ON public."cleaning_catalog";
CREATE POLICY "Manager Catalog Access" ON public."cleaning_catalog" AS PERMISSIVE FOR ALL TO public USING (check_manager_access(org_id)) WITH CHECK (check_manager_access(org_id));
DROP POLICY IF EXISTS "CORE_Clients_Manage" ON public."cleaning_clients";
CREATE POLICY "CORE_Clients_Manage" ON public."cleaning_clients" AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM get_my_org_and_role() get_my_org_and_role(org_id, role)
  WHERE ((get_my_org_and_role.org_id = cleaning_clients.org_id) AND (get_my_org_and_role.role = ANY (ARRAY['owner'::text, 'manager'::text, 'admin'::text, 'coordinator'::text]))))));
DROP POLICY IF EXISTS "extra_job_photos_delete" ON public."cleaning_extra_job_photos";
CREATE POLICY "extra_job_photos_delete" ON public."cleaning_extra_job_photos" AS PERMISSIVE FOR DELETE TO "authenticated" USING (((uploaded_by = auth.uid()) OR is_cleaning_org_manager(org_id)));
DROP POLICY IF EXISTS "extra_job_photos_insert" ON public."cleaning_extra_job_photos";
CREATE POLICY "extra_job_photos_insert" ON public."cleaning_extra_job_photos" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((uploaded_by = auth.uid()) AND (EXISTS ( SELECT 1
   FROM cleaning_extra_jobs j
  WHERE ((j.id = cleaning_extra_job_photos.extra_job_id) AND (j.org_id = j.org_id) AND (is_cleaning_org_manager(j.org_id) OR (j.assigned_staff_id = auth.uid())))))));
DROP POLICY IF EXISTS "extra_job_photos_select" ON public."cleaning_extra_job_photos";
CREATE POLICY "extra_job_photos_select" ON public."cleaning_extra_job_photos" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM cleaning_extra_jobs j
  WHERE ((j.id = cleaning_extra_job_photos.extra_job_id) AND (is_cleaning_org_manager(j.org_id) OR (j.assigned_staff_id = auth.uid()) OR (j.created_by = auth.uid()))))));
DROP POLICY IF EXISTS "extra_jobs_delete_manager" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_delete_manager" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR DELETE TO "authenticated" USING (is_cleaning_org_manager(org_id));
DROP POLICY IF EXISTS "extra_jobs_insert_manager" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_insert_manager" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (is_cleaning_org_manager(org_id));
DROP POLICY IF EXISTS "extra_jobs_insert_worker" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_insert_worker" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((origin = 'employee'::text) AND (created_by = auth.uid()) AND (assigned_staff_id = auth.uid()) AND is_org_member(org_id)));
DROP POLICY IF EXISTS "extra_jobs_select_org" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_select_org" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((is_cleaning_org_manager(org_id) OR (assigned_staff_id = auth.uid()) OR (created_by = auth.uid())));
DROP POLICY IF EXISTS "extra_jobs_update_manager" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_update_manager" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (is_cleaning_org_manager(org_id)) WITH CHECK (is_cleaning_org_manager(org_id));
DROP POLICY IF EXISTS "extra_jobs_update_worker" ON public."cleaning_extra_jobs";
CREATE POLICY "extra_jobs_update_worker" ON public."cleaning_extra_jobs" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (((assigned_staff_id = auth.uid()) OR (created_by = auth.uid()))) WITH CHECK (((assigned_staff_id = auth.uid()) OR (created_by = auth.uid())));
DROP POLICY IF EXISTS "Inventory_Manager_Access" ON public."cleaning_inventory";
CREATE POLICY "Inventory_Manager_Access" ON public."cleaning_inventory" AS PERMISSIVE FOR ALL TO public USING (is_org_manager(org_id));
DROP POLICY IF EXISTS "Inventory_Staff_View" ON public."cleaning_inventory";
CREATE POLICY "Inventory_Staff_View" ON public."cleaning_inventory" AS PERMISSIVE FOR SELECT TO public USING (has_location_access(location_id));
DROP POLICY IF EXISTS "Manager Inventory Access" ON public."cleaning_inventory";
CREATE POLICY "Manager Inventory Access" ON public."cleaning_inventory" AS PERMISSIVE FOR ALL TO public USING (check_manager_access(org_id)) WITH CHECK (check_manager_access(org_id));
DROP POLICY IF EXISTS "cleaning_locations_select_assigned_or_mgmt" ON public."cleaning_locations";
CREATE POLICY "cleaning_locations_select_assigned_or_mgmt" ON public."cleaning_locations" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((is_org_management(org_id) OR (id IN ( SELECT t.location_id
   FROM cleaning_tasks t
  WHERE (t.assigned_staff_id = ( SELECT auth.uid() AS uid))))));
DROP POLICY IF EXISTS "cleaning_locations_select_org_member" ON public."cleaning_locations";
CREATE POLICY "cleaning_locations_select_org_member" ON public."cleaning_locations" AS PERMISSIVE FOR SELECT TO "authenticated" USING (is_org_member(org_id));
DROP POLICY IF EXISTS "cleaning_locations_select_platform_admin" ON public."cleaning_locations";
CREATE POLICY "cleaning_locations_select_platform_admin" ON public."cleaning_locations" AS PERMISSIVE FOR SELECT TO "authenticated" USING (( SELECT is_platform_admin() AS is_platform_admin));
DROP POLICY IF EXISTS "cleaning_locations_select_resident" ON public."cleaning_locations";
CREATE POLICY "cleaning_locations_select_resident" ON public."cleaning_locations" AS PERMISSIVE FOR SELECT TO "authenticated" USING (has_active_location_access(id));
DROP POLICY IF EXISTS "cleaning_locations_write_management" ON public."cleaning_locations";
CREATE POLICY "cleaning_locations_write_management" ON public."cleaning_locations" AS PERMISSIVE FOR ALL TO "authenticated" USING (is_org_management(org_id)) WITH CHECK (is_org_management(org_id));
DROP POLICY IF EXISTS "Universal Staff Visibility" ON public."cleaning_staff";
CREATE POLICY "Universal Staff Visibility" ON public."cleaning_staff" AS PERMISSIVE FOR SELECT TO public USING ((org_id IN ( SELECT memberships.org_id
   FROM memberships
  WHERE (memberships.user_id = auth.uid()))));
DROP POLICY IF EXISTS "cleaning_staff_write_management" ON public."cleaning_staff";
CREATE POLICY "cleaning_staff_write_management" ON public."cleaning_staff" AS PERMISSIVE FOR ALL TO "authenticated" USING (((org_id IS NOT NULL) AND is_management_role(org_id))) WITH CHECK (((org_id IS NOT NULL) AND is_management_role(org_id)));
DROP POLICY IF EXISTS "cleaning_tasks_policy_final" ON public."cleaning_tasks";
CREATE POLICY "cleaning_tasks_policy_final" ON public."cleaning_tasks" AS PERMISSIVE FOR ALL TO "authenticated" USING ((org_id IN ( SELECT memberships.org_id
   FROM memberships
  WHERE (memberships.user_id = auth.uid())))) WITH CHECK ((org_id IN ( SELECT memberships.org_id
   FROM memberships
  WHERE (memberships.user_id = auth.uid()))));
DROP POLICY IF EXISTS "worker_tasks_master_policy" ON public."cleaning_tasks";
CREATE POLICY "worker_tasks_master_policy" ON public."cleaning_tasks" AS PERMISSIVE FOR ALL TO "authenticated" USING ((org_id IN ( SELECT memberships.org_id
   FROM memberships
  WHERE (memberships.user_id = auth.uid())))) WITH CHECK ((org_id IN ( SELECT memberships.org_id
