  WHERE ((m.org_id = vehicles.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true) AND (lower(COALESCE(m.role, ''::text)) = ANY (ARRAY['owner'::text, 'admin'::text, 'coordinator'::text, 'manager'::text])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM memberships m
  WHERE ((m.org_id = vehicles.org_id) AND (m.user_id = auth.uid()) AND (COALESCE(m.is_active, true) = true) AND (lower(COALESCE(m.role, ''::text)) = ANY (ARRAY['owner'::text, 'admin'::text, 'coordinator'::text, 'manager'::text]))))));
